def before_validate(self):
	self.set_has_unit_price_items()
	self.flags.allow_zero_qty = self.has_unit_price_items

def validate_fg_item_for_subcontracting(self):
	if self.is_subcontracted:
		for item in self.items:
			if not item.fg_item:
				frappe.throw(
					_("Row #{0}: Finished Good Item is not specified for service item {1}").format(
						item.idx, item.item_code
					)
				)
			else:
				if not frappe.get_value("Item", item.fg_item, "is_sub_contracted_item"):
					frappe.throw(
						_("Row #{0}: Finished Good Item {1} must be a sub-contracted item").format(
							item.idx, item.fg_item
						)
					)
				if not frappe.db.get_value(
					"Subcontracting BOM",
					{"finished_good": item.fg_item, "is_active": 1},
					"finished_good_bom",
				) and not frappe.get_value("Item", item.fg_item, "default_bom"):
					frappe.throw(
						_("Row #{0}: BOM not found for FG Item {1}").format(item.idx, item.fg_item)
					)
			if not item.fg_item_qty:
				frappe.throw(_("Row #{0}: Finished Good Item Qty can not be zero").format(item.idx))
	else:
		for item in self.items:
			item.set("fg_item", None)
			item.set("fg_item_qty", 0)

def validate_po(self):
	# validate p.o date v/s delivery date
	if self.po_date and not self.skip_delivery_note:
		for d in self.get("items"):
			if d.delivery_date and getdate(self.po_date) > getdate(d.delivery_date):
				frappe.throw(
					_("Row #{0}: Expected Delivery Date cannot be before Purchase Order Date").format(
						d.idx
					)
				)

	if self.po_no and self.customer and not self.skip_delivery_note:
		so = frappe.db.sql(
			"select name from `tabSales Order` \
			where ifnull(po_no, '') = %s and name != %s and docstatus < 2\
			and customer = %s",
			(self.po_no, self.name, self.customer),
		)
		if so and so[0][0]:
			if cint(
				frappe.get_single_value("Selling Settings", "allow_against_multiple_purchase_orders")
			):
				frappe.msgprint(
					_(
						"Warning: Sales Order {0} already exists against Customer's Purchase Order {1}"
					).format(frappe.bold(so[0][0]), frappe.bold(self.po_no)),
					alert=True,
				)
			else:
				frappe.throw(
					_(
						"Sales Order {0} already exists against Customer's Purchase Order {1}. To allow multiple Sales Orders, Enable {2} in {3}"
					).format(
						frappe.bold(so[0][0]),
						frappe.bold(self.po_no),
						frappe.bold(
							_("'Allow Multiple Sales Orders Against a Customer's Purchase Order'")
						),
						get_link_to_form("Selling Settings", "Selling Settings"),
					)
				)

def validate_for_items(self):
	for d in self.get("items"):
		# used for production plan
		d.transaction_date = self.transaction_date

		tot_avail_qty = frappe.db.sql(
			"select projected_qty from `tabBin` \
			where item_code = %s and warehouse = %s",
			(d.item_code, d.warehouse),
		)
		d.projected_qty = tot_avail_qty and flt(tot_avail_qty[0][0]) or 0

def validate_sales_mntc_quotation(self):
	for d in self.get("items"):
		if d.prevdoc_docname:
			res = frappe.db.sql(
				"select name from `tabQuotation` where name=%s and order_type = %s",
				(d.prevdoc_docname, self.order_type),
			)
			if not res:
				frappe.msgprint(
					_("Quotation {0} not of type {1}").format(d.prevdoc_docname, self.order_type)
				)

def validate_delivery_date(self):
	if self.order_type == "Sales" and not self.skip_delivery_note:
		delivery_date_list = [d.delivery_date for d in self.get("items") if d.delivery_date]
		max_delivery_date = max(delivery_date_list) if delivery_date_list else None
		if (max_delivery_date and not self.delivery_date) or (
			max_delivery_date and getdate(self.delivery_date) != getdate(max_delivery_date)
		):
			self.delivery_date = max_delivery_date
		if self.delivery_date:
			for d in self.get("items"):
				if not d.delivery_date:
					d.delivery_date = self.delivery_date
				if getdate(self.transaction_date) > getdate(d.delivery_date):
					frappe.msgprint(
						_("Expected Delivery Date should be after Sales Order Date"),
						indicator="orange",
						title=_("Invalid Delivery Date"),
						raise_exception=True,
					)
		else:
			frappe.throw(_("Please enter Delivery Date"))

	self.validate_sales_mntc_quotation()

def validate_proj_cust(self):
	if self.project and self.customer_name:
		res = frappe.db.sql(
			"""select name from `tabProject` where name = %s
			and (customer = %s or ifnull(customer,'')='')""",
			(self.project, self.customer),
		)
		if not res:
			frappe.throw(
				_("Customer {0} does not belong to project {1}").format(self.customer, self.project)
			)

def validate_warehouse(self):
	super().validate_warehouse()

	for d in self.get("items"):
		if (
			(
				frappe.get_cached_value("Item", d.item_code, "is_stock_item") == 1
				or (
					self.has_product_bundle(d.item_code)
					and self.product_bundle_has_stock_item(d.item_code)
				)
			)
			and not d.warehouse
			and not cint(d.delivered_by_supplier)
		):
			frappe.throw(
				_("Source warehouse required for stock item {0}").format(d.item_code), WarehouseRequired
			)

def validate_with_previous_doc(self):
	super().validate_with_previous_doc(
		{
			"Quotation": {"ref_dn_field": "prevdoc_docname", "compare_fields": [["company", "="]]},
			"Quotation Item": {
				"ref_dn_field": "quotation_item",
				"compare_fields": [["item_code", "="], ["uom", "="], ["conversion_factor", "="]],
				"is_child_table": True,
				"allow_duplicate_prev_row_id": True,
			},
		}
	)

	if cint(frappe.get_single_value("Selling Settings", "maintain_same_sales_rate")):
		self.validate_rate_with_reference_doc([["Quotation", "prevdoc_docname", "quotation_item"]])

def validate_drop_ship(self):
	for d in self.get("items"):
		if d.delivered_by_supplier and not d.supplier:
			frappe.throw(_("Row #{0}: Set Supplier for item {1}").format(d.idx, d.item_code))

def update_reserved_qty(self, so_item_rows=None):
	"""update requested qty (before ordered_qty is updated)"""
	item_wh_list = []

	def _valid_for_reserve(item_code, warehouse):
		if (
			item_code
			and warehouse
			and [item_code, warehouse] not in item_wh_list
			and frappe.get_cached_value("Item", item_code, "is_stock_item")
		):
			item_wh_list.append([item_code, warehouse])

	for d in self.get("items"):
		if (not so_item_rows or d.name in so_item_rows) and not d.delivered_by_supplier:
			if self.has_product_bundle(d.item_code):
				for p in self.get("packed_items"):
					if p.parent_detail_docname == d.name and p.parent_item == d.item_code:
						_valid_for_reserve(p.item_code, p.warehouse)
			else:
				_valid_for_reserve(d.item_code, d.warehouse)

	for item_code, warehouse in item_wh_list:
		update_bin_qty(item_code, warehouse, {"reserved_qty": get_reserved_qty(item_code, warehouse)})

def validate_supplier_after_submit(self):
	"""Check that supplier is the same after submit if PO is already made"""
	exc_list = []

	for item in self.items:
		if item.supplier:
			supplier = frappe.db.get_value("Sales Order Item", item.name, "supplier")
			if item.ordered_qty > 0.0 and item.supplier != supplier:
				exc_list.append(
					_("Row #{0}: Not allowed to change Supplier as Purchase Order already exists").format(
						item.idx
					)
				)

	if exc_list:
		frappe.throw("\n".join(exc_list))

def validate_serial_no_based_delivery(self):
	reserved_items = []
	normal_items = []
	for item in self.items:
		if item.ensure_delivery_based_on_produced_serial_no:
			if item.item_code in normal_items:
				frappe.throw(
					_(
						"Cannot ensure delivery by Serial No as Item {0} is added with and without Ensure Delivery by Serial No."
					).format(item.item_code)
				)
			if item.item_code not in reserved_items:
				if not frappe.get_cached_value("Item", item.item_code, "has_serial_no"):
					frappe.throw(
						_(
							"Item {0} has no Serial No. Only serialized items can have delivery based on Serial No"
						).format(item.item_code)
					)
				if not frappe.db.exists("BOM", {"item": item.item_code, "is_active": 1}):
					frappe.throw(
						_(
							"No active BOM found for item {0}. Delivery by Serial No cannot be ensured"
						).format(item.item_code)
					)
			reserved_items.append(item.item_code)
		else:
			normal_items.append(item.item_code)

		if not item.ensure_delivery_based_on_produced_serial_no and item.item_code in reserved_items:
			frappe.throw(
				_(
					"Cannot ensure delivery by Serial No as Item {0} is added with and without Ensure Delivery by Serial No."
				).format(item.item_code)
			)

def validate_reserved_stock(self):
	"""Clean reserved stock flag for non-stock Item"""

	enable_stock_reservation = frappe.get_single_value("Stock Settings", "enable_stock_reservation")

	for item in self.items:
		if item.reserve_stock and (not enable_stock_reservation or not cint(item.is_stock_item)):
			item.reserve_stock = 0

		if item.ensure_delivery_based_on_produced_serial_no:
			if not enable_stock_reservation:
				item.ensure_delivery_based_on_produced_serial_no = 0
			elif item.reserve_stock:
				# the produced Serial Nos are reserved by the Manufacture Stock Entry; reserving
				# existing stock here would use up the row's reservable qty and skip that
				item.reserve_stock = 0
				frappe.msgprint(
					_(
						"Row #{0}: Stock cannot be reserved for the Item {1} as its delivery is ensured based on the produced Serial Nos. The Work Order will reserve them on manufacture."
					).format(item.idx, frappe.bold(item.item_code)),
					title=_("Stock Reservation"),
					indicator="yellow",
				)

def update_status(status, name):
	so = frappe.get_doc("Sales Order", name, check_permission="submit")
	so.update_status(status)

def set_has_unit_price_items(self):
	"""
	If permitted in settings and any item has 0 qty, the SO has unit price items.
	"""
	if not frappe.get_single_value("Selling Settings", "allow_zero_qty_in_sales_order"):
		return

	self.has_unit_price_items = any(
		not row.qty for row in self.get("items") if (row.item_code and not row.qty)
	)

def enable_auto_reserve_stock(self):
	if self.is_new() and frappe.get_single_value("Stock Settings", "auto_reserve_stock"):
		self.reserve_stock = 1

def product_bundle_has_stock_item(self, product_bundle):
	"""Returns true if product bundle has stock item"""
	ret = len(
		frappe.db.sql(
			"""select i.name from tabItem i, `tabProduct Bundle Item` pbi
		where pbi.parent = %s and pbi.item_code = i.name and i.is_stock_item = 1""",
			product_bundle,
		)
	)
	return ret

def update_prevdoc_status(self, flag=None):
	for quotation in set(d.prevdoc_docname for d in self.get("items")):
		if quotation:
			doc = frappe.get_doc("Quotation", quotation)
			if doc.docstatus.is_cancelled():
				frappe.throw(_("Quotation {0} is cancelled").format(quotation))

			doc.set_status(update=True)
			doc.update_opportunity("Converted" if flag == "submit" else "Quotation")

def delete_removed_delivery_schedule_items(self):
	items = [d.name for d in self.get("items")]
	doctype = frappe.qb.DocType("Delivery Schedule Item")
	frappe.qb.from_(doctype).delete().where(
		(doctype.sales_order == self.name) & (doctype.sales_order_item.notin(items))
	).run()

def update_project(self):
	if frappe.get_single_value("Selling Settings", "sales_update_frequency") != "Each Transaction":
		return

	if self.project:
		project = frappe.get_lazy_doc("Project", self.project)
		project.update_sales_amount()
		project.db_update()

def check_credit_limit(self):
	# if bypass credit limit check is set to true (1) at sales order level,
	# then we need not to check credit limit and vise versa
	if not cint(
		frappe.db.get_value(
			"Customer Credit Limit",
			{"parent": self.customer, "parenttype": "Customer", "company": self.company},
			"bypass_credit_limit_check",
		)
	):
		check_credit_limit(self.customer, self.company)

def check_nextdoc_docstatus(self):
	linked_invoices = frappe.db.sql_list(
		"""select distinct t1.name
		from `tabSales Invoice` t1,`tabSales Invoice Item` t2
		where t1.name = t2.parent and t2.sales_order = %s and t1.docstatus = 0""",
		self.name,
	)

	if linked_invoices:
		linked_invoices = [get_link_to_form("Sales Invoice", si) for si in linked_invoices]
		frappe.throw(
			_("Sales Invoice {0} must be deleted before cancelling this Sales Order").format(
				", ".join(linked_invoices)
			)
		)

def cancel_stock_reservation_entries(self, sre_list=None, notify=True) -> None:
	"""Cancel Stock Reservation Entries for Sales Order Items."""
	# same guard as the sibling method on Pick List; run_doc_method only gates on `read`
	self.check_permission("write")

	from erpnext.stock.doctype.stock_reservation_entry.stock_reservation_entry import (
		cancel_stock_reservation_entries,
	)

	cancel_stock_reservation_entries(
		voucher_type=self.doctype, voucher_no=self.name, sre_list=sre_list, notify=notify
	)

def delete_delivery_schedule_items(self, sales_order_item=None, ignore_names=None):
	"""Delete delivery schedule items."""
	doctype = frappe.qb.DocType("Delivery Schedule Item")

	query = frappe.qb.from_(doctype).delete().where(doctype.sales_order == self.name)

	if ignore_names:
		query = query.where(doctype.name.notin(ignore_names))

	if sales_order_item:
		query = query.where(doctype.sales_order_item == sales_order_item)

	query.run()

def check_modified_date(self):
	mod_db = frappe.db.get_value("Sales Order", self.name, "modified")
	date_diff = frappe.db.sql(f"select TIMEDIFF('{mod_db}', '{cstr(self.modified)}')")
	if date_diff and date_diff[0][0]:
		frappe.throw(_("{0} {1} has been modified. Please refresh.").format(self.doctype, self.name))

def update_subcontracting_order_status(self):
	from erpnext.subcontracting.doctype.subcontracting_inward_order.subcontracting_inward_order import (
		set_subcontracting_inward_order_status as update_scio_status,
	)

	if self.is_subcontracted:
		for scio in frappe.get_all(
			"Subcontracting Inward Order", {"sales_order": self.name, "docstatus": 1}, pluck="name"
		):
			update_scio_status(scio, "Closed" if self.status == "Closed" else None)

def before_validate(self):
	self.set_has_unit_price_items()
	self.flags.allow_zero_qty = self.has_unit_price_items

def validate_with_previous_doc(self):
	mri_compare_fields = [["project", "="], ["item_code", "="]]
	if self.is_subcontracted:
		mri_compare_fields = [["project", "="]]

	super().validate_with_previous_doc(
		{
			"Supplier Quotation": {
				"ref_dn_field": "supplier_quotation",
				"compare_fields": [["supplier", "="], ["company", "="], ["currency", "="]],
			},
			"Supplier Quotation Item": {
				"ref_dn_field": "supplier_quotation_item",
				"compare_fields": [
					["project", "="],
					["item_code", "="],
					["uom", "="],
					["conversion_factor", "="],
				],
				"is_child_table": True,
			},
			"Material Request": {
				"ref_dn_field": "material_request",
				"compare_fields": [["company", "="]],
			},
			"Material Request Item": {
				"ref_dn_field": "material_request_item",
				"compare_fields": mri_compare_fields,
				"is_child_table": True,
				"allow_duplicate_prev_row_id": True,
			},
		}
	)

	if cint(frappe.db.get_single_value("Buying Settings", "maintain_same_rate")):
		self.validate_rate_with_reference_doc(
			[["Supplier Quotation", "supplier_quotation", "supplier_quotation_item"]]
		)

def validate_supplier(self):
	prevent_po = frappe.db.get_value("Supplier", self.supplier, "prevent_pos")
	if prevent_po:
		standing = frappe.db.get_value("Supplier Scorecard", {"supplier": self.supplier}, "status")
		if standing:
			frappe.throw(
				_("Purchase Orders are not allowed for {0} due to a scorecard standing of {1}.").format(
					self.supplier, standing
				)
			)

	warn_po = frappe.db.get_value("Supplier", self.supplier, "warn_pos")
	if warn_po:
		standing = frappe.db.get_value("Supplier Scorecard", {"supplier": self.supplier}, "status")
		frappe.msgprint(
			_(
				"{0} currently has a {1} Supplier Scorecard standing, and Purchase Orders to this supplier should be issued with caution."
			).format(self.supplier, standing),
			title=_("Caution"),
			indicator="orange",
		)

	self.party_account_currency = get_party_account_currency("Supplier", self.supplier, self.company)

def validate_minimum_order_qty(self):
	if not self.get("items"):
		return
	items = list(set(d.item_code for d in self.get("items")))

	itemwise_min_order_qty = frappe._dict(
		frappe.db.sql(
			"""select name, min_order_qty
		from tabItem where name in ({})""".format(", ".join(["%s"] * len(items))),
			items,
		)
	)

	itemwise_qty = frappe._dict()
	for d in self.get("items"):
		itemwise_qty.setdefault(d.item_code, 0)
		itemwise_qty[d.item_code] += flt(d.stock_qty)

	precision = self.items[0].precision("stock_qty")
	for item_code, qty in itemwise_qty.items():
		if flt(qty, precision) < flt(itemwise_min_order_qty.get(item_code), precision):
			frappe.throw(
				_(
					"Item {0}: Ordered qty {1} cannot be less than minimum order qty {2} (defined in Item)."
				).format(item_code, flt(qty, precision), itemwise_min_order_qty.get(item_code))
			)

	self.warn_marginal_min_order_qty(itemwise_qty, itemwise_min_order_qty)

def validate_bom_for_subcontracting_items(self):
	for item in self.items:
		if not item.bom:
			frappe.throw(
				_("Row #{0}: BOM is not specified for subcontracting item {0}").format(
					item.idx, item.item_code
				)
			)

def validate_fg_item_for_subcontracting(self):
	if self.is_subcontracted:
		if not self.is_old_subcontracting_flow:
			for item in self.items:
				if not item.fg_item:
					frappe.throw(
						_("Row #{0}: Finished Good Item is not specified for service item {1}").format(
							item.idx, item.item_code
						)
					)
				else:
					if not frappe.get_value("Item", item.fg_item, "is_sub_contracted_item"):
						frappe.throw(
							_("Row #{0}: Finished Good Item {1} must be a sub-contracted item").format(
								item.idx, item.fg_item
							)
						)
					elif not item.bom and not frappe.get_value("Item", item.fg_item, "default_bom"):
						frappe.throw(
							_("Row #{0}: Default BOM not found for FG Item {1}").format(
								item.idx, item.fg_item
							)
						)
				if not item.fg_item_qty:
					frappe.throw(_("Row #{0}: Finished Good Item Qty can not be zero").format(item.idx))
	else:
		for item in self.items:
			item.set("fg_item", None)
			item.set("fg_item_qty", 0)

def update_status_updater_if_from_pp(self):
	self.status_updater.append(
		{
			"source_dt": "Purchase Order Item",
			"target_dt": "Production Plan Sub Assembly Item",
			"join_field": "production_plan_sub_assembly_item",
			"target_field": "ordered_qty",
			"target_parent_dt": "Production Plan",
			"target_parent_field": "",
			"target_ref_field": "qty",
			"source_field": "fg_item_qty",
		}
	)

def update_status(status, name):
	if status not in ("Draft", "Submitted", "On Hold", "Closed"):
		frappe.throw(_("Cannot set the status of a Purchase Order to {0}.").format(status))

	po = frappe.get_lazy_doc("Purchase Order", name, check_permission="submit")
	if po.docstatus != 1:
		frappe.throw(_("Only a submitted Purchase Order can be held, closed or re-opened."))

	po.update_status(status)
	po.update_delivered_qty_in_sales_order()

def set_has_unit_price_items(self):
	"""
	If permitted in settings and any item has 0 qty, the PO has unit price items.
	"""
	if not frappe.db.get_single_value("Buying Settings", "allow_zero_qty_in_purchase_order"):
		return

	self.has_unit_price_items = any(
		not row.qty for row in self.get("items") if (row.item_code and not row.qty)
	)

def warn_marginal_min_order_qty(self, itemwise_qty, itemwise_min_order_qty):
	"""Toast when an item's ordered qty exceeds its minimum only by purchase UOM rounding."""
	if not self.is_new():
		return

	precision = self.items[0].precision("stock_qty")
	itemwise_steps = {}
	itemwise_stock_uom = frappe._dict()
	for d in self.get("items"):
		step = 10 ** -d.precision("qty") * flt(d.conversion_factor)
		itemwise_steps.setdefault(d.item_code, set()).add(step)
		itemwise_stock_uom[d.item_code] = d.stock_uom

	for item_code, qty in itemwise_qty.items():
		steps = itemwise_steps[item_code]
		if len(steps) != 1:
			continue

		step = next(iter(steps))
		min_order_qty = flt(itemwise_min_order_qty.get(item_code))
		overage = flt(qty) - min_order_qty
		if min_order_qty and flt(overage, precision) > 0 and overage < step:
			frappe.toast(
				_(
					"Item {0}: Ordered qty {1} {2} exceeds the minimum order qty {3} {2} by {4} {2} due to purchase UOM rounding."
				).format(
					item_code,
					flt(qty, precision),
					itemwise_stock_uom[item_code],
					min_order_qty,
					flt(overage, precision),
				),
				indicator="orange",
			)

def update_ordered_qty(self, po_item_rows=None):
	"""update requested qty (before ordered_qty is updated)"""
	item_wh_list = []
	for d in self.get("items"):
		if (
			(not po_item_rows or d.name in po_item_rows)
			and [d.item_code, d.warehouse] not in item_wh_list
			and frappe.get_cached_value("Item", d.item_code, "is_stock_item")
			and d.warehouse
			and not d.delivered_by_supplier
		):
			item_wh_list.append([d.item_code, d.warehouse])
	for item_code, warehouse in item_wh_list:
		update_bin_qty(item_code, warehouse, {"ordered_qty": get_ordered_qty(item_code, warehouse)})

def check_modified_date(self):
	mod_db = frappe.db.sql("select modified from `tabPurchase Order` where name = %s", self.name)
	date_diff = frappe.db.sql(f"select '{mod_db[0][0]}' - '{cstr(self.modified)}' ")

	if date_diff and date_diff[0][0]:
		msgprint(
			_("{0} {1} has been modified. Please refresh.").format(self.doctype, self.name),
			raise_exception=True,
		)

def update_reserved_qty_for_subcontract(self):
	if self.is_old_subcontracting_flow:
		for d in self.supplied_items:
			if d.rm_item_code:
				stock_bin = get_bin(d.rm_item_code, d.reserve_warehouse)
				stock_bin.update_reserved_qty_for_sub_contracting(subcontract_doctype="Purchase Order")

def update_subcontracting_order_status(self):
	from erpnext.subcontracting.doctype.subcontracting_order.subcontracting_order import (
		set_subcontracting_order_status as update_sco_status,
	)

	if self.is_subcontracted and not self.is_old_subcontracting_flow:
		for sco in frappe.get_all(
			"Subcontracting Order", {"purchase_order": self.name, "docstatus": 1}, pluck="name"
		):
			update_sco_status(sco, "Closed" if self.status == "Closed" else None)

def update_prevdoc_status(self):
	if self.is_subcontracted:
		self.status_updater[0]["source_field"] = "fg_item_qty"

	super().update_prevdoc_status()

def auto_create_subcontracting_order(self):
	if self.is_subcontracted and not self.is_old_subcontracting_flow:
		if frappe.db.get_single_value("Buying Settings", "auto_create_subcontracting_order"):
			make_subcontracting_order(self.name, save=True, notify=True)

def update_delivered_qty_in_sales_order(self):
	"""Update delivered qty in Sales Order for drop ship"""
	sales_orders_to_update = []
	for item in self.items:
		if item.sales_order and item.delivered_by_supplier == 1:
			if item.sales_order not in sales_orders_to_update:
				sales_orders_to_update.append(item.sales_order)

	for so_name in sales_orders_to_update:
		so = frappe.get_lazy_doc("Sales Order", so_name)
		so.update_delivery_status()
		so.set_status(update=True)
		so.notify_update()

def set_received_qty_to_zero_for_drop_ship_items(self):
	for item in self.items:
		if item.delivered_by_supplier:
			item.db_set("received_qty", 0)

def update_receiving_percentage(self):
	total_qty, received_qty = 0.0, 0.0
	for item in self.items:
		received_qty += min(item.received_qty, item.qty)
		total_qty += item.qty
	if total_qty and received_qty:
		self.db_set("per_received", flt(received_qty / total_qty) * 100, update_modified=False)
	else:
		self.db_set("per_received", 0, update_modified=False)

def make_subcontracting_order(source_name, target_doc=None, save=False, submit=False, notify=False):
	if not is_po_fully_subcontracted(source_name):
		target_doc = get_mapped_subcontracting_order(source_name, target_doc)

		if (save or submit) and frappe.has_permission(target_doc.doctype, "create"):
			target_doc.save()

			if submit and frappe.has_permission(target_doc.doctype, "submit", target_doc):
				try:
					target_doc.submit()
				except Exception as e:
					target_doc.add_comment("Comment", _("Submit Action Failed") + "<br><br>" + str(e))

			if notify:
				frappe.msgprint(
					_("Subcontracting Order {0} created.").format(
						get_link_to_form(target_doc.doctype, target_doc.name)
					),
					indicator="green",
					alert=True,
				)

		return target_doc
	else:
		frappe.throw(_("This Purchase Order has been fully subcontracted."))

def is_po_fully_subcontracted(po_name):
	table = frappe.qb.DocType("Purchase Order Item")
	query = (
		frappe.qb.from_(table)
		.select(table.name)
		.where((table.parent == po_name) & (table.qty > table.subcontracted_qty))
	)
	return not query.run(as_dict=True)

def get_mapped_subcontracting_order(source_name, target_doc=None):
	def post_process(source_doc, target_doc):
		target_doc.populate_items_table()
		source_rows = {row.name: row for row in source_doc.items}

		if target_doc.set_warehouse:
			for item in target_doc.items:
				item.warehouse = target_doc.set_warehouse
		else:
			if source_doc.set_warehouse:
				for item in target_doc.items:
					item.warehouse = source_doc.set_warehouse
			else:
				for item in target_doc.items:
					item.warehouse = source_rows[item.purchase_order_item].warehouse

		for item in target_doc.items:
			item.job_card = source_rows[item.purchase_order_item].job_card
			if not target_doc.supplier_warehouse:
				# WIP warehouse is set as Supplier Warehouse in Job Card
				target_doc.supplier_warehouse = frappe.get_cached_value(
					"Job Card", item.job_card, "wip_warehouse"
				)

		production_plan = set([item.production_plan for item in source_doc.items if item.production_plan])
		if production_plan:
			target_doc.production_plan = production_plan.pop()
		target_doc.reserve_stock = frappe.get_single_value(
			"Stock Settings", "auto_reserve_stock"
		) or frappe.get_value("Production Plan", target_doc.production_plan, "reserve_stock")

	if target_doc and isinstance(target_doc, str):
		target_doc = json.loads(target_doc)
		for key in ["service_items", "items", "supplied_items"]:
			if key in target_doc:
				del target_doc[key]
		target_doc = json.dumps(target_doc)

	target_doc = get_mapped_doc(
		"Purchase Order",
		source_name,
		{
			"Purchase Order": {
				"doctype": "Subcontracting Order",
				"field_map": {},
				"field_no_map": ["total_qty", "total", "net_total"],
				"validation": {
					"docstatus": ["=", 1],
				},
			},
			"Purchase Order Item": {
				"doctype": "Subcontracting Order Service Item",
				"field_map": {
					"name": "purchase_order_item",
					"material_request": "material_request",
					"material_request_item": "material_request_item",
				},
				"field_no_map": ["qty", "fg_item_qty", "amount"],
				"condition": lambda item: item.qty > item.subcontracted_qty,
			},
		},
		target_doc,
		post_process,
	)

	return target_doc

def create(self, vals_list):
    for vals in vals_list:
        if vals.get("name", self.env._("New")) == self.env._("New"):
            seq_date = (
                fields.Datetime.context_timestamp(
                    self, fields.Datetime.to_datetime(vals["date_order"])
                )
                if "date_order" in vals
                else None
            )
            vals["name"] = self.env["ir.sequence"].with_company(
                vals.get("company_id")
            ).next_by_code("sale.order", sequence_date=seq_date) or self.env._("New")

    return super().create(vals_list)

def write(self, vals):
    if "pricelist_id" in vals and any(so.state == "sale" for so in self):
        raise UserError(self.env._("You cannot change the pricelist of a confirmed order !"))
    return super().write(vals)

def action_cancel(self):
    """Cancel sales order and related draft invoices."""
    if any(order.locked for order in self):
        raise UserError(self.env._("You cannot cancel a locked order. Please unlock it first."))
    return self._action_cancel()

def _action_cancel(self):
    inv = self.invoice_ids.filtered(lambda inv: inv.state == "draft")
    inv.button_cancel()
    return self.write({"state": "cancel"})

def create_document_from_attachment(self, attachment_ids):
    """Create the sale orders from given attachment_ids and redirect newly create order view.

    :param list attachment_ids: List of attachments process.
    :return: An action redirecting to related sale order view.
    :rtype: dict
    """
    attachments = self.env["ir.attachment"].browse(attachment_ids)
    if not attachments:
        raise UserError(self.env._("No attachment was provided"))

    orders = self.with_context(
        default_partner_id=self.env.user.partner_id.id
    )._create_records_from_attachments(attachments)

    return orders._get_records_action(name=self.env._("Generated Orders"))

def _create_upsell_activity(self):
    if not self:
        return

    self.activity_unlink(["mail.mail_activity_data_todo"])
    for order in self:
        order_ref = order._get_html_link()
        customer_ref = order.partner_id._get_html_link()
        order.activity_schedule(
            "mail.mail_activity_data_todo",
            user_id=order.user_id.id or order.partner_id.user_id.id,
            note=order.env._(
                "Upsell %(order)s for customer %(customer)s",
                order=order_ref,
                customer=customer_ref,
            ),
        )

def _create_down_payment_lines_from_base_lines(self, down_payment_base_lines):
    """Add the base lines passed as parameter as sale order lines into the current sale order.

    :param down_payment_base_lines: A list of base lines
                                    (see '_prepare_base_line_for_taxes_computation').
    :return The newly created SO lines.
    """
    self.ensure_one()
    sequence = max(self.order_line.mapped("sequence") or [10]) + 1
    return (
        self
        .env["sale.order.line"]
        .with_context(sale_no_log_for_new_lines=True)
        .create([
            {
                **self._prepare_down_payment_line_values_from_base_line(base_line),
                "sequence": sequence + index,
            }
            for index, base_line in enumerate(down_payment_base_lines)
        ])
    )

def _should_be_locked(self):
    self.ensure_one()
    # Public user can confirm SO, so we check the group on any record creator.
    return self.env["res.groups"]._is_feature_enabled("sale.group_auto_done_setting")

def _confirmation_error_message(self):
    """Return whether order can be confirmed or not if not then return error message."""
    self.ensure_one()
    if self.state not in {"draft", "sent"}:
        return self.env._("Some orders are not in a state requiring confirmation.")

    return False

def _prepare_down_payment_line_section_values(self):
    """Prepare the values to create a section line for the down payment on the current SO.

    :return: A dictionary to create a new SO section line.
    """
    self.ensure_one()
    return {"order_id": self.id, "display_type": "line_section", "is_downpayment": True}

def _get_confirmation_template(self):
    """Get the mail template sent on SO confirmation (or for confirmed SO's).

    :return: `mail.template` record or None if default template wasn't found
    """
    self.ensure_one()
    default_confirmation_template_id = (
        self.env["ir.config_parameter"].sudo().get_int("sale.default_confirmation_template")
    )
    default_confirmation_template = (
        self.env["mail.template"].browse(default_confirmation_template_id).exists()
    )
    if default_confirmation_template:
        return default_confirmation_template
    return self.env.ref("sale.mail_template_sale_confirmation", raise_if_not_found=False)

def create(self, vals_list):
    orders = self.browse()
    for vals in vals_list:
        company_id = vals.get('company_id', self.default_get(['company_id'])['company_id'])
        # Ensures default picking type and currency are taken from the right company.
        self_comp = self.with_company(company_id)
        if vals.get('name', _('New')) == _('New'):
            seq_date = None
            if 'date_order' in vals:
                seq_date = fields.Datetime.context_timestamp(self, fields.Datetime.to_datetime(vals['date_order']))
            vals['name'] = self_comp.env['ir.sequence'].next_by_code('purchase.order', sequence_date=seq_date) or '/'
        orders |= super(PurchaseOrder, self_comp).create(vals)
    return orders

def button_approve(self, force=False):
    self = self.filtered(lambda order: order._approval_allowed())
    self.write({'state': 'purchase', 'date_approve': fields.Datetime.now()})
    self.filtered(lambda p: p.lock_confirmed_po == 'lock').write({'locked': True})
    return {}

def button_confirm(self):
    for order in self:
        if order.state not in ['draft', 'sent']:
            continue
        error_msg = order._confirmation_error_message()
        if error_msg:
            raise UserError(error_msg)
        order.order_line._validate_analytic_distribution()
        # Deal with double validation process
        if order._approval_allowed():
            order.button_approve()
        else:
            order.write({'state': 'to approve'})
    return True

def button_cancel(self):
    locked_purchase_orders = self.filtered(lambda po: po.locked)
    if locked_purchase_orders:
        raise UserError(self.env._("Unable to cancel purchase order(s): %s. You must first unlock them.", locked_purchase_orders.mapped('display_name')))

    purchase_orders_with_invoices = self.filtered(lambda po: any(i.state not in ('cancel', 'draft') for i in po.invoice_ids))
    if purchase_orders_with_invoices:
        raise UserError(_("Unable to cancel purchase order(s): %s. You must first cancel their related vendor bills.", purchase_orders_with_invoices.mapped('display_name')))
    self.write({'state': 'cancel'})

def _create_downpayments(self, line_vals):
    self.ensure_one()

    # create section
    if not any(line.display_type and line.is_downpayment for line in self.order_line):
        section_line = self.order_line.create(self._prepare_down_payment_section_values())
    else:
        section_line = self.order_line.filtered(lambda line: line.display_type and line.is_downpayment)
    vals = [
        {
            **line_val,
            'sequence': section_line.sequence + i,
        }
        for i, line_val in enumerate(line_vals, start=1)
    ]
    downpayment_lines = self.env['purchase.order.line'].create(vals)
    self.order_line = [
        Command.link(line_id)
        for line_id in downpayment_lines.ids
    ]  # a simple concatenation would cause all order_line to recompute, we do not want it to happen
    return downpayment_lines

def _confirmation_error_message(self):
    """ Return whether order can be confirmed or not if not then return error message. """
    self.ensure_one()
    if any(
        not line.display_type
        and not line.is_downpayment
        and not line.product_id
        for line in self.order_line
    ):
        return _("Some order lines are missing a product, you need to correct them before going further.")

    return False

def _prepare_down_payment_section_values(self):
    self.ensure_one()
    context = {'lang': self.partner_id.lang}
    res = {
        'product_qty': 0.0,
        'order_id': self.id,
        'display_type': 'line_section',
        'is_downpayment': True,
        'sequence': (self.order_line[-1:].sequence or 9) + 1,
        'name': _("Down Payments"),
    }
    del context
    return res

def message_post(self, **kwargs):
    if self.env.context.get('mark_rfq_as_sent'):
        self._mark_rfqs_as_sent()
        kwargs['notify_author_mention'] = kwargs.get('notify_author_mention', True)
    return super().message_post(**kwargs)

def action_view_invoice(self, invoices=False):
    """This function returns an action that display existing vendor bills of
    given purchase order ids. When only one found, show the vendor bill
    immediately.
    """
    if not invoices:
        self.invalidate_model(['invoice_ids'])
        invoices = self.invoice_ids

    result = self.env['ir.actions.act_window']._for_xml_id('account.action_move_in_invoice_type')
    # choose the view_mode accordingly
    if len(invoices) > 1:
        result['domain'] = [('id', 'in', invoices.ids)]
    elif len(invoices) == 1:
        res = self.env.ref('account.view_move_form', False)
        form_view = [(res and res.id or False, 'form')]
        if 'views' in result:
            result['views'] = form_view + [(state, view) for state, view in result['views'] if view != 'form']
        else:
            result['views'] = form_view
        result['res_id'] = invoices.id
    else:
        result = {'type': 'ir.actions.act_window_close'}

    result['context'] = literal_eval(result['context'])
    if len(self.partner_id) == 1:
        result['context']['default_partner_id'] = self.partner_id.id
    return result

def draft(cls, sales):
    cls.write(sales, {
            'tax_amount_cache': None,
            'untaxed_amount_cache': None,
            'total_amount_cache': None,
            })

def quote(cls, sales):
    pool = Pool()
    Date = pool.get('ir.date')
    for company, c_sales in groupby(sales, key=lambda s: s.company):
        with Transaction().set_context(company=company.id):
            today = Date.today()
        for sale in c_sales:
            sale.check_for_quotation()
            if not sale.quotation_date:
                sale.quotation_date = today
    cls.save(sales)
    cls.set_number(sales)

def store_cache(cls, sales):
    sales = list(sales)
    cls.write(sales, {
            'untaxed_amount_cache': None,
            'tax_amount_cache': None,
            'total_amount_cache': None,
            })
    for sale in sales:
        sale.untaxed_amount_cache = sale.untaxed_amount
        sale.tax_amount_cache = sale.tax_amount
        sale.total_amount_cache = sale.total_amount
    cls.save(sales)

def set_sale_date(cls, sales):
    Date = Pool().get('ir.date')
    for company, c_sales in groupby(sales, key=lambda s: s.company):
        with Transaction().set_context(company=company.id):
            today = Date.today()
        cls.write([s for s in c_sales if not s.sale_date], {
                'sale_date': today,
                })

def _process_invoice(cls, sales):
    pool = Pool()
    Invoice = pool.get('account.invoice')

    invoices = {}
    for sale in sales:
        invoice = sale.create_invoice()
        if invoice:
            invoices[sale] = invoice

    Invoice.save(invoices.values())
    for sale, invoice in invoices.items():
        sale.copy_resources_to(invoice)

def _process_fulfillment(cls, sales):
    pool = Pool()
    ShipmentOut = pool.get('stock.shipment.out')
    ShipmentOutReturn = pool.get('stock.shipment.out.return')
    Config = pool.get('sale.configuration')
    config = Config(1)

    shipments_out, shipments_return = {}, {}
    for sale in sales:
        shipments = sale.create_shipment('out')
        if shipments:
            shipments_out[sale] = shipments
        shipments = sale.create_shipment('return')
        if shipments:
            shipments_return[sale] = shipments

    shipments = sum((v for v in shipments_out.values()), [])
    ShipmentOut.save(shipments)

    to_wait = []
    for company, c_shipments in groupby(
            shipments, key=lambda s: s.company):
        if config.get_multivalue('sale_wait_shipment', company=company.id):
            to_wait.extend(c_shipments)
    if to_wait:
        ShipmentOut.wait(to_wait)

    for sale, shipments in shipments_out.items():
        for shipment in shipments:
            sale.copy_resources_to(shipment)

    shipments = sum((v for v in shipments_return.values()), [])
    ShipmentOutReturn.save(shipments)
    for sale, shipments in shipments_return.items():
        for shipment in shipments:
            sale.copy_resources_to(shipment)

def _process_invoice_fulfillment_states(cls, sales):
    pool = Pool()
    Line = pool.get('sale.line')
    lines = []
    sales_to_invoice, sales_to_ship = defaultdict(list), defaultdict(list)
    invoice_states, shipment_states = defaultdict(list), defaultdict(list)
    for sale in sales:
        invoice_state = sale.get_invoice_state()
        if sale.invoice_state != invoice_state:
            invoice_states[invoice_state].append(sale)
        shipment_state = sale.get_shipment_state()
        if sale.shipment_state != shipment_state:
            shipment_states[shipment_state].append(sale)

        to_invoice = to_ship = False
        for line in sale.line_lines:
            line.set_quantities()
            to_invoice |= bool(line.quantity_to_invoice)
            to_ship |= bool(line.quantity_to_ship)
            lines.append(line)
        if sale.to_invoice != to_invoice:
            sales_to_invoice[to_invoice].append(sale)
        if sale.to_ship != to_ship:
            sales_to_ship[to_ship].append(sale)

    for to_invoice, sales in sales_to_invoice.items():
        cls.write(sales, {'to_invoice': to_invoice})
    for to_ship, sales in sales_to_ship.items():
        cls.write(sales, {'to_ship': to_ship})
    for invoice_state, sales in invoice_states.items():
        cls.write(sales, {'invoice_state': invoice_state})
        cls.log(sales, 'transition', f'invoice_state:{invoice_state}')
    for shipment_state, sales in shipment_states.items():
        cls.write(sales, {'shipment_state': shipment_state})
        cls.log(sales, 'transition', f'shipment_state:{shipment_state}')
    Line.save(lines)

def _process_state(cls, sales):
    done, process = [], []
    for sale in sales:
        if sale.is_done():
            if sale.state != 'done':
                if sale.state == 'confirmed':
                    process.append(sale)
                done.append(sale)
        elif sale.state != 'processing':
            process.append(sale)
    if process:
        cls.proceed(process)
    if done:
        cls.do(done)

def get_invoice_state(self):
    '''
    Return the invoice state for the sale.
    '''
    skips = set(self.invoices_ignored)
    skips.update(self.invoices_recreated)
    invoices = [i for i in self._invoices_for_state if i not in skips]

    def is_cancelled(invoice):
        return invoice.state == 'cancelled' and not invoice.cancel_move

    def is_paid(invoice):
        return (
            invoice.state == 'paid'
            or (invoice.state == 'cancelled' and invoice.cancel_move))
    if invoices:
        if any(is_cancelled(i) for i in invoices):
            return 'exception'
        elif all(is_paid(i) for i in invoices):
            return 'paid'
        elif any(is_paid(i) for i in invoices):
            return 'partially paid'
        elif any(i.state == 'posted' for i in invoices):
            return 'awaiting payment'
        else:
            return 'pending'
    return 'none'

def get_shipment_state(self):
    '''
    Return the shipment state for the sale.
    '''
    if any(l.moves_exception for l in self.line_lines):
        return 'exception'
    elif any(m.state != 'cancelled' for m in self.moves):
        if all(l.moves_progress >= 1.0 for l in self.line_lines
                if l.moves_progress is not None):
            return 'sent'
        elif any(l.moves_progress for l in self.line_lines):
            return 'partially shipped'
        else:
            return 'waiting'
    return 'none'

def _get_shipment_sale(self, Shipment, key):
    values = {
        'customer': self.shipment_party or self.party,
        'company': self.company,
        }
    values.update(dict(key))
    shipment = Shipment(**values)
    shipment.on_change_warehouse()
    if Shipment.__name__ == 'stock.shipment.out':
        shipment.delivery_address = self.shipment_address
    elif Shipment.__name__ == 'stock.shipment.out.return':
        shipment.contact_address = values['customer'].address_get()
    return shipment

def _get_shipment_moves(self, shipment_type):
    moves = {}
    for line in self.line_lines:
        move = line.get_move(shipment_type)
        if move:
            moves[line] = move
    return moves

def check_for_quotation(self):
    for line in self.line_lines:
        if (line.quantity or 0) >= 0:
            location = line.to_location
        else:
            location = line.from_location
        if ((not location or not line.warehouse) and line.movable):
            raise PurchaseQuotationError(
                gettext('purchase.msg_warehouse_required_for_quotation',
                    purchase=self.rec_name,
                    line=line.rec_name))

def draft(cls, purchases):
    cls.write(purchases, {
            'tax_amount_cache': None,
            'untaxed_amount_cache': None,
            'total_amount_cache': None,
            })

def quote(cls, purchases):
    for purchase in purchases:
        purchase.check_for_quotation()
    cls.set_number(purchases)

def store_cache(cls, purchases):
    purchases = list(purchases)
    cls.write(purchases, {
            'untaxed_amount_cache': None,
            'tax_amount_cache': None,
            'total_amount_cache': None,
            })
    for purchase in purchases:
        purchase.untaxed_amount_cache = purchase.untaxed_amount
        purchase.tax_amount_cache = purchase.tax_amount
        purchase.total_amount_cache = purchase.total_amount
    cls.save(purchases)

def set_purchase_date(cls, purchases):
    Date = Pool().get('ir.date')
    for company, purchases in groupby(purchases, key=lambda p: p.company):
        with Transaction().set_context(company=company.id):
            today = Date.today()
        cls.write([p for p in purchases if not p.purchase_date], {
                'purchase_date': today,
                })

def _process_invoice(cls, purchases):
    invoices = {}
    for purchase in purchases:
        invoice = purchase.create_invoice()
        if invoice:
            invoices[purchase] = invoice

    cls._save_invoice(invoices)

def _process_fulfillment(cls, purchases):
    pool = Pool()
    Move = pool.get('stock.move')
    ShipmentInReturn = pool.get('stock.shipment.in.return')

    moves, shipments_return = [], {}
    for purchase in purchases:
        moves.extend(purchase.create_move('in'))
        return_moves = purchase.create_move('return')
        if return_moves:
            shipments_return[purchase] = purchase.create_return_shipment(
                return_moves)

    Move.save(moves)

    ShipmentInReturn.save(shipments_return.values())
    ShipmentInReturn.wait(shipments_return.values())
    for purchase, shipment in shipments_return.items():
        purchase.copy_resources_to(shipment)

def _process_invoice_fulfillment_states(cls, purchases):
    pool = Pool()
    Line = pool.get('purchase.line')
    lines = []
    purchases_to_invoice = defaultdict(list)
    invoice_states, shipment_states = defaultdict(list), defaultdict(list)
    for purchase in purchases:
        invoice_state = purchase.get_invoice_state()
        if purchase.invoice_state != invoice_state:
            invoice_states[invoice_state].append(purchase)
        shipment_state = purchase.get_shipment_state()
        if purchase.shipment_state != shipment_state:
            shipment_states[shipment_state].append(purchase)

        to_invoice = False
        for line in purchase.line_lines:
            line.set_quantities()
            to_invoice |= bool(line.quantity_to_invoice)
            lines.append(line)
        if purchase.to_invoice != to_invoice:
            purchases_to_invoice[to_invoice].append(purchase)

    for to_invoice, purchases in purchases_to_invoice.items():
        cls.write(purchases, {'to_invoice': to_invoice})
    for invoice_state, purchases in invoice_states.items():
        cls.write(purchases, {'invoice_state': invoice_state})
        cls.log(purchases, 'transition', f'invoice_state:{invoice_state}')
    for shipment_state, purchases in shipment_states.items():
        cls.write(purchases, {'shipment_state': shipment_state})
        cls.log(
            purchases, 'transition', f'shipment_state:{shipment_state}')
    Line.save(lines)

def _process_state(cls, purchases):
    process, done = [], []
    for purchase in purchases:
        if purchase.is_done():
            if purchase.state != 'done':
                if purchase.state == 'confirmed':
                    process.append(purchase)
                done.append(purchase)
        elif purchase.state != 'processing':
            process.append(purchase)
    if process:
        cls.proceed(process)
    if done:
        cls.do(done)

def _save_invoice(cls, invoices):
    pool = Pool()
    Invoice = pool.get('account.invoice')

    Invoice.save(invoices.values())
    for purchase, invoice in invoices.items():
        purchase.copy_resources_to(invoice)

def get_invoice_state(self):
    '''
    Return the invoice state for the purchase.
    '''
    skips = set(self.invoices_ignored)
    skips.update(self.invoices_recreated)
    invoices = [i for i in self._invoices_for_state if i not in skips]

    def is_cancelled(invoice):
        return invoice.state == 'cancelled' and not invoice.cancel_move

    def is_paid(invoice):
        return (
            invoice.state == 'paid'
            or (invoice.state == 'cancelled' and invoice.cancel_move))
    if invoices:
        if any(is_cancelled(i) for i in invoices):
            return 'exception'
        elif all(is_paid(i) for i in invoices):
            return 'paid'
        elif any(is_paid(i) for i in invoices):
            return 'partially paid'
        elif any(i.state == 'posted' for i in invoices):
            return 'awaiting payment'
        else:
            return 'pending'
    return 'none'

def get_shipment_state(self):
    '''
    Return the shipment state for the purchase.
    '''
    if any(l.moves_exception for l in self.line_lines):
        return 'exception'
    elif any(m.state != 'cancelled' for m in self.moves):
        if all(l.moves_progress >= 1 for l in self.line_lines
                if l.moves_progress is not None):
            return 'received'
        elif any(l.moves_progress for l in self.line_lines):
            return 'partially shipped'
        else:
            return 'waiting'
    return 'none'

def _get_return_shipment(self):
    ShipmentInReturn = Pool().get('stock.shipment.in.return')
    return ShipmentInReturn(
        company=self.company,
        from_location=self.return_from_location,
        to_location=self.party.supplier_location,
        supplier=self.party,
        delivery_address=self.party.address_get(type='delivery'),
        )

@Transactional
protected Partner validateCustomer(SaleOrder saleOrder) {

  Partner clientPartner = partnerRepository.find(saleOrder.getClientPartner().getId());
  clientPartner.setIsCustomer(true);
  clientPartner.setIsProspect(false);

  return partnerRepository.save(clientPartner);
}

@Transactional(rollbackOn = {Exception.class})
public void confirmProcess(SaleOrder saleOrder) throws AxelorException {
  List<Integer> authorizedStatus = new ArrayList<>();
  authorizedStatus.add(SaleOrderRepository.STATUS_FINALIZED_QUOTATION);
  authorizedStatus.add(SaleOrderRepository.STATUS_ORDER_COMPLETED);
  if (saleOrder.getStatusSelect() == null
      || !authorizedStatus.contains(saleOrder.getStatusSelect())) {
    throw new AxelorException(
        TraceBackRepository.CATEGORY_INCONSISTENCY,
        I18n.get(SaleExceptionMessage.SALE_ORDER_CONFIRM_WRONG_STATUS));
  }

  saleOrder.setStatusSelect(SaleOrderRepository.STATUS_ORDER_CONFIRMED);
  saleOrder.setConfirmationDateTime(appSaleService.getTodayDateTime().toLocalDateTime());
  saleOrder.setConfirmedByUser(userService.getUser());

  this.validateCustomer(saleOrder);

  if (appSaleService.getAppSale().getCloseOpportunityUponSaleOrderConfirmation()) {
    Opportunity opportunity = saleOrder.getOpportunity();
    if (opportunity != null) {
      opportunity.setOpportunityStatus(appCrmService.getClosedWinOpportunityStatus());
    }
  }

  saleOrderRepository.save(saleOrder);
}

@Transactional(
    rollbackOn = {Exception.class},
    ignore = {BlockedSaleOrderException.class})
@Override
public void checkSaleOrderBlocking(SaleOrder saleOrder, boolean manualUnblock)
    throws AxelorException {
  Partner partner = saleOrder.getClientPartner();
  Blocking blocking =
      blockingService.getBlocking(
          partner, saleOrder.getCompany(), BlockingRepository.SALE_BLOCKING);

  if (blocking != null && !manualUnblock) {
    saleOrder.setBlockedOnCustCreditExceed(true);
    saleOrderRepository.save(saleOrder);
    String reason =
        blocking.getBlockingReason() != null ? blocking.getBlockingReason().getName() : "";
    throw new BlockedSaleOrderException(
        partner, I18n.get("Client is sale blocked:") + " " + reason);
  }
}

@Transactional(
    rollbackOn = {Exception.class},
    ignore = {BlockedSaleOrderException.class})
@Override
public void checkSaleOrderBlocking(SaleOrder saleOrder) throws AxelorException {
  checkSaleOrderBlocking(saleOrder, saleOrder.getManualUnblock());
}

@Transactional(
    rollbackOn = {Exception.class},
    ignore = {BlockedSaleOrderException.class})
@Override
public String confirmSaleOrder(SaleOrder saleOrder) throws AxelorException {
  checkSaleOrderBlocking(saleOrder);

  SaleOrderConfirm saleOrderConfirm = new SaleOrderConfirm(saleOrder);
  try {
    saleOrderConfirmEvent.fire(saleOrderConfirm);
  } catch (ObserverException e) {
    throw new ObserverBaseException(e.getCause(), e.getCause().getMessage());
  }
  return saleOrderConfirm.getNotifyMessage();
}

@Override
@Transactional(rollbackOn = {Exception.class})
public void cancelPurchaseOrder(PurchaseOrder purchaseOrder) throws AxelorException {
  List<Integer> authorizedStatus = new ArrayList<>();
  authorizedStatus.add(PurchaseOrderRepository.STATUS_DRAFT);
  authorizedStatus.add(PurchaseOrderRepository.STATUS_REQUESTED);
  authorizedStatus.add(PurchaseOrderRepository.STATUS_VALIDATED);
  if (purchaseOrder.getStatusSelect() == null
      || !authorizedStatus.contains(purchaseOrder.getStatusSelect())) {
    throw new AxelorException(
        TraceBackRepository.CATEGORY_INCONSISTENCY,
        I18n.get(PurchaseExceptionMessage.PURCHASE_ORDER_CANCEL_WRONG_STATUS));
  }

  purchaseOrder.setStatusSelect(PurchaseOrderRepository.STATUS_CANCELED);
  purchaseOrderRepo.save(purchaseOrder);
}

@Override
@Transactional(rollbackOn = {Exception.class})
public void validatePurchaseOrder(PurchaseOrder purchaseOrder) throws AxelorException {

  if (purchaseOrder.getStatusSelect() == null
      || purchaseOrder.getStatusSelect() != PurchaseOrderRepository.STATUS_REQUESTED) {
    throw new AxelorException(
        TraceBackRepository.CATEGORY_INCONSISTENCY,
        I18n.get(PurchaseExceptionMessage.PURCHASE_ORDER_VALIDATE_WRONG_STATUS));
  }

  purchaseOrderService.computePurchaseOrder(purchaseOrder);

  purchaseOrder.setStatusSelect(PurchaseOrderRepository.STATUS_VALIDATED);
  purchaseOrder.setValidationDateTime(
      appPurchaseService.getTodayDateTime(purchaseOrder.getCompany()).toLocalDateTime());
  purchaseOrder.setValidatedByUser(AuthUtils.getUser());

  purchaseOrder.setSupplierPartner(purchaseOrderService.validateSupplier(purchaseOrder));
  purchaseOrderTypeSelectService.setTypeSelect(purchaseOrder);

  purchaseOrderService.updateCostPrice(purchaseOrder);
}

@Override
@Transactional(rollbackOn = {Exception.class})
public void draftPurchaseOrder(PurchaseOrder purchaseOrder) throws AxelorException {

  if (purchaseOrder.getStatusSelect() == null
      || purchaseOrder.getStatusSelect() != PurchaseOrderRepository.STATUS_CANCELED) {
    throw new AxelorException(
        TraceBackRepository.CATEGORY_INCONSISTENCY,
        I18n.get(PurchaseExceptionMessage.PURCHASE_ORDER_DRAFT_WRONG_STATUS));
  }

  purchaseOrder.setStatusSelect(PurchaseOrderRepository.STATUS_DRAFT);
  purchaseOrderRepo.save(purchaseOrder);
}

def update_prevdoc_status(self):
	self.update_qty()
	self.validate_qty()

def update_qty(self, update_modified=True):
	"""Updates qty or amount at row level

	:param update_modified: If true, updates `modified` and `modified_by` for target parent doc
	"""
	for args in self.status_updater:
		# condition to include current record (if submit or no if cancel)
		if self.docstatus == 1:
			args["cond"] = " or parent=%s" % frappe.db.escape(self.name)
		else:
			args["cond"] = " and parent!=%s" % frappe.db.escape(self.name)

		self._update_children(args, update_modified)

		if "percent_join_field" in args or "percent_join_field_parent" in args:
			self._update_percent_field_in_targets(args, update_modified)

	from erpnext.manufacturing.doctype.blanket_order.blanket_order import (
		refresh_blanket_orders_of_fulfilled_rows,
	)

	refresh_blanket_orders_of_fulfilled_rows(self)

def _update_children(self, args, update_modified):
	"""Update quantities or amount in child table"""
	for d in self.get_all_children():
		if d.doctype != args["source_dt"]:
			continue

		self._update_modified(args, update_modified)

		# updates qty in the child table
		args["detail_id"] = d.get(args["join_field"])

		args["second_source_condition"] = ""
		if (
			args.get("second_source_dt")
			and args.get("second_source_field")
			and args.get("second_join_field")
		):
			if not args.get("second_source_extra_cond"):
				args["second_source_extra_cond"] = ""

			args["second_source_condition"] = frappe.db.sql(
				""" select ifnull((select sum({second_source_field})
				from `tab{second_source_dt}`
				where `{second_join_field}`=%(detail_id)s
				and (`tab{second_source_dt}`.docstatus=1)
				{second_source_extra_cond}), 0) """.format(**args),
				{"detail_id": args["detail_id"]},
			)[0][0]

		if args["detail_id"]:
			if not args.get("extra_cond"):
				args["extra_cond"] = ""

			args["source_dt_value"] = (
				frappe.db.sql(
					"""
					(select ifnull(sum({source_field}), 0)
						from `tab{source_dt}` where `{join_field}`=%(detail_id)s
						and (docstatus=1 {cond}) {extra_cond})
			""".format(**args),
					{"detail_id": args["detail_id"]},
				)[0][0]
				or 0.0
			)

			if args["second_source_condition"]:
				args["source_dt_value"] += flt(args["second_source_condition"])

			target_value = args["source_dt_value"]
			if args.get("target_conversion_factor"):
				target_value = f"{target_value} / {args['target_conversion_factor']}"

			frappe.db.sql(
				"""update `tab{target_dt}`
				set {target_field} = {target_value} {update_modified}
				where name=%(detail_id)s""".format(target_value=target_value, **args),
				{"detail_id": args["detail_id"]},
			)

def _update_percent_field_in_targets(self, args, update_modified=True):
	"""Update percent field in parent transaction"""
	if args.get("percent_join_field_parent"):
		# if reference to target doc where % is to be updated, is
		# in source doc's parent form, consider percent_join_field_parent
		if name := self.get(args["percent_join_field_parent"]):
			args["name"] = name
			self._update_percent_field(args, update_modified)
	else:
		distinct_transactions = set(
			d.get(args["percent_join_field"]) for d in self.get_all_children(args["source_dt"])
		)

		for name in distinct_transactions:
			if name:
				args["name"] = name
				self._update_percent_field(args, update_modified)

def _update_percent_field(self, args, update_modified=True):
	"""Update percent field in parent transaction"""

	update_data = {}

	if args.get("target_parent_field"):
		update_data[args.get("target_parent_field")] = self._calculate_target_parent_percentage(
			args["name"],
			args["target_parent_dt"],
			args["target_dt"],
			args["target_ref_field"],
			args["target_field"],
		)
		# update field
		if args.get("status_field"):
			update_data[args.get("status_field")] = self._determine_status(
				update_data[args.get("target_parent_field")], args["keyword"]
			)

	if update_data:
		target = frappe.get_lazy_doc(args["target_parent_dt"], args["name"])
		target.update(update_data)  # status calculus might depend on it
		status = target.get_status()
		if status.get("status"):
			update_data.update(status)
		target.db_set(update_data, update_modified=update_modified, notify=True)

def _update_modified(self, args, update_modified):
	if not update_modified:
		args["update_modified"] = ""
		return

	args["update_modified"] = ", modified = {}, modified_by = {}".format(
		frappe.db.escape(now()), frappe.db.escape(frappe.session.user)
	)

def validate_qty(self):
	"""Validates qty at row level"""
	selling_doctypes = ("Sales Order", "Sales Invoice", "Delivery Note")
	buying_doctypes = ("Purchase Order", "Purchase Invoice", "Purchase Receipt")

	for args in self.status_updater:
		if "target_ref_field" not in args or args.get("validate_qty") is False:
			# if target_ref_field is not specified or validate_qty is explicitly set to False, skip validation
			continue

		# Reset per-args so each config block uses its own allowance source without
		# leaking cached values from a previous config block.
		self.item_allowance = {}
		self.global_qty_allowance = None
		self.global_amount_allowance = None

		items_to_validate = []
		selling_negative_rate_allowed = frappe.get_single_value(
			"Selling Settings", "allow_negative_rates_for_items"
		)
		buying_negative_rate_allowed = frappe.get_single_value(
			"Buying Settings", "allow_negative_rates_for_items"
		)

		# get unique transactions to update
		for d in self.get_all_children():
			if hasattr(d, "qty") and flt(d.qty) < 0 and not self.get("is_return"):
				frappe.throw(_("For an item {0}, quantity must be positive number").format(d.item_code))

			if hasattr(d, "qty") and flt(d.qty) > 0 and self.get("is_return"):
				frappe.throw(_("For an item {0}, quantity must be negative number").format(d.item_code))

			if (not selling_negative_rate_allowed and self.doctype in selling_doctypes) or (
				not buying_negative_rate_allowed and self.doctype in buying_doctypes
			):
				if hasattr(d, "item_code") and hasattr(d, "rate") and flt(d.rate) < 0:
					frappe.throw(
						_(
							"For item {0}, rate must be a positive number. To Allow negative rates, enable {1} in {2}"
						).format(
							frappe.bold(d.item_code),
							frappe.bold(_("`Allow Negative rates for Items`")),
							get_link_to_form(
								"Selling Settings"
								if self.doctype in selling_doctypes
								else "Buying Settings"
							),
						),
					)

			if d.doctype == args["source_dt"] and d.get(args["join_field"]):
				items_to_validate.append(
					frappe._dict(
						{
							"name": d.get(args["join_field"]),
							"production_plan_sub_assembly_item": d.get(
								"production_plan_sub_assembly_item"
							),
							"idx": d.idx,
							"child_doc": d,
						}
					)
				)

		if items_to_validate:
			pp_sub_assembly_items = [
				item.production_plan_sub_assembly_item
				for item in items_to_validate
				if item.production_plan_sub_assembly_item
			]

			pp_subcontract_items = []
			if pp_sub_assembly_items:
				pp_subcontract_items = frappe.db.get_all(
					"Production Plan Sub Assembly Item",
					filters={
						"name": ("in", pp_sub_assembly_items),
						"type_of_manufacturing": "Subcontract",
					},
					pluck="name",
				)

			regular_items = []
			pp_items = []

			for item in items_to_validate:
				if item.production_plan_sub_assembly_item in pp_subcontract_items:
					pp_items.append(item.name)
				else:
					regular_items.append(item.name)

			item_details = []

			# Query regular items with item_code field
			if regular_items:
				item_details.extend(self.fetch_items_with_pending_qty(args, "item_code", regular_items))

			# Query production plan items with production_item field
			if pp_items and args.get("target_dt") in ["Production Plan Sub Assembly Item"]:
				item_details.extend(self.fetch_items_with_pending_qty(args, "production_item", pp_items))

			item_lookup = {item.name: item for item in item_details}

			for child_item in items_to_validate:
				item = item_lookup.get(child_item.name)

				if item:
					item["idx"] = child_item.idx
					item["target_ref_field"] = args["target_ref_field"].replace("_", " ")

					# if not item[args['target_ref_field']]:
					# 	msgprint(_("Note: System will not check over-delivery and over-booking for Item {0} as quantity or amount is 0").format(item.item_code))
					if args.get("no_allowance"):
						item["reduce_by"] = item[args["target_field"]] - item[args["target_ref_field"]]
						if item["reduce_by"] > 0.01:
							self.limits_crossed_error(args, item, "qty")

					elif item[args["target_ref_field"]]:
						self.check_overflow_with_allowance(item, args)

def get_status(self):
	"""
	Get the status of the document.

	Returns:
	dict: A dictionary containing the status. This allows callers to receive
	a dictionary for efficient bulk updates, for example when `per_billed`
	and other status fields also need to be updated.

	Note:
	Can be overriden on a doctype to implement more localized status updater logic.

	Example:
	{
	"status": "Draft",
	"per_billed": 50,
	"billing_status": "Partly Billed"
	}
	"""
	if self.doctype not in status_map:
		return {
			"status": self.get("status")
		}  # sometimes status field is not present on certain DocTypes such as Stock Entry

	sl = status_map[self.doctype][:]
	sl.reverse()

	for s in sl:
		if not s[1]:
			return {"status": s[0]}
		elif s[1].startswith("eval:"):
			if frappe.safe_eval(
				s[1][5:],
				None,
				{
					"self": self.as_dict(),
					"getdate": getdate,
					"nowdate": nowdate,
					"get_value": frappe.db.get_value,
				},
			):
				return {"status": s[0]}
		elif getattr(self, s[1])():
			return {"status": s[0]}

	return {"status": self.status}

def _determine_status(percentage, keyword):
	if percentage < 0.001:
		return f"Not {keyword}"
	elif percentage >= 99.999999:
		return f"Fully {keyword}"
	else:
		return f"Partly {keyword}"

def limits_crossed_error(self, args, item, qty_or_amount):
	"""Raise exception for limits crossed"""
	if (
		self.doctype in ["Sales Invoice", "Delivery Note"]
		and qty_or_amount == "amount"
		and self.is_internal_customer
	):
		return

	elif (
		self.doctype in ["Purchase Invoice", "Purchase Receipt"]
		and qty_or_amount == "amount"
		and self.is_internal_supplier
	):
		return

	if args["source_dt"] != "Pick List Item" and args["target_dt"] not in [
		"Quotation Item",
		"Packed Item",
	]:
		if args.get("target_dt") == "Material Request Item":
			action_msg = _('To allow over ordering, update "Over Order Allowance" in Buying Settings.')
		elif qty_or_amount == "qty":
			action_msg = _(
				'To allow over receipt / delivery, update "Over Receipt/Delivery Allowance" in Stock Settings or the Item.'
			)
		else:
			action_msg = _(
				'To allow over billing, update "Over Billing Allowance" in Accounts Settings or the Item.'
			)
	else:
		action_msg = None

	frappe.throw(
		_(
			"This document is over limit by {0} {1} for item {4}. Are you making another {3} against the same {2}?"
		).format(
			frappe.bold(_(item["target_ref_field"].title())),
			frappe.bold(item["reduce_by"]),
			frappe.bold(_(args.get("target_dt"))),
			frappe.bold(_(self.doctype)),
			frappe.bold(item.get("item_code")),
		)
		+ ("<br><br>" + action_msg if action_msg else ""),
