def get_allowance_for(
	item_code,
	item_allowance=None,
	global_qty_allowance=None,
	global_amount_allowance=None,
	qty_or_amount="qty",
	global_qty_allowance_field="over_delivery_receipt_allowance",
	global_qty_allowance_doctype="Stock Settings",
	item_qty_allowance_field="over_delivery_receipt_allowance",
):
	"""
	Returns the allowance for the item, if not set, returns global allowance.

	Args:
	        item_code: The item to get allowance for.
	        item_allowance: Cached per-item allowances from a previous call.
	        global_qty_allowance: Cached global qty allowance from a previous call.
	        global_amount_allowance: Cached global amount allowance from a previous call.
	        qty_or_amount: Whether to return qty or amount allowance.
	        global_qty_allowance_field: The field name on the settings doctype to use for the global qty allowance.
	        global_qty_allowance_doctype: The settings doctype to read the global qty allowance from.
	        item_qty_allowance_field: The field name on the Item doctype to use for the item-level qty allowance override.
	"""
	if item_allowance is None:
		item_allowance = {}
	if qty_or_amount == "qty":
		if item_allowance.get(item_code, frappe._dict()).get("qty"):
			return (
				item_allowance[item_code].qty,
				item_allowance,
				global_qty_allowance,
				global_amount_allowance,
			)
	else:
		if item_allowance.get(item_code, frappe._dict()).get("amount"):
			return (
				item_allowance[item_code].amount,
				item_allowance,
				global_qty_allowance,
				global_amount_allowance,
			)

	qty_allowance, over_billing_allowance = frappe.get_cached_value(
		"Item", item_code, [item_qty_allowance_field, "over_billing_allowance"]
	)

	if qty_or_amount == "qty" and not qty_allowance:
		if global_qty_allowance is None:
			global_qty_allowance = flt(
				frappe.get_single_value(global_qty_allowance_doctype, global_qty_allowance_field)
			)
		qty_allowance = global_qty_allowance
	elif qty_or_amount == "amount" and not over_billing_allowance:
		if global_amount_allowance is None:
			global_amount_allowance = flt(
				frappe.get_cached_value("Accounts Settings", None, "over_billing_allowance")
			)
		over_billing_allowance = global_amount_allowance

	if qty_or_amount == "qty":
		allowance = qty_allowance
		item_allowance.setdefault(item_code, frappe._dict()).setdefault("qty", qty_allowance)
	else:
		allowance = over_billing_allowance
		item_allowance.setdefault(item_code, frappe._dict()).setdefault("amount", over_billing_allowance)

	return allowance, item_allowance, global_qty_allowance, global_amount_allowance

def update_delivery_date_based_on_schedule(self, child_row, first_delivery_date):
	for row in self.items:
		if row.name == child_row.name:
			if first_delivery_date:
				row.delivery_date = first_delivery_date
			break

	self.save()

def copy_data(self, default=None):
    default = dict(default or {})
    default_has_no_order_line = "order_line" not in default
    default.setdefault("order_line", [])
    vals_list = super().copy_data(default=default)
    if default_has_no_order_line:
        for order, vals in zip(self, vals_list):
            vals["order_line"] = [
                Command.create(line_vals)
                for line_vals in order._get_copiable_order_lines().copy_data()
            ]
    return vals_list

def _create_upsell_activity(self):
    if not self:
        return

    self.activity_unlink(["mail.mail_activity_data_todo"])
    for order in self:
        order_ref = order._get_html_link()
        customer_ref = order.partner_id._get_html_link()
        order.activity_schedule(
            "mail.mail_activity_data_todo",
            user_id=order.user_id.id or order.partner_id.user_id.id,
            note=order.env._(
                "Upsell %(order)s for customer %(customer)s",
                order=order_ref,
                customer=customer_ref,
            ),
        )

def _create_down_payment_lines_from_base_lines(self, down_payment_base_lines):
    """Add the base lines passed as parameter as sale order lines into the current sale order.

    :param down_payment_base_lines: A list of base lines
                                    (see '_prepare_base_line_for_taxes_computation').
    :return The newly created SO lines.
    """
    self.ensure_one()
    sequence = max(self.order_line.mapped("sequence") or [10]) + 1
    return (
        self
        .env["sale.order.line"]
        .with_context(sale_no_log_for_new_lines=True)
        .create([
            {
                **self._prepare_down_payment_line_values_from_base_line(base_line),
                "sequence": sequence + index,
            }
            for index, base_line in enumerate(down_payment_base_lines)
        ])
    )

def create(self, vals_list):
    for vals in vals_list:
        if vals.get("name", self.env._("New")) == self.env._("New"):
            seq_date = (
                fields.Datetime.context_timestamp(
                    self, fields.Datetime.to_datetime(vals["date_order"])
                )
                if "date_order" in vals
                else None
            )
            vals["name"] = self.env["ir.sequence"].with_company(
                vals.get("company_id")
            ).next_by_code("sale.order", sequence_date=seq_date) or self.env._("New")

    return super().create(vals_list)

def _get_copiable_order_lines(self):
    """Return the order lines that can be copied to a new order."""
    return self.order_line.filtered(lambda sol: not sol.is_downpayment)

def _prepare_down_payment_line_section_values(self):
    """Prepare the values to create a section line for the down payment on the current SO.

    :return: A dictionary to create a new SO section line.
    """
    self.ensure_one()
    return {"order_id": self.id, "display_type": "line_section", "is_downpayment": True}

def copy(self, default=None):
    ctx = dict(self.env.context)
    ctx.pop('default_product_id', None)
    self = self.with_context(ctx)
    new_pos = super().copy(default=default)
    for line in new_pos.order_line:
        if line.product_id:
            line.date_planned = line._get_date_planned(line._get_seller_info())
    return new_pos

def message_post(self, **kwargs):
    if self.env.context.get('mark_rfq_as_sent'):
        self._mark_rfqs_as_sent()
        kwargs['notify_author_mention'] = kwargs.get('notify_author_mention', True)
    return super().message_post(**kwargs)

def button_cancel(self):
    locked_purchase_orders = self.filtered(lambda po: po.locked)
    if locked_purchase_orders:
        raise UserError(self.env._("Unable to cancel purchase order(s): %s. You must first unlock them.", locked_purchase_orders.mapped('display_name')))

    purchase_orders_with_invoices = self.filtered(lambda po: any(i.state not in ('cancel', 'draft') for i in po.invoice_ids))
    if purchase_orders_with_invoices:
        raise UserError(_("Unable to cancel purchase order(s): %s. You must first cancel their related vendor bills.", purchase_orders_with_invoices.mapped('display_name')))
    self.write({'state': 'cancel'})

def __setup__(cls):
    super().__setup__()
    t = cls.__table__()
    cls._sql_indexes.add(
        Index(
            t,
            (t.state, Index.Equality(cardinality='low')),
            where=t.state == 'draft'))
    cls._order = [
        ('date', 'DESC'),
        ('id', 'DESC'),
        ]
    cls._transitions |= {
        ('draft', 'validated'),
        }
    cls._buttons.update({
            'validate_amendment': {
                'invisible': Eval('state') != 'draft',
                'depends': ['state'],
                },
            })

def _stock_moves(cls, line):
    for move in line.moves:
        if move.state in {'staging', 'draft'}:
            yield move

def on_change_with_state(self, name=None):
    if self.amendment:
        return self.amendment.state

def on_change_line(self):
    if self.line:
        self.product = self.line.product
        self.quantity = self.line.quantity
        self.unit = self.line.unit
        self.unit_price = self.line.unit_price
        self.description = self.line.description
    else:
        self.product = self.quantity = self.unit = self.unit_price = None
        self.description = None

def on_change_party(self):
    if not self.invoice_party:
        self.invoice_address = None
    if not self.shipment_party:
        self.shipment_address = None
    if self.party:
        if not self.invoice_address:
            self.invoice_address = self.party.address_get(type='invoice')
        if not self.shipment_address:
            with Transaction().set_context(
                    warehouse=(
                        self.warehouse.id if self.warehouse else None)):
                self.shipment_address = self.party.address_get(
                    type='delivery')

def on_change_invoice_party(self):
    if self.invoice_party:
        self.invoice_address = self.invoice_party.address_get(
            type='invoice')
    elif self.party:
        self.invoice_address = self.party.address_get(type='invoice')

def on_change_shipment_party(self):
    with Transaction().set_context(
            warehouse=self.warehouse.id if self.warehouse else None):
        if self.shipment_party:
            self.shipment_address = self.shipment_party.address_get(
                type='delivery')
        elif self.party:
            self.shipment_address = self.party.address_get(type='delivery')

def on_change_with_product_uom_category(self, name=None):
    if self.line:
        if self.line.product_uom_category:
            return self.line.product_uom_category
        elif self.line.unit:
            return self.line.unit.category

def apply(self, sale):
    assert self.sale == sale
    sale_line = None
    if self.line:
        for line in sale.lines:
            if self.line == line:
                sale_line = line
                break
    getattr(self, '_apply_%s' % self.action)(sale, sale_line)

@Override
public BigDecimal getQtyToOrderLeft(SaleOrderLine saleOrderLine) {
  return saleOrderLine.getQty().subtract(saleOrderLine.getOrderedQty());
}

@Override
public void checkSolOrderedQty(SaleOrder saleOrder) throws AxelorException {
  List<SaleOrderLine> saleOrderLineList = saleOrder.getSaleOrderLineList();
  if (saleOrderLineList.stream()
      .allMatch(line -> line.getQty().compareTo(line.getOrderedQty()) == 0)) {
    throw new AxelorException(
        TraceBackRepository.CATEGORY_INCONSISTENCY,
        I18n.get(SaleExceptionMessage.SALE_QUOTATION_ALL_ALREADY_ORDERED));
  }
}

protected SaleOrderLine getSaleOrderLineCopy(
    SaleOrderLine saleOrderLineToCopy, BigDecimal qtyToOrder, SaleOrder confirmedSaleOrder)
    throws AxelorException {
  SaleOrderLine copySaleOrderLine = saleOrderLineRepository.copy(saleOrderLineToCopy, true);
  copySaleOrderLine.setQty(qtyToOrder);
  copySaleOrderLine.setSaleOrder(null);
  saleOrderLineOnChangeService.qtyOnChange(copySaleOrderLine, confirmedSaleOrder, null);
  saleOrderLineRepository.save(copySaleOrderLine);
  return copySaleOrderLine;
}

protected void updateOriginSol(
    SaleOrderLine saleOrderLineToCopy, BigDecimal qtyToOrder, AppBase appBase)
    throws AxelorException {
  BigDecimal qtyToOrderLeft = getQtyToOrderLeft(saleOrderLineToCopy);
  if (qtyToOrderLeft.compareTo(qtyToOrder) < 0) {
    throw new AxelorException(
        TraceBackRepository.CATEGORY_INCONSISTENCY,
        I18n.get(SaleExceptionMessage.SALE_QUOTATION_WRONG_ORDER_QTY),
        qtyToOrderLeft.setScale(appBase.getNbDecimalDigitForQty(), RoundingMode.HALF_UP),
        saleOrderLineToCopy.getProduct().getName());
  }
  saleOrderLineToCopy.setOrderedQty(saleOrderLineToCopy.getOrderedQty().add(qtyToOrder));
}

protected void addLines(Map<Long, BigDecimal> qtyToOrderMap, SaleOrder confirmedSaleOrder)
    throws AxelorException {
  AppBase appBase = appBaseService.getAppBase();
  for (Map.Entry<Long, BigDecimal> entry : qtyToOrderMap.entrySet()) {
    Long lineId = entry.getKey();
    BigDecimal qtyToOrder = entry.getValue();
    if (qtyToOrderMap.get(lineId) != null
        && qtyToOrderMap.get(lineId).compareTo(BigDecimal.ZERO) == 0) {
      continue;
    }

    SaleOrderLine saleOrderLineToCopy = saleOrderLineRepository.find(lineId);
    updateOriginSol(saleOrderLineToCopy, qtyToOrder, appBase);
    SaleOrderLine copySaleOrderLine =
        getSaleOrderLineCopy(saleOrderLineToCopy, qtyToOrder, confirmedSaleOrder);
    confirmedSaleOrder.addSaleOrderLineListItem(copySaleOrderLine);
  }

  if (CollectionUtils.isEmpty(confirmedSaleOrder.getSaleOrderLineList())) {
    throw new AxelorException(
        TraceBackRepository.CATEGORY_INCONSISTENCY,
        I18n.get(SaleExceptionMessage.SALE_QUOTATION_NO_LINE_GENERATED));
  }
}

protected SaleOrder getConfirmedSaleOrder(SaleOrder saleOrder) {
  SaleOrder confirmedSaleOrder = saleOrderRepository.copy(saleOrder, true);
  confirmedSaleOrder.clearSaleOrderLineList();
  confirmedSaleOrder.clearSaleOrderLineTaxList();
  confirmedSaleOrder.clearBatchSet();
  confirmedSaleOrder.setOriginSaleQuotation(saleOrder);
  confirmedSaleOrder.setManualUnblock(saleOrder.getManualUnblock());
  confirmedSaleOrder.setOpportunity(saleOrder.getOpportunity());
  return confirmedSaleOrder;
}

@Transactional(rollbackOn = {AxelorException.class})
@Override
public SaleOrder generateConfirmedSaleOrder(
    SaleOrder saleOrder, Map<Long, BigDecimal> qtyToOrderMap) throws AxelorException {

  checkBeforeConfirm(saleOrder, qtyToOrderMap);
  SaleOrder confirmedSaleOrder = getConfirmedSaleOrder(saleOrder);
  addLines(qtyToOrderMap, confirmedSaleOrder);
  addEndOfPackLines(saleOrder, confirmedSaleOrder);
  saleOrderComputeService.computeSaleOrder(confirmedSaleOrder);
  saleOrderFinalizeService.finalizeQuotation(confirmedSaleOrder);
  saleOrderConfirmService.confirmSaleOrder(confirmedSaleOrder);
  saleOrderOrderingStatusService.updateOrderingStatus(saleOrder);
  saleOrderComputeService.computeSaleOrder(saleOrder);
  return confirmedSaleOrder;
}

protected void addEndOfPackLines(SaleOrder saleOrder, SaleOrder confirmedSaleOrder) {
  List<SaleOrderLine> endOfPackLines =
      saleOrder.getSaleOrderLineList().stream()
          .filter(line -> line.getTypeSelect() == SaleOrderLineRepository.TYPE_END_OF_PACK)
          .collect(Collectors.toList());
  for (SaleOrderLine endOfPackLine : endOfPackLines) {
    SaleOrderLine copy = saleOrderLineRepository.copy(endOfPackLine, true);
    copy.setSaleOrder(null);
    saleOrderLineRepository.save(copy);
    confirmedSaleOrder.addSaleOrderLineListItem(copy);
  }
}

protected void checkDiffs(
    List<PurchaseOrder> purchaseOrdersToMerge,
    PurchaseOrderMergingResult result,
    PurchaseOrder firstPurchaseOrder) {
  purchaseOrdersToMerge.forEach(
      purchaseOrder -> {
        updateDiffsCommonFields(purchaseOrder, result);
      });
  if (purchaseOrdersToMerge.stream()
      .anyMatch(order -> order.getInAti() != firstPurchaseOrder.getInAti())) {
    Checks checks = getChecks(result);
    checks.setExistAtiDiff(true);
  }
}

