def validate_with_previous_doc(self):
	super().validate_with_previous_doc(
		{
			"Sales Order": {
				"ref_dn_field": "against_sales_order",
				"compare_fields": [
					["customer", "="],
					["company", "="],
					["project", "="],
					["currency", "="],
				],
			},
			"Sales Order Item": {
				"ref_dn_field": "so_detail",
				"compare_fields": [["item_code", "="], ["uom", "="], ["conversion_factor", "="]],
				"is_child_table": True,
				"allow_duplicate_prev_row_id": True,
			},
			"Sales Invoice": {
				"ref_dn_field": "against_sales_invoice",
				"compare_fields": [
					["customer", "="],
					["company", "="],
					["project", "="],
					["currency", "="],
				],
			},
			"Sales Invoice Item": {
				"ref_dn_field": "si_detail",
				"compare_fields": [["item_code", "="], ["uom", "="], ["conversion_factor", "="]],
				"is_child_table": True,
				"allow_duplicate_prev_row_id": True,
			},
		}
	)

	if (
		cint(frappe.get_single_value("Selling Settings", "maintain_same_sales_rate"))
		and not self.is_return
		and not self.is_internal_customer
	):
		self.validate_rate_with_reference_doc(
			[
				["Sales Order", "against_sales_order", "so_detail"],
				["Sales Invoice", "against_sales_invoice", "si_detail"],
			]
		)

def validate_references(self):
	self.validate_sales_order_references()
	self.validate_sales_invoice_references()

def validate_sales_order_references(self):
	self._validate_dependent_item_fields(
		"against_sales_order", "so_detail", _("References to Sales Orders are Incomplete")
	)

def validate_sales_invoice_references(self):
	if self.is_return:
		return

	self._validate_dependent_item_fields(
		"against_sales_invoice", "si_detail", _("References to Sales Invoices are Incomplete")
	)

def _validate_dependent_item_fields(self, field_a: str, field_b: str, error_title: str):
	errors = []
	for item in self.items:
		missing_label = None
		if item.get(field_a) and not item.get(field_b):
			missing_label = item.meta.get_label(field_b)
		elif item.get(field_b) and not item.get(field_a):
			missing_label = item.meta.get_label(field_a)

		if missing_label and missing_label != "No Label":
			errors.append(
				_("The field {0} in row {1} is not set").format(
					frappe.bold(_(missing_label)), frappe.bold(item.idx)
				)
			)

	if errors:
		frappe.throw("<br>".join(errors), title=error_title)

def validate_proj_cust(self):
	"""check for does customer belong to same project as entered.."""
	if self.project and self.customer:
		res = frappe.db.sql(
			"""select name from `tabProject`
			where name = %s and (customer = %s or
				ifnull(customer,'')='')""",
			(self.project, self.customer),
		)
		if not res:
			frappe.throw(
				_("Customer {0} does not belong to project {1}").format(self.customer, self.project)
			)

def validate_warehouse(self):
	super().validate_warehouse()

	for d in self.get_item_list():
		if not d["warehouse"] and frappe.get_cached_value("Item", d["item_code"], "is_stock_item") == 1:
			frappe.throw(_("Warehouse required for stock Item {0}").format(d["item_code"]))

def check_credit_limit(self):
	from erpnext.selling.doctype.customer.customer import check_credit_limit

	if self.per_billed == 100:
		return

	extra_amount = 0
	validate_against_credit_limit = False
	bypass_credit_limit_check_at_sales_order = cint(
		frappe.db.get_value(
			"Customer Credit Limit",
			filters={"parent": self.customer, "parenttype": "Customer", "company": self.company},
			fieldname="bypass_credit_limit_check",
		)
	)

	if bypass_credit_limit_check_at_sales_order:
		for d in self.get("items"):
			if not d.against_sales_invoice:
				validate_against_credit_limit = True
				extra_amount = self.base_grand_total
				break
	else:
		for d in self.get("items"):
			if not (d.against_sales_order or d.against_sales_invoice):
				validate_against_credit_limit = True
				break

	if validate_against_credit_limit:
		check_credit_limit(
			self.customer, self.company, bypass_credit_limit_check_at_sales_order, extra_amount
		)

def validate_packed_qty(self):
	"""Validate that if packed qty exists, it should be equal to qty"""

	if frappe.db.exists("Packing Slip", {"docstatus": 1, "delivery_note": self.name}):
		product_bundle_list = self.get_product_bundle_list()
		for item in self.items + self.packed_items:
			if (
				item.item_code not in product_bundle_list
				and flt(item.packed_qty)
				and flt(item.packed_qty) != flt(item.qty)
			):
				frappe.throw(
					_("Row {0}: Packed Qty must be equal to {1} Qty.").format(
						item.idx, frappe.bold(item.doctype)
					)
				)

def so_required(self):
	"""check in manage account if sales order required or not"""
	if self.is_return:
		return

	if frappe.get_single_value("Selling Settings", "so_required") == "Yes":
		for d in self.get("items"):
			if not d.against_sales_order:
				frappe.throw(_("Sales Order required for Item {0}").format(d.item_code))

def set_internal_return_target_warehouse(self):
	"""An internal return brings material back from the warehouse the delivery put it in."""
	original_rows = [d.dn_detail for d in self.items if d.dn_detail]
	if not (self.is_return and self.return_against and self.is_internal_customer and original_rows):
		return

	target_warehouses = frappe._dict(
		frappe.get_all(
			"Delivery Note Item",
			filters={"name": ("in", original_rows)},
			fields=["name", "target_warehouse"],
			as_list=True,
		)
	)
	for row in self.items:
		expected = target_warehouses.get(row.dn_detail)
		if not expected:
			continue

		if not row.target_warehouse:
			row.target_warehouse = expected
		elif row.target_warehouse != expected:
			frappe.throw(
				_("Row #{0}: Target Warehouse must be {1}, as on Delivery Note {2}").format(
					row.idx, frappe.bold(expected), frappe.bold(self.return_against)
				)
			)

def update_current_stock(self):
	if not (self.get("_action") and self._action != "update_after_submit"):
		return

	warehouse_item_codes = {}
	for d in self.get("items") + self.get("packed_items"):
		warehouse_item_codes.setdefault(d.warehouse, set()).add(d.item_code)

	if not warehouse_item_codes:
		return

	bin_map = {}
	for warehouse, item_codes in warehouse_item_codes.items():
		for b in frappe.get_all(
			"Bin",
			filters={"item_code": ["in", item_codes], "warehouse": warehouse},
			fields=["item_code", "actual_qty", "projected_qty"],
		):
			bin_map[(b.item_code, warehouse)] = b

	for d in self.get("items"):
		bin_data = bin_map.get((d.item_code, d.warehouse))
		d.actual_qty = bin_data.actual_qty if bin_data else None

	for d in self.get("packed_items"):
		bin_data = bin_map.get((d.item_code, d.warehouse))
		if bin_data:
			d.actual_qty = flt(bin_data.actual_qty)
			d.projected_qty = flt(bin_data.projected_qty)

def update_billing_status(self, update_modified=True):
	updated_delivery_notes = [self.name]
	if self.is_return and self.return_against:
		updated_delivery_notes.append(self.return_against)

	for d in self.get("items"):
		if d.si_detail and not d.so_detail:
			d.db_set("billed_amt", d.amount, update_modified=update_modified)
		elif d.so_detail:
			updated_delivery_notes += update_billed_amount_based_on_so(d.so_detail, update_modified)

	for dn in set(updated_delivery_notes):
		dn_doc = self if (dn == self.name) else frappe.get_lazy_doc("Delivery Note", dn)
		update_dn_modified = update_modified and dn != self.return_against
		dn_doc.update_billing_percentage(update_modified=update_dn_modified)

	self.load_from_db()

def make_return_invoice(self):
	creditable_qty = get_creditable_qty(self)
	if not any(creditable_qty.values()):
		frappe.msgprint(_("No Credit Note was created because the returned items were not invoiced"))
		return

	try:
		return_invoice = make_sales_invoice(self.name)
		return_invoice.is_return = True
		limit_to_creditable_qty(return_invoice, creditable_qty)
		return_invoice.save()
		return_invoice.submit()

		credit_note_link = frappe.utils.get_link_to_form("Sales Invoice", return_invoice.name)

		frappe.msgprint(_("Credit Note {0} has been created automatically").format(credit_note_link))
	except Exception:
		frappe.throw(
			_(
				"Could not create Credit Note automatically, please uncheck 'Issue Credit Note' and submit again"
			)
		)

def get_product_bundle_list(self):
	items_list = [item.item_code for item in self.items]
	return frappe.db.get_all(
		"Product Bundle",
		filters={"new_item_code": ["in", items_list], "disabled": 0},
		pluck="name",
	)

def get_creditable_qty(return_doc) -> dict:
	original_rows = get_original_rows(return_doc)
	if not original_rows:
		return {}

	available = get_billed_stock_qty({row.name for row in original_rows})
	apply_earlier_credits(available, original_rows, return_doc)

	creditable_qty = {}
	rows = [d for d in return_doc.items if d.dn_detail] + [d for d in return_doc.items if not d.dn_detail]
	for row in rows:
		sources = (
			[row.dn_detail]
			if row.dn_detail
			else [d.name for d in original_rows if d.item_code == row.item_code]
		)
		factor = flt(row.conversion_factor) or 1
		needed = abs(flt(row.stock_qty) or flt(row.qty) * factor)
		creditable_qty[row.name] = flt(take_credit(available, sources, needed) / factor, 6)

	return creditable_qty

def limit_to_creditable_qty(return_invoice, creditable_qty: dict) -> None:
	rows = []
	for row in return_invoice.items:
		qty = flt(creditable_qty.get(row.dn_detail))
		if qty:
			row.qty = -min(abs(flt(row.qty)), qty)
			rows.append(row)

	return_invoice.set("items", rows)

def make_sales_invoice(
	source_name: str, target_doc: Document | str | None = None, args: dict | str | None = None
):
	if args is None:
		args = {}
	if isinstance(args, str):
		args = json.loads(args)

	doc = frappe.get_doc("Delivery Note", source_name)
	if doc.status == "Closed":
		frappe.throw(_("Delivery Note {0} is closed and cannot be invoiced").format(frappe.bold(doc.name)))

	to_make_invoice_qty_map = {}
	returned_qty_map = get_returned_qty_map(source_name)
	invoiced_qty_map = get_invoiced_qty_map(source_name)
	for ref, qty in get_qty_already_mapped(target_doc, "dn_detail").items():
		invoiced_qty_map[ref] = invoiced_qty_map.get(ref, 0) + qty

	def set_missing_values(source, target):
		target.update_stock = 0
		target.run_method("set_missing_values")
		target.run_method("set_po_nos")

		if len(target.get("items")) == 0:
			frappe.throw(_("All these items have already been Invoiced/Returned"))

		if args and args.get("merge_taxes"):
			merge_taxes(source, target)

		target.run_method("calculate_taxes_and_totals")

		# set company address
		if source.company_address:
			target.update({"company_address": source.company_address})
		else:
			# set company address
			target.update(get_company_address(target.company))

		if target.company_address:
			target.update(get_fetch_values("Sales Invoice", "company_address", target.company_address))

	def update_item(source_doc, target_doc, source_parent):
		target_doc.qty = to_make_invoice_qty_map[source_doc.name]
		target_doc._old_name = source_doc.name

	def get_pending_qty(item_row):
		pending_qty = item_row.qty - invoiced_qty_map.get(item_row.name, 0)

		returned_qty = 0
		if returned_qty_map.get(item_row.name, 0) > 0:
			returned_qty = flt(returned_qty_map.get(item_row.name, 0))
			returned_qty_map[item_row.name] -= pending_qty

		if returned_qty:
			if returned_qty >= pending_qty:
				pending_qty = 0
				returned_qty -= pending_qty
			else:
				pending_qty -= returned_qty
				returned_qty = 0

		to_make_invoice_qty_map[item_row.name] = pending_qty

		return pending_qty

	def select_item(d):
		filtered_items = args.get("filtered_children", [])
		child_filter = d.name in filtered_items if filtered_items else True
		return child_filter and not d.si_detail

	doc = get_mapped_doc(
		"Delivery Note",
		source_name,
		{
			"Delivery Note": {
				"doctype": "Sales Invoice",
				"field_map": {"is_return": "is_return"},
				"validation": {"docstatus": ["=", 1]},
			},
			"Delivery Note Item": {
				"doctype": "Sales Invoice Item",
				"field_map": {
					"name": "dn_detail",
					"parent": "delivery_note",
					"so_detail": "so_detail",
					"against_sales_order": "sales_order",
					"cost_center": "cost_center",
				},
				"postprocess": update_item,
				"filter": lambda d: get_pending_qty(d) <= 0
				if not doc.get("is_return")
				else get_pending_qty(d) >= 0,
				"condition": select_item,
			},
			"Sales Taxes and Charges": {
				"doctype": "Sales Taxes and Charges",
				"reset_value": not (args and args.get("merge_taxes")),
				"ignore": args.get("merge_taxes") if args else 0,
			},
			"Sales Team": {
				"doctype": "Sales Team",
				"field_map": {"incentives": "incentives"},
				"add_if_empty": True,
			},
		},
		target_doc,
		set_missing_values,
	)

	automatically_fetch_payment_terms = cint(
		frappe.get_single_value("Accounts Settings", "automatically_fetch_payment_terms")
	)

	if doc.is_return:
		# A credit note made from a return Delivery Note should roll back the billed
		# amount on the linked Sales Order too, so that per_billed stays consistent with
		# per_delivered (which the return already reset).
		doc.update_billed_amount_in_sales_order = True
	else:
		so, doctype, fieldname = doc.get_order_details()
		if (
			doc.linked_order_has_payment_terms(so, fieldname, doctype)
			and not automatically_fetch_payment_terms
		):
			payment_terms_template = frappe.db.get_value(doctype, so, "payment_terms_template")
			doc.payment_terms_template = payment_terms_template
			doc.due_date = get_due_date(
				doc.posting_date,
				"Customer",
				doc.customer,
				doc.company,
				template_name=doc.payment_terms_template,
			)

		elif automatically_fetch_payment_terms:
			doc.set_payment_schedule()

	return doc

def get_original_rows(return_doc) -> list:
	linked = {d.dn_detail for d in return_doc.items if d.dn_detail}
	item_codes = {d.item_code for d in return_doc.items}
	rows = {}
	fields = ["name", "item_code", "idx"]
	if linked:
		for row in frappe.get_all(
			"Delivery Note Item", filters={"name": ("in", list(linked))}, fields=fields
		):
			rows[row.name] = row

	if return_doc.return_against:
		for row in frappe.get_all(
			"Delivery Note Item",
			filters={"parent": return_doc.return_against, "item_code": ("in", list(item_codes))},
			fields=fields,
		):
			rows[row.name] = row

	return sorted(rows.values(), key=lambda row: row.idx)

def apply_earlier_credits(available: dict, original_rows: list, return_doc) -> None:
	earlier_credits = get_earlier_credits(original_rows, return_doc)
	for earlier in earlier_credits:
		if earlier.dn_detail in available:
			take_credit(available, [earlier.dn_detail], earlier.stock_qty)

	for earlier in earlier_credits:
		if not earlier.dn_detail:
			sources = [d.name for d in original_rows if d.item_code == earlier.item_code]
			take_credit(available, sources, earlier.stock_qty)

def get_billed_stock_qty(original_rows: set) -> dict:
	si = frappe.qb.DocType("Sales Invoice")
	sii = frappe.qb.DocType("Sales Invoice Item")
	invoiced = {
		row.dn_detail: row
		for row in (
			frappe.qb.from_(sii)
			.join(si)
			.on(si.name == sii.parent)
			.select(sii.dn_detail, Sum(sii.stock_qty).as_("stock_qty"), Sum(sii.amount).as_("amount"))
			.where(
				sii.dn_detail.isin(list(original_rows))
				& (sii.docstatus == 1)
				& ((si.is_return == 0) | (si.update_billed_amount_in_delivery_note == 1))
			)
			.groupby(sii.dn_detail)
		).run(as_dict=True)
	}

	billed_qty = {}
	for row in frappe.get_all(
		"Delivery Note Item",
		filters={"name": ("in", list(original_rows))},
		fields=["name", "billed_amt", "rate", "qty", "conversion_factor"],
	):
		factor = flt(row.conversion_factor) or 1
		billed_qty[row.name] = get_row_billed_qty(row, invoiced.get(row.name)) * factor

	return billed_qty

def get_row_billed_qty(row, invoiced) -> float:
	direct_qty = flt(invoiced.stock_qty) / (flt(row.conversion_factor) or 1) if invoiced else 0.0
	if not flt(row.rate):
		return direct_qty if invoiced else flt(row.qty)

	direct_amount = flt(invoiced.amount) if invoiced else 0.0
	order_billed_amount = max(flt(row.billed_amt) - direct_amount, 0.0)
	return direct_qty + flt(order_billed_amount / flt(row.rate), 6)

def validate_delivery_note(self):
	"""Raises an exception if the `Delivery Note` status is not Draft"""

	if cint(frappe.db.get_value("Delivery Note", self.delivery_note, "docstatus")) != 0:
		frappe.throw(
			_("A Packing Slip can only be created for Draft Delivery Note.").format(self.delivery_note)
		)

def validate_case_nos(self):
	"""Validate if case nos overlap. If they do, recommend next case no."""

	if cint(self.from_case_no) <= 0:
		frappe.throw(_("The 'From Package No.' field must neither be empty nor it's value less than 1."))
	elif not self.to_case_no:
		self.to_case_no = self.from_case_no
	elif cint(self.to_case_no) < cint(self.from_case_no):
		frappe.throw(_("'To Package No.' cannot be less than 'From Package No.'"))
	else:
		ps = frappe.qb.DocType("Packing Slip")
		res = (
			frappe.qb.from_(ps)
			.select(
				ps.name,
			)
			.where(
				(ps.delivery_note == self.delivery_note)
				& (ps.docstatus == 1)
				& (
					(ps.from_case_no.between(self.from_case_no, self.to_case_no))
					| (ps.to_case_no.between(self.from_case_no, self.to_case_no))
					| ((ps.from_case_no <= self.from_case_no) & (ps.to_case_no >= self.from_case_no))
				)
			)
		).run()

		if res:
			frappe.throw(
				_("""Package No(s) already in use. Try from Package No {0}""").format(
					self.get_recommended_case_no()
				)
			)

def validate_items(self):
	references = {}
	for item in self.items:
		if item.qty <= 0:
			frappe.throw(_("Row {0}: Qty must be greater than 0.").format(item.idx))

		if not item.dn_detail and not item.pi_detail:
			frappe.throw(
				_("Row {0}: Either Delivery Note Item or Packed Item reference is mandatory.").format(
					item.idx
				)
			)

		reference = self.get_reference_row(item)
		self.validate_reference_row(item, reference)
		self.validate_remaining_qty(item, flt(reference.qty) - flt(reference.packed_qty))
		references[item.dn_detail or item.pi_detail] = reference

	self.validate_total_qty_per_reference(references)

def validate_total_qty_per_reference(self, references):
	qty_by_reference = {}
	for item in self.items:
		key = item.dn_detail or item.pi_detail
		qty_by_reference[key] = qty_by_reference.get(key, 0) + flt(item.qty)

		reference = references[key]
		remaining_qty = flt(reference.qty) - flt(reference.packed_qty)
		if qty_by_reference[key] > remaining_qty:
			frappe.throw(
				_("Row {0}: Total packed qty cannot be greater than {1} for the Item {2}.").format(
					item.idx, frappe.bold(remaining_qty), frappe.bold(item.item_code)
				)
			)

def validate_reference_row(self, item, reference):
	if not reference or reference.parent != self.delivery_note or reference.item_code != item.item_code:
		frappe.throw(
			_("Row {0}: Please provide a valid Delivery Note Item or Packed Item reference.").format(
				item.idx
			)
		)

def validate_remaining_qty(self, item, remaining_qty):
	if remaining_qty <= 0:
		frappe.throw(
			_("Row {0}: Packing Slip is already created for Item {1}.").format(
				item.idx, frappe.bold(item.item_code)
			)
		)
	elif item.qty > remaining_qty:
		frappe.throw(
			_("Row {0}: Qty cannot be greater than {1} for the Item {2}.").format(
				item.idx, frappe.bold(remaining_qty), frappe.bold(item.item_code)
			)
		)

def set_missing_values(self):
	if not self.from_case_no:
		self.from_case_no = self.get_recommended_case_no()

	for item in self.items:
		weight_per_unit, weight_uom = frappe.db.get_value(
			"Item", item.item_code, ["weight_per_unit", "weight_uom"]
		)

		if weight_per_unit and not item.net_weight:
			item.net_weight = flt(weight_per_unit) * self.get_conversion_factor(item)
		if weight_uom and not item.weight_uom:
			item.weight_uom = weight_uom

def calculate_net_total_pkg(self):
	self.net_weight_uom = self.items[0].weight_uom if self.items else None
	self.gross_weight_uom = self.net_weight_uom

	net_weight_pkg = 0
	for item in self.items:
		if item.weight_uom != self.net_weight_uom:
			frappe.throw(
				_(
					"Different UOM for items will lead to incorrect (Total) Net Weight value. Make sure that Net Weight of each item is in the same UOM."
				)
			)

		net_weight_pkg += flt(item.net_weight) * flt(item.qty)

	self.net_weight_pkg = round(net_weight_pkg, 2)

	if not flt(self.gross_weight_pkg):
		self.gross_weight_pkg = self.net_weight_pkg

def get_recommended_case_no(self):
	"""Returns the next case no. for a new packing slip for a delivery note"""

	return (
		cint(
			frappe.db.get_value(
				"Packing Slip",
				{"delivery_note": self.delivery_note, "docstatus": 1},
				[{"MAX": "to_case_no"}],
			)
		)
		+ 1
	)

def get_reference_row(self, item):
	return frappe.db.get_value(
		"Delivery Note Item" if item.dn_detail else "Packed Item",
		{"name": item.dn_detail or item.pi_detail, "docstatus": 0},
		["parent", "item_code", "qty", "packed_qty"],
		as_dict=True,
	)

def get_conversion_factor(self, item):
	if not item.dn_detail:
		return 1.0

	return flt(frappe.db.get_value("Delivery Note Item", item.dn_detail, "conversion_factor")) or 1.0

def _compute_show_check_availability(self):
    """ According to `picking.show_check_availability`, the "Reserve" button will be
    displayed in the form view of a picking.
    """
    for picking in self:
        if picking.state not in ('confirmed', 'waiting', 'assigned'):
            picking.show_check_availability = False
            continue
        if all(m.picked or m.product_uom_qty == m.quantity for m in picking.move_ids):
            picking.show_check_availability = False
            continue
        picking.show_check_availability = any(
            move.state in ('waiting', 'confirmed', 'partially_available') and
            move.uom_id.compare(move.product_uom_qty, 0)
            for move in picking.move_ids
        )

def _check_move_lines_map_quant_package(self, package):
    return package._check_move_lines_map_quant(self.move_line_ids.filtered(lambda ml:
        ml.product_id.is_storable
        and (ml.package_id == package or ml.package_id in package.all_children_package_ids)))

def _check_entire_pack(self):
    """ This function check if entire packs are moved in the picking"""
    for package, package_move_lines in self.move_line_ids.grouped('package_id').items():
        if not package:
            continue
        pickings = package_move_lines.picking_id
        if pickings._is_single_transfer() and pickings._check_move_lines_map_quant_package(package):
            move_lines_to_pack = package_move_lines.filtered(lambda ml: not ml.result_package_id and ml.state not in ('done', 'cancel'))
            if package.package_type_id.package_use != 'reusable':
                move_lines_to_pack.write({
                    'result_package_id': package.id,
                    'is_entire_pack': True,
                })
    # If we move all packages within a package, we can consider that they keep their container as well
    self.move_line_ids.result_package_id._apply_package_dest_for_entire_packs()

def _get_lot_move_lines_for_sanity_check(self, none_done_picking_ids, separate_pickings=True):
    """ Get all move_lines with tracked products that need to be checked over in the sanity check.
        :param none_done_picking_ids: Set of all pickings ids that have no quantity set on any move_line.
        :param separate_pickings: Indicates if pickings should be checked independently for lot/serial numbers or not.
    """
    def get_relevant_move_line_ids(none_done_picking_ids, picking):
        # Get all move_lines if picking has no quantity set, otherwise only get the move_lines with some quantity set.
        if picking.id in none_done_picking_ids:
            return picking.move_line_ids.filtered(lambda ml: ml.product_id and ml.product_id.tracking in ['lot', 'serial']).ids
        else:
            return get_line_with_done_qty_ids(picking.move_line_ids)

    def get_line_with_done_qty_ids(move_lines):
        # Get only move_lines that has some quantity set.
        return move_lines.filtered(lambda ml: ml.product_id.tracking in ['lot', 'serial'] and ml.picked and ml.uom_id.compare(ml.quantity, 0)).ids

    if separate_pickings:
        # If pickings are checked independently, get full/partial move_lines depending if each picking has no quantity set.
        lines_to_check_ids = [line_id for picking in self for line_id in get_relevant_move_line_ids(none_done_picking_ids, picking)]
    else:
        # If pickings are checked as one (like in a batch), then get only the move_lines with quantity across all pickings if there is at least one.
        if any(picking.id not in none_done_picking_ids for picking in self):
            lines_to_check_ids = get_line_with_done_qty_ids(self.move_line_ids)
        else:
            lines_to_check_ids = self.move_line_ids.filtered(lambda ml: ml.product_id and ml.product_id.tracking in ['lot', 'serial']).ids

    return self.env['stock.move.line'].browse(lines_to_check_ids)

def _sanity_check(self, separate_pickings=True):
    """ Sanity check for `button_validate()`
        :param separate_pickings: Indicates if pickings should be checked independently for lot/serial numbers or not.
    """
    pickings_without_lots = self.browse()
    products_without_lots = self.env['product.product']
    pickings_without_moves = self.filtered(lambda p: not p.move_ids and not p.move_line_ids)
    precision_digits = self.env['decimal.precision'].precision_get('Product Unit')

    no_quantities_done_ids = set()
    pickings_without_quantities = self.env['stock.picking']
    for picking in self:
        has_pick = any(move.picked and move.state not in ('done', 'cancel') for move in picking.move_ids)
        if all(float_is_zero(move.quantity, precision_digits=precision_digits) for move in picking.move_ids.filtered(lambda m: m.state not in ('done', 'cancel') and (not has_pick or m.picked))):
            pickings_without_quantities |= picking

    pickings_using_lots = self.filtered(lambda p: p.picking_type_id.use_create_lots or p.picking_type_id.use_existing_lots)
    if pickings_using_lots:
        lines_to_check = pickings_using_lots._get_lot_move_lines_for_sanity_check(no_quantities_done_ids, separate_pickings)
        for line in lines_to_check:
            if not line.lot_name and not line.lot_id:
                pickings_without_lots |= line.picking_id
                products_without_lots |= line.product_id

    if not self._should_show_transfers():
        if pickings_without_moves:
            raise UserError(_("You can’t validate an empty transfer. Please add some products to move before proceeding."))
        if pickings_without_quantities:
            raise UserError(self._get_without_quantities_error_message())
        if pickings_without_lots:
            raise UserError(_('You need to supply a Lot/Serial number for products %s.', ', '.join(products_without_lots.mapped('display_name'))))
    else:
        message = ""
        if pickings_without_moves:
            message += _('Transfers %s: Please add some items to move.', ', '.join(pickings_without_moves.mapped('name')))
        if pickings_without_lots:
            message += _(
                '\n\nTransfers %(transfer_list)s: You need to supply a Lot/Serial number for products %(product_list)s.',
                transfer_list=pickings_without_lots.mapped('name'),
                product_list=products_without_lots.mapped('display_name'),
            )
        if message:
            raise UserError(message.lstrip())

def button_validate(self):
    self = self.filtered(lambda p: p.state != 'done')
    draft_picking = self.filtered(lambda p: p.state == 'draft')
    res = draft_picking.with_context(to_validate=True).action_confirm()
    if res is not True:
        return res
    for move in draft_picking.move_ids:
        if move.uom_id.is_zero(move.quantity) and not move.uom_id.is_zero(move.product_uom_qty):
            move.quantity = move.product_uom_qty

    # Sanity checks.
    if not self.env.context.get('skip_sanity_check', False):
        self._sanity_check()

    # Run the pre-validation wizards. Processing a pre-validation wizard should work on the
    # moves and/or the context and never call `_action_done`.
    if not self.env.context.get('button_validate_picking_ids'):
        self = self.with_context(button_validate_picking_ids=self.ids)
    res = self._pre_action_done_hook()
    if res is not True:
        return res

    # Call `_action_done`.
    pickings_not_to_backorder = self.filtered(lambda p: p.picking_type_id.create_backorder == 'never')
    if self.env.context.get('picking_ids_not_to_backorder'):
        pickings_not_to_backorder |= self.browse(self.env.context['picking_ids_not_to_backorder']).filtered(
            lambda p: p.picking_type_id.create_backorder != 'always'
        )
    pickings_to_backorder = self - pickings_not_to_backorder
    if pickings_not_to_backorder:
        pickings_not_to_backorder.with_context(cancel_backorder=True)._action_done()
    if pickings_to_backorder:
        pickings_to_backorder.with_context(cancel_backorder=False)._action_done()

    # Remove done pickings from their batch.
    if any(picking.state == 'done' for picking in self):
        to_assign_ids = set()
        if self and self.env.context.get('pickings_to_detach'):
            pickings_to_detach = self.env['stock.picking'].browse(self.env.context['pickings_to_detach'])
            pickings_to_detach.batch_id = False
            pickings_to_detach.move_ids.filtered(lambda m: not m.quantity).picked = False
            to_assign_ids.update(self.env.context['pickings_to_detach'])

        for picking in self:
            if picking.state != 'done':
                continue
            # Avoid inconsistencies in states of the same batch when validating a single picking in a batch.
            if picking.batch_id and any(p.state != 'done' for p in picking.batch_id.picking_ids):
                picking.batch_id = None
            # If backorder were made and auto-batch is enabled, seek a batch for each of them with the selected criterias.
            to_assign_ids.update(picking.backorder_ids.ids)

        # If batch setting is enabled, auto-batch done pickings' backorders.
        if self.env.user.has_group('stock.group_stock_picking_batch'):
            # To avoid inconsistencies, all incorrect pickings must be removed before assigning backorder pickings
            assignable_pickings = self.env['stock.picking'].browse(to_assign_ids)
            for picking in assignable_pickings:
                picking._find_auto_batch()
            assignable_pickings.move_line_ids.with_context(skip_auto_waveable=True)._auto_wave()

    report_actions = self._get_autoprint_report_actions()
    if report_actions:
        return {
            'type': 'ir.actions.client',
            'tag': 'do_multi_print',
            'params': {
                'reports': report_actions,
            }
        }
    return True

def _check_backorder(self):
    prec = self.env["decimal.precision"].precision_get("Product Unit")
    backorder_pickings = self.browse()
    for picking in self:
        if picking.picking_type_id.create_backorder != 'ask':
            continue
        if any(
                (move.product_uom_qty and not move.picked) or
                float_compare(move._get_picked_quantity(), move.product_uom_qty, precision_digits=prec) < 0
                for move in picking.move_ids
                if move.state != 'cancel'
        ):
            backorder_pickings |= picking
    return backorder_pickings

def _create_backorder_picking(self):
    self.ensure_one()
    return self.copy({
        'name': '/',
        'move_ids': [],
        'move_line_ids': [],
        'backorder_id': self.id,
        'return_id': self.return_id.id,
    })

def write(self, vals):
    if vals.get('picking_type_id') and any(picking.state in ('done', 'cancel') for picking in self):
        raise UserError(_("Changing the operation type of this record is forbidden at this point."))

    old_batches = self.batch_id
    if vals.get('picking_type_id'):
        picking_type = self.env['stock.picking.type'].browse(vals.get('picking_type_id'))
        for picking in self:
            if picking.picking_type_id != picking_type:
                picking.name = picking_type.sequence_id.next_by_id()
                vals['location_id'] = picking_type.default_location_src_id.id
                vals['location_dest_id'] = picking_type.default_location_dest_id.id
    res = super().write(vals)

    if vals.get('batch_id'):
        old_batches.filtered(lambda b: not b.picking_ids).state = 'cancel'
        if not self.batch_id.picking_type_id:
            self.batch_id.picking_type_id = self.picking_type_id[0]
        self.batch_id._sanity_check()
        # assign batch users to batch pickings
        self.batch_id.picking_ids.assign_batch_user(self.batch_id.user_id.id)
    if vals.get('date_done'):
        self.filtered(lambda p: p.state == 'done').move_ids.date = vals['date_done']
    if vals.get('signature'):
        for picking in self:
            picking._attach_sign()
    # Change locations of moves if those of the picking change
    after_vals = {}
    if vals.get('location_id'):
        after_vals['location_id'] = vals['location_id']
    if vals.get('location_dest_id'):
        after_vals['location_dest_id'] = vals['location_dest_id']
    if after_vals:
        self.move_ids.filtered(lambda move: move.location_dest_usage != 'inventory').write(after_vals)
    if vals.get('move_ids'):
        self._autoconfirm_picking()

    return res

def _is_single_transfer(self):
    # Overriden for batches.
    if self.env.user.has_group('stock.group_stock_picking_batch'):
        return len(self) == 1 or len(self.batch_id) == 1
    return len(self) == 1

def _should_show_transfers(self):
    """Whether the different transfers should be displayed on the pre action done wizards."""
    if self.batch_id:
        picking_ids_to_detach = self.env.context.get('pickings_to_detach') or []
        batch_pickings_count = len(self.batch_id.picking_ids) - len(picking_ids_to_detach)
        if len(self.batch_id) == 1 and len(self) == batch_pickings_count:
            return False
    return len(self) > 1

def _get_without_quantities_error_message(self):
    """ Returns the error message raised in validation if no quantities are reserved.
    The purpose of this method is to be overridden in case we want to adapt this message.

    :return: Translated error message
    :rtype: str
    """
    return _(
        "Transfer trouble alert! Validating a zero quantity transfer? You're not moving invisible goods around are you?\n"
        "Set some quantities and let's get moving!"
    )

def action_confirm(self):
    self._check_company()
    if not self.env.context.get('skip_zero_demand_check') and not modules.module.current_test:
        # Check for zero demand moves before confirming
        zero_demand_moves = self.move_ids.filtered(lambda m: m.product_uom_qty <= 0)
        if zero_demand_moves:
            return self._action_generate_zero_demand_wizard()

    # call `_action_confirm` on every draft move
    self.move_ids.filtered(lambda move: move.state == 'draft')._action_confirm()

    # run scheduler for moves forecasted to not have enough in stock
    self.move_ids.filtered(lambda move: move.state not in ('draft', 'cancel', 'done'))._trigger_scheduler()

    if self.env.user.has_group('stock.group_stock_picking_batch'):
        for picking in self:
            picking._find_auto_batch()
    return True

def _pre_action_done_hook(self):
    for picking in self:
        has_quantity = False
        has_pick = False
        for move in picking.move_ids:
            if move.quantity:
                has_quantity = True
            if move.location_dest_usage == 'inventory':
                continue
            if move.picked:
                has_pick = True
            if has_quantity and has_pick:
                break
        if has_quantity and not has_pick:
            picking.move_ids.picked = True
    if not self.env.context.get('skip_backorder'):
        pickings_to_backorder = self._check_backorder()
        if pickings_to_backorder:
            return pickings_to_backorder._action_generate_backorder_wizard(show_transfers=self._should_show_transfers())
    return True

def _get_moves_to_backorder(self):
    self.ensure_one()
    return self.move_ids.filtered(lambda x: x.state not in ('done', 'cancel'))

def _autoconfirm_picking(self):
    """ Automatically run `action_confirm` on `self` if one of the
    picking's move was added after the initial
    call to `action_confirm`. Note that `action_confirm` will only work on draft moves.
    """
    for picking in self:
        if picking.state in ('done', 'cancel'):
            continue
        if not picking.move_ids:
            continue
        if any(move.additional for move in picking.move_ids):
            picking.with_context(skip_zero_demand_check=True).action_confirm()
    to_confirm = self.move_ids.filtered(lambda m: m.state == 'draft' and m.quantity)
    to_confirm._action_confirm()

def assign_batch_user(self, user_id):
    pickings = self.filtered(lambda p: p.user_id.id != user_id)
    pickings.write({'user_id': user_id})
    for pick in pickings:
        if user_id:
            log_message = _('Assigned to %s Responsible', pick.batch_id._get_html_link())
        else:
            log_message = _('Unassigned responsible from %s', pick.batch_id._get_html_link())
        pick.message_post(body=log_message)

def _intercompany_unpack(self):
    if not self.env.user.has_group('stock.group_tracking_lot') or\
       not self.env['ir.config_parameter'].sudo().get_bool('stock.intercompany_auto_unpack'):
        return
    for picking in self:
        if not picking.partner_id:
            continue
        destination_company = self.env['res.company'].sudo().search([('partner_id', 'parent_of', picking.partner_id.id)], limit=1)
        if destination_company == picking.company_id:
            continue
        moves = picking.move_ids.filtered(lambda m: m.location_dest_id.usage == 'transit')
        moves.move_line_ids.result_package_id.unpack()

def _send_confirmation_email(self):
    subtype_id = self.env['ir.model.data']._xmlid_to_res_id('mail.mt_comment')
    for stock_pick in self.filtered(lambda p: p.company_id.stock_move_email_validation and p.picking_type_id.code == 'outgoing'):
        delivery_template = stock_pick.company_id.stock_mail_confirmation_template_id
        stock_pick.with_context(force_send=True).message_post_with_source(
            delivery_template,
            email_layout_xmlid='mail.mail_notification_light',
            subtype_id=subtype_id,
        )

def create(self, vals_list):
    scheduled_dates = []
    for vals in vals_list:
        defaults = self.default_get(['name', 'picking_type_id'])
        picking_type = self.env['stock.picking.type'].browse(vals.get('picking_type_id', defaults.get('picking_type_id')))
        if vals.get('name', '/') == '/' and defaults.get('name', '/') == '/' and vals.get('picking_type_id', defaults.get('picking_type_id')):
            if picking_type.sequence_id:
                vals['name'] = picking_type.sequence_id.next_by_id()

        # make sure to write `schedule_date` *after* the `stock.move` creation in
        # order to get a determinist execution of `_set_scheduled_date`
        scheduled_dates.append(vals.pop('scheduled_date', False))

    pickings = super().create(vals_list)

    for picking, scheduled_date in zip(pickings, scheduled_dates):
        if scheduled_date:
            picking.with_context(mail_notrack=True).write({'scheduled_date': scheduled_date})
    pickings._autoconfirm_picking()

    for picking, vals in zip(pickings, vals_list):
        if vals.get('batch_id'):
            if not picking.batch_id.picking_type_id:
                picking.batch_id.picking_type_id = picking.picking_type_id[0]
            picking.batch_id._sanity_check()

    return pickings

def _get_possible_pickings_domain(self):
    self.ensure_one()
    domain = [
        ('id', '!=', self.id),
        ('company_id', '=', self.company_id.id if self.company_id else False),
        ('state', '=', 'assigned'),
        ('picking_type_id', '=', self.picking_type_id.id),
        ('batch_id', '=', False),
    ]
    if self.picking_type_id.batch_group_by_partner:
        domain.append(('partner_id', '=', self.partner_id.id))
    if self.picking_type_id.batch_group_by_destination:
        domain.append(('partner_id.country_id', '=', self.partner_id.country_id.id))
    if self.picking_type_id.batch_group_by_src_loc:
        domain.append(('location_id', '=', self.location_id.id))
    if self.picking_type_id.batch_group_by_dest_loc:
        domain.append(('location_dest_id', '=', self.location_dest_id.id))

    return Domain(domain)

def _get_possible_batches_domain(self):
    self.ensure_one()
    domain = [
        ('state', 'in', ('draft', 'in_progress') if self.picking_type_id.batch_auto_confirm else ('draft',)),
        ('picking_type_id', '=', self.picking_type_id.id),
        ('company_id', '=', self.company_id.id if self.company_id else False),
        ('is_wave', '=', False)
    ]
    if self.picking_type_id.batch_group_by_partner:
        domain.append(('picking_ids.partner_id', '=', self.partner_id.id))
    if self.picking_type_id.batch_group_by_destination:
        domain.append(('picking_ids.partner_id.country_id', '=', self.partner_id.country_id.id))
    if self.picking_type_id.batch_group_by_src_loc:
        domain.append(('picking_ids.location_id', '=', self.location_id.id))
    if self.picking_type_id.batch_group_by_dest_loc:
        domain.append(('picking_ids.location_dest_id', '=', self.location_dest_id.id))
    if self.env.context.get('batches_to_validate'):
        domain.append(('id', 'not in', self.env.context.get('batches_to_validate')))

    return Domain(domain)

def _get_auto_batch_description(self):
    """ Get the description of the automatically created batch based on the grouped pickings and grouping criteria """
    self.ensure_one()
    description_items = []
    if self.picking_type_id.batch_group_by_partner and self.partner_id:
        description_items.append(self.partner_id.name or '')
    if self.picking_type_id.batch_group_by_destination and self.partner_id.country_id:
        description_items.append(self.partner_id.country_id.name)
    if self.picking_type_id.batch_group_by_src_loc and self.location_id:
        description_items.append(self.location_id.display_name)
    if self.picking_type_id.batch_group_by_dest_loc and self.location_dest_id:
        description_items.append(self.location_dest_id.display_name)
    return ', '.join(description_items)

def _is_auto_batchable(self, picking=None):
    """ Verifies if a picking can be put in a batch with another picking without violating auto_batch constrains.
    """
    if self.state != 'assigned':
        return False
    if self.picking_type_id.batch_max_lines:
        picking = picking or self.env['stock.picking']
        moves_count = len(set(self.move_ids.ids + picking.move_ids.ids))
        if moves_count > self.picking_type_id.batch_max_lines:
            return False
    return True

def receive(cls, shipments):
    Move = Pool().get('stock.move')
    with Move.bulk_func('do', auto=False) as do:
        for shipment in shipments:
            do.extend(shipment.incoming_moves)
    with Move.bulk_delete(auto=False) as delete:
        for shipment in shipments:
            for move in shipment.inventory_moves:
                if move.state in {'draft', 'cancelled'}:
                    delete.push(move)
    cls.create_inventory_moves(shipments)
    # Set received state to allow done transition
    cls.write(shipments, {'state': 'received'})
    with cls.bulk_func('do', auto=False) as do:
        for shipment in shipments:
            if shipment.warehouse_storage == shipment.warehouse_input:
                do.push(shipment)

def pack(cls, shipments):
    pool = Pool()
    Move = pool.get('stock.move')
    with Move.bulk_delete() as delete:
        outgoing_moves = []
        for shipment in shipments:
            for move in shipment.inventory_moves:
                if move.state not in {'done', 'cancelled'}:
                    raise AccessError(
                        gettext('stock.msg_shipment_pack_inventory_done',
                            shipment=shipment.rec_name))
            if shipment.warehouse_storage != shipment.warehouse_output:
                shipment.check_quantity()
            for move in shipment.outgoing_moves:
                if move.quantity:
                    outgoing_moves.append(move)
                else:
                    delete.push(move)
    Move.assign(outgoing_moves)

def create_inventory_moves(cls, shipments):
    for shipment in shipments:
        if shipment.warehouse_storage == shipment.warehouse_input:
            # Do not create inventory moves
            continue
        # Use moves instead of inventory_moves because save reset before
        # adding new records and as set_inventory_moves is just a proxy to
        # moves, it will reset also the incoming_moves
        moves = list(shipment.moves)
        for incoming_move in shipment.incoming_moves:
            move = shipment._get_inventory_move(incoming_move)
            if move:
                moves.append(move)
        shipment.moves = moves
    cls.save(shipments)

def draft(cls, shipments):
    Move = Pool().get('stock.move')
    Move.draft([m for s in shipments for m in s.outgoing_moves
            if m.state != 'staging'])
    Move.delete([m for s in shipments for m in s.inventory_moves
            if m.state in {'staging', 'draft', 'cancelled'}])

def _sync_inventory_to_outgoing(cls, shipments, quantity=True):
    pool = Pool()
    Move = pool.get('stock.move')
    Uom = pool.get('product.uom')

    def active(move):
        return move.state != 'cancelled'

    moves, imoves = [], []
    for shipment in shipments:
        if shipment.warehouse_storage == shipment.warehouse_output:
            # Do not have inventory moves
            continue

        outgoing_moves = {m: m for m in shipment.outgoing_moves}
        inventory_qty = defaultdict(lambda: defaultdict(float))
        inventory_moves = defaultdict(lambda: defaultdict(list))
        for move in filter(active, shipment.outgoing_moves):
            key = shipment._sync_move_key(move)
            inventory_qty[move][key] = 0
        for move in filter(active, shipment.inventory_moves):
            key = shipment._sync_move_key(move)
            outgoing_move = outgoing_moves.get(move.origin)
            qty_default_uom = Uom.compute_qty(
                move.unit, move.quantity,
                move.product.default_uom, round=False)
            inventory_qty[outgoing_move][key] += qty_default_uom
            inventory_moves[outgoing_move][key].append(move)

        for outgoing_move in inventory_qty:
            if outgoing_move:
                outgoing_key = shipment._sync_move_key(outgoing_move)
            for key, qty in inventory_qty[outgoing_move].items():
                if not quantity and outgoing_move:
                    # Do not create outgoing move with origin
                    # to allow to reset to draft
                    continue
                if outgoing_move and key == outgoing_key:
                    move = outgoing_move
                else:
                    move = shipment._sync_outgoing_move(outgoing_move)
                    for name, value in key:
                        setattr(move, name, value)
                    for imove in inventory_moves[outgoing_move][key]:
                        imove.origin = move
                        imoves.append(imove)
                qty = Uom.compute_qty(
                    move.product.default_uom, qty, move.unit)
                if quantity and move.quantity != qty:
                    move.quantity = qty
                moves.append(move)
    Move.save(moves)
    Move.save(imoves)

def do(cls, shipments):
    pool = Pool()
    Move = pool.get('stock.move')
    Date = pool.get('ir.date')

    Move.delete([
            m for s in shipments for m in s.outgoing_moves
            if m.state == 'staging'])
    Move.do([m for s in shipments for m in s.outgoing_moves])
    for company, c_shipments in groupby(
            shipments, key=lambda s: s.company):
        with Transaction().set_context(company=company.id):
            today = Date.today()
        cls.write([s for s in c_shipments if not s.effective_date], {
                'effective_date': today,
                })

def _sync_move_key(self, move):
    return (
        ('product', move.product),
        ('unit', move.unit),
        )

protected void processBackorderLine(StockMoveLine stockMoveLine, StockMove newStockMove)
    throws AxelorException {
  if (stockMoveLine.getQty().compareTo(stockMoveLine.getRealQty()) <= 0) {
    return;
  }
  StockMoveLine newStockMoveLine = copySplittedStockMoveLine(stockMoveLine);
  newStockMove.addStockMoveLineListItem(newStockMoveLine);

  Product product = newStockMoveLine.getProduct();
  if (product != null) {
    TrackingNumberConfiguration trackingNumberConfiguration =
        (TrackingNumberConfiguration)
            productCompanyService.get(
                product, "trackingNumberConfiguration", newStockMove.getCompany());

    newStockMoveLine.setTrackingNumber(null);
    stockMoveLineService.assignOrGenerateTrackingNumber(
        newStockMoveLine,
        newStockMove,
        product,
        trackingNumberConfiguration,
        newStockMove.getTypeSelect() == StockMoveRepository.TYPE_OUTGOING
            ? StockMoveLineService.TYPE_SALES
            : StockMoveLineService.TYPE_PURCHASES);
  }
}

protected void checkOngoingInventory(StockMove stockMove) throws AxelorException {

  BatchProcessorHelper batchHelper =
      BatchProcessorHelper.builder().flushAfterBatch(false).build();

  Set<Long> stockLocationIds = new HashSet<>();
  Set<Long> productIds = new HashSet<>();
  Long stockMoveId = stockMove.getId();
  Query<StockMoveLine> smlQuery = getStockMoveLineQuery(stockMoveId);

  batchHelper.<StockMoveLine>forEachByQuery(
      smlQuery,
      sml -> {
        StockLocation from = sml.getFromStockLocation();
        StockLocation to = sml.getToStockLocation();
        if (from != null && from.getTypeSelect() != StockLocationRepository.TYPE_VIRTUAL) {
          stockLocationIds.add(from.getId());
          Set<Long> locationIds =
              stockLocationService
                  .getLocationAndAllParentLocationsIdsOrderedFromTheClosestToTheFurthest(from);
          if (locationIds != null) {
            stockLocationIds.addAll(locationIds);
          }
        }
        if (to != null && to.getTypeSelect() != StockLocationRepository.TYPE_VIRTUAL) {
          stockLocationIds.add(to.getId());
          Set<Long> locationIds =
              stockLocationService
                  .getLocationAndAllParentLocationsIdsOrderedFromTheClosestToTheFurthest(to);
          if (locationIds != null) {
            stockLocationIds.addAll(locationIds);
          }
        }

        if (sml.getProduct() != null) {
          productIds.add(sml.getProduct().getId());
        }
      });

  if (stockLocationIds.isEmpty() || productIds.isEmpty()) {
    return;
  }

  InventoryLineRepository inventoryLineRepo = Beans.get(InventoryLineRepository.class);

  InventoryLine inventoryLine =
      inventoryLineRepo
          .all()
          .filter(
              "self.inventory.isStockMoveBlocked = true\n"
                  + "AND self.inventory.stockLocation.id IN (:stockLocationIds)\n"
                  + "AND self.product.id IN (:productList)")
          .bind("stockLocationIds", stockLocationIds)
          .bind("productList", productIds)
          .fetchOne();

  if (inventoryLine != null) {
    throw new AxelorException(
        inventoryLine,
        TraceBackRepository.CATEGORY_INCONSISTENCY,
        I18n.get(StockExceptionMessage.STOCK_MOVE_19),
        inventoryLine.getInventory().getInventorySeq());
  }
}

