protected void fillNewStockMoveFields(StockMove newStockMove, StockMove stockMove)
    throws AxelorException {
  if (stockMove.getToAddress() != null) {
    newStockMove.setFromAddress(stockMove.getToAddress());
  }

  setStockMoveTypeSelect(newStockMove, stockMove);

  newStockMove.setStockMoveSeq(
      stockMoveToolService.getSequenceStockMove(
          newStockMove.getTypeSelect(), newStockMove.getCompany(), stockMove));

  setStockMoveName(newStockMove, stockMove);

  if (stockMove.getPartner() != null) {
    newStockMove.setShipmentMode(stockMove.getPartner().getShipmentMode());
    newStockMove.setFreightCarrierMode(stockMove.getPartner().getFreightCarrierMode());
    newStockMove.setCarrierPartner(stockMove.getPartner().getCarrierPartner());
  }
  newStockMove.setIsReversion(!stockMove.getIsReversion());
  newStockMove.setReversionOriginStockMove(stockMove);
  newStockMove.setFromAddressStr(stockMove.getToAddressStr());
  newStockMove.setNote(stockMove.getNote());
  newStockMove.setNumOfPackages(stockMove.getNumOfPackages());
  newStockMove.setNumOfPalettes(stockMove.getNumOfPalettes());
  newStockMove.setGrossMass(stockMove.getGrossMass());
  newStockMove.setExTaxTotal(stockMoveToolService.compute(newStockMove));
  newStockMove.setIsWithBackorder(stockMove.getIsWithBackorder());
  newStockMove.setOrigin(stockMove.getOrigin());
  setOrigin(stockMove, newStockMove);
  newStockMove.setGroupProductsOnPrintings(stockMove.getGroupProductsOnPrintings());
}

protected void copyStockMoveLines(
    StockMove newStockMove, List<StockMoveLine> stockMoveLines, boolean split) {
  for (StockMoveLine stockMoveLine : stockMoveLines) {
    if (!split || stockMoveLine.getRealQty().compareTo(stockMoveLine.getQty()) > 0) {
      newStockMove.addStockMoveLineListItem(copyStockMoveLine(stockMoveLine, split));
    }
  }
}

protected void reverseStockMoveLineStockLocation(List<StockMoveLine> newStockMoveLineList) {
  for (StockMoveLine stockMoveLine : newStockMoveLineList) {

    StockLocation toStockLocation = stockMoveLine.getToStockLocation();
    StockLocation fromStockLocation = stockMoveLine.getFromStockLocation();

    stockMoveLine.setFromStockLocation(toStockLocation);
    stockMoveLine.setToStockLocation(fromStockLocation);
  }
}

@Override
public void setOrigin(StockMove oldStockMove, StockMove newStockMove) {
  if (oldStockMove.getInventory() != null) {
    newStockMove.setInventory(oldStockMove.getInventory());
  } else if (oldStockMove.getStockCorrection() != null) {
    newStockMove.setStockCorrection(oldStockMove.getStockCorrection());
  }
}

protected boolean isNewBackorderLinePossible(StockMove stockMove) throws AxelorException {
  return stockMoveLineRepo
          .all()
          .filter("self.stockMove.id = :stockMoveId AND self.qty > self.realQty")
          .bind("stockMoveId", stockMove.getId())
          .count()
      > 0;
}

protected void computeTotalNetMass(
    StockMoveLine stockMoveLine, boolean massesRequiredForStockMoveLine) throws AxelorException {
  BigDecimal netMass = stockMoveLine.getNetMass();
  if (netMass.signum() != 0) {
    BigDecimal totalNetMass = netMass.multiply(stockMoveLine.getRealQty());
    stockMoveLine.setTotalNetMass(totalNetMass);
  } else if (massesRequiredForStockMoveLine) {
    throw new AxelorException(
        stockMoveLine.getStockMove(),
        TraceBackRepository.CATEGORY_NO_VALUE,
        I18n.get(StockExceptionMessage.STOCK_MOVE_18));
  }
}

protected void computeNetMass(
    StockMoveLine stockMoveLine, Unit endUnit, UnitConversionService unitConversionService)
    throws AxelorException {
  BigDecimal netMass = stockMoveLine.getNetMass();
  Product product = stockMoveLine.getProduct();
  if (netMass.signum() == 0) {
    Unit startUnit = product.getMassUnit();
    if (startUnit != null && endUnit != null) {
      netMass =
          unitConversionService.convert(
              startUnit, endUnit, product.getNetMass(), product.getNetMass().scale(), null);
      stockMoveLine.setNetMass(netMass);
    }
  }
}

protected void copyPlannedStockMoveLines(StockMove stockMove) {
  clearPlannedStockMoveLine(stockMove, true);

  final long stockMoveId = stockMove.getId();
  Query<StockMoveLine> query = getStockMoveLineQuery(stockMoveId);
  final StockMove[] stockMoveHolder = {stockMoveRepo.find(stockMoveId)};
  BatchProcessorHelper.of()
      .<StockMoveLine>forEachByQuery(
          query,
          line -> {
            StockMoveLine copy = stockMoveLineRepo.copy(line, false);
            copy.setArchived(true);
            copy.setPlannedStockMove(stockMoveHolder[0]);
            stockMoveLineRepo.save(copy);
          },
          () -> stockMoveHolder[0] = stockMoveRepo.find(stockMoveId));
}

protected void setStockMoveName(StockMove newStockMove, StockMove stockMove) {
  newStockMove.setName(
      stockMoveToolService.computeName(
          newStockMove,
          String.format(
              I18n.get(StockExceptionMessage.STOCK_MOVE_8),
              newStockMove.getStockMoveSeq(),
              stockMove.getStockMoveSeq())));
}

protected void setStockMoveTypeSelect(StockMove newStockMove, StockMove stockMove) {
  switch (stockMove.getTypeSelect()) {
    case StockMoveRepository.TYPE_INCOMING:
      newStockMove.setTypeSelect(StockMoveRepository.TYPE_OUTGOING);
      break;
    case StockMoveRepository.TYPE_OUTGOING:
      newStockMove.setTypeSelect(StockMoveRepository.TYPE_INCOMING);
      break;
    default:
      newStockMove.setTypeSelect(StockMoveRepository.TYPE_INTERNAL);
      break;
  }
}

protected StockMoveLine copyStockMoveLine(StockMoveLine stockMoveLine, boolean split) {
  StockMoveLine newStockMoveLine = stockMoveLineRepo.copy(stockMoveLine, false);

  if (split) {
    newStockMoveLine.setQty(stockMoveLine.getRealQty().subtract(stockMoveLine.getQty()));
    newStockMoveLine.setRealQty(newStockMoveLine.getQty());
  } else {
    newStockMoveLine.setQty(stockMoveLine.getRealQty());
    newStockMoveLine.setRealQty(stockMoveLine.getRealQty());
  }
  return newStockMoveLine;
}

def validate(self):
	self.set_active()
	self.validate_docstatus()

def on_update(self):
	self.create_custom_field_for_workflow_state()
	self.update_default_workflow_status()

def update_default_workflow_status(self):
	docstatus_map = {}
	states = self.get("states")

	TargetDocType = frappe.qb.DocType(self.document_type)
	state_field = getattr(TargetDocType, self.workflow_state_field)

	for d in states:
		if d.doc_status not in docstatus_map:
			(
				frappe.qb.update(TargetDocType)
				.set(state_field, d.state)
				.where(state_field.isnull() | (state_field == ""))
				.where(TargetDocType.docstatus == d.doc_status)
			).run()

			docstatus_map[d.doc_status] = d.state

def validate_docstatus(self):
	def get_state(state):
		for s in self.states:
			if s.state == state:
				return s

		frappe.throw(frappe._("{0} not a valid State").format(state))

	meta = frappe.get_meta(self.document_type)
	is_submittable = meta.is_submittable

	if not is_submittable:
		for state in self.states:
			if cint(state.doc_status) != 0:
				frappe.throw(
					frappe._(
						"Workflow State '{0}' has Document Status {1}, but DocType '{2}' is not submittable. "
						"Only Document Status 0 (Draft) is allowed for non-submittable DocTypes."
					).format(state.state, state.doc_status, self.document_type)
				)

	for t in self.transitions:
		state = get_state(t.state)
		next_state = get_state(t.next_state)
		state_docstatus = cint(state.doc_status)
		next_state_docstatus = cint(next_state.doc_status)

		if state_docstatus == 2:
			frappe.throw(
				frappe._("Cannot change state of Cancelled Document. Transition row {0}").format(t.idx)
			)

		if state_docstatus == 1 and next_state_docstatus == 0:
			frappe.throw(
				frappe._(
					"Submitted Document cannot be converted back to draft. Transition row {0}"
				).format(t.idx)
			)

		if state_docstatus == 0 and next_state_docstatus == 2:
			frappe.throw(frappe._("Cannot cancel before submitting. See Transition {0}").format(t.idx))

def set_active(self):
	if cint(self.is_active):
		Workflow = frappe.qb.DocType("Workflow")
		(
			frappe.qb.update(Workflow)
			.set(Workflow.is_active, 0)
			.where(Workflow.document_type == self.document_type)
		).run()

def write(self, vals: dict):
    clear_templates = self._has_trigger_onchange()
    res = super().write(vals)
    if set(vals).intersection(CRITICAL_FIELDS):
        self._update_cron()
        self._update_registry()
        clear_templates |= self._has_trigger_onchange()
        if clear_templates and any(self._ids):
            # Invalidate templates cache to update on_change attributes if needed
            self.env.transaction.invalidate_ormcache('templates')
    elif set(vals).intersection(RANGE_FIELDS):
        self._update_cron()
    return res

def _register_hook(self):
    """ Patch models that should trigger action rules based on creation,
        modification, deletion of records and form onchanges.
    """
    #
    # Note: the patched methods must be defined inside another function,
    # otherwise their closure may be wrong. For instance, the function
    # create refers to the outer variable 'create', which you expect to be
    # bound to create itself. But that expectation is wrong if create is
    # defined inside a loop; in that case, the variable 'create' is bound to
    # the last function defined by the loop.
    #

    def make_create():
        """ Instanciate a create method that processes automation rules. """
        @api.model_create_multi
        def create(self, vals_list, **kw):
            # retrieve the automation rules to possibly execute
            automations = self.env['base.automation']._get_actions(self, CREATE_TRIGGERS)
            if not automations:
                return create.origin(self, vals_list, **kw)
            # call original method
            records = create.origin(self.with_env(automations.env), vals_list, **kw)
            # check postconditions, and execute actions on the records that satisfy them
            for automation in automations.with_context(old_values=None):
                with _keep_to_compute(self.env, self.env._protected):
                    automation._process(automation._filter_post(records, feedback=True), trigger='create')
            return records.with_env(self.env)

        return create

    def make_write():
        """ Instanciate a write method that processes automation rules. """
        def write(self, vals, **kw):
            # retrieve the automation rules to possibly execute
            automations = self.env['base.automation']._get_actions(self, WRITE_TRIGGERS)
            if not (automations and self):
                return write.origin(self, vals, **kw)
            records = self.with_env(automations.env).filtered('id')
            written_fields = [records._fields[n] for n in vals if n in records._fields]
            # check preconditions on records
            with _keep_to_compute(self.env, written_fields):
                pre = {a: a._filter_pre(records) for a in automations}
            # read old values before the update
            old_values = {
                record.id: {field_name: record[field_name] for field_name in vals if field_name in record._fields and record._fields[field_name].store}
                for record in records
            }
            # call original method
            write.origin(self.with_env(automations.env), vals, **kw)
            # check postconditions, and execute actions on the records that satisfy them
            for automation in automations.with_context(old_values=old_values):
                with _keep_to_compute(self.env, written_fields):
                    records, domain_post = automation._filter_post_export_domain(pre[automation], feedback=True)
                    automation._process(records, domain_post=domain_post, trigger='write')
            return True

        return write

    def make_compute_field_value():
        """ Instanciate a compute_field_value method that processes automation rules. """
        #
        # Note: This is to catch updates made by field recomputations.
        #
        def _compute_field_value(self, field):
            # determine fields that may trigger an automation
            stored_fnames = [f.name for f in self.pool.field_computed[field] if f.store]
            if not stored_fnames:
                return _compute_field_value.origin(self, field)
            # retrieve the action rules to possibly execute
            automations = self.env['base.automation']._get_actions(self, WRITE_TRIGGERS)
            records = self.filtered('id').with_env(automations.env)
            if not (automations and records):
                _compute_field_value.origin(self, field)
                return True
            # check preconditions on records
            # changed fields are all fields computed by the function
            changed_fields = [f for f in records._fields.values() if f.compute == field.compute]
            with _keep_to_compute(self.env, changed_fields):
                pre = {a: a._filter_pre(records) for a in automations}
                # read old values before the update
                old_values = {
                    record.id: {fname: record[fname] for fname in stored_fnames}
                    for record in records
                }
            # call original method
            _compute_field_value.origin(self, field)
            # check postconditions, and execute automations on the records that satisfy them
            for automation in automations.with_context(old_values=old_values):
                with _keep_to_compute(self.env, changed_fields):
                    records, domain_post = automation._filter_post_export_domain(pre[automation], feedback=True)
                    automation._process(records, domain_post=domain_post, trigger='_compute_field_value')
            return True

        return _compute_field_value

    def make_unlink():
        """ Instanciate an unlink method that processes automation rules. """
        def unlink(self, **kwargs):
            # retrieve the action rules to possibly execute
            automations = self.env['base.automation']._get_actions(self, ['on_unlink'])
            records = self.with_env(automations.env)
            # check conditions, and execute actions on the records that satisfy them
            for automation in automations:
                with _keep_to_compute(self.env, self.env._protected):
                    automation._process(automation._filter_post(records, feedback=True), trigger='unlink')
            # call original method
            return unlink.origin(self, **kwargs)

        return unlink

    def make_onchange(automation_rule_id):
        """ Instanciate an onchange method for the given automation rule. """
        def base_automation_onchange(self):
            automation_rule = self.env['base.automation'].browse(automation_rule_id)

            if not automation_rule._filter_post(self):
                # Do nothing if onchange record does not satisfy the filter_domain
                return

            result = {}
            actions = automation_rule.sudo().action_server_ids.with_context(
                active_model=self._name,
                active_id=self._origin.id,
                active_ids=self._origin.ids,
                onchange_self=self,
            )
            for action in actions:
                try:
                    res = action.run()
                except Exception as e:
                    automation_rule._add_postmortem(e)
                    raise

                if res:
                    if 'value' in res:
                        res['value'].pop('id', None)
                        self.update({key: val for key, val in res['value'].items() if key in self._fields})
                    if 'domain' in res:
                        result.setdefault('domain', {}).update(res['domain'])
                    if 'warning' in res:
                        result['warning'] = res["warning"]
            return result

        return base_automation_onchange

    def make_message_post():
        def _message_post(self, *args, **kwargs):
            message = _message_post.origin(self, *args, **kwargs)
            # Don't execute automations for a message emitted during
            # the run of automations for a real message
            # Don't execute if we know already that a message is only internal
            message_sudo = message.sudo().with_context(active_test=False)
            if "__action_done"  in self.env.context or message_sudo.is_internal or message_sudo.subtype_id.internal:
                return message
            if message_sudo.message_type in ('notification', 'auto_comment', 'user_notification'):
                return message

            # always execute actions when the author is a customer
            # if author is not set, it means the message is coming from outside
            mail_trigger = "on_message_received" if not message_sudo.author_id or message_sudo.author_id.partner_share else "on_message_sent"
            automations = self.env['base.automation']._get_actions(self, [mail_trigger])
            for automation in automations.with_context(old_values=None):
                with _keep_to_compute(self.env, self.env._protected):
                    records = automation._filter_pre(self, feedback=True)
                    automation._process(records, trigger='_message_post')

            return message
        return _message_post

    patched_models = defaultdict(set)

    def patch(model, name, method):
        """ Patch method `name` on `model`, unless it has been patched already. """
        if model not in patched_models[name]:
            patched_models[name].add(model)
            ModelClass = model.env.registry[model._name]
            method.origin = getattr(ModelClass, name)
            setattr(ModelClass, name, method)

    # retrieve all actions, and patch their corresponding model
    for automation_rule in self.with_context({}).search([]):
        Model = self.env.get(automation_rule.model_name)

        # Do not crash if the model of the base_action_rule was uninstalled
        if Model is None:
            _logger.warning(
                "Automation rule with name '%s' (ID %d) depends on model %s (ID: %d)",
                automation_rule.name,
                automation_rule.id,
                automation_rule.model_name,
                automation_rule.model_id.id)
            continue

        if automation_rule.trigger in CREATE_WRITE_SET:
            if automation_rule.trigger in CREATE_TRIGGERS:
                patch(Model, 'create', make_create())
            if automation_rule.trigger in WRITE_TRIGGERS:
                patch(Model, 'write', make_write())
                patch(Model, '_compute_field_value', make_compute_field_value())

        elif automation_rule.trigger == 'on_unlink':
            patch(Model, 'unlink', make_unlink())

        elif automation_rule.trigger == 'on_change':
            # register an onchange method for the automation_rule
            method = make_onchange(automation_rule.id)
            for field in automation_rule.on_change_field_ids:
                Model._onchange_methods[field.name].append(method)

        if automation_rule.model_id.is_mail_thread and automation_rule.trigger in MAIL_TRIGGERS:
            patch(Model, "message_post", make_message_post())

def _has_trigger_onchange(self):
    return any(
        automation.active and automation.trigger == 'on_change' and automation.on_change_field_ids
        for automation in self
    )

def _update_cron(self):
    """ Activate the cron job depending on whether there exists automation rules
    based on time conditions.  Also update its frequency according to
    the smallest automation delay, or restore the default 4 hours if there
    is no time based automation.
    """
    cron = self.env.ref('base_automation.ir_cron_data_base_automation_check', raise_if_not_found=False)
    if cron:
        try:
            cron.lock_for_update(allow_referencing=True)
        except LockError:
            return
        automations = self.with_context(active_test=True).search([('trigger', 'in', TIME_TRIGGERS)])
        interval_number, interval_type = self._get_cron_interval(automations)
        vals = {'active': bool(automations)}

        actual_cron_timedelta = TIMEDELTA_TYPES[cron.interval_type](cron.interval_number)
        new_cron_timedelta = TIMEDELTA_TYPES[interval_type](interval_number)
        if new_cron_timedelta < actual_cron_timedelta:
            # we only update the cron interval if the new delay is shorter than the current one
            vals.update({
                'interval_type': interval_type,
                'interval_number': interval_number,
            })
        cron.write(vals)

def _keep_to_compute(env, changed_fields):
    """ Keep the computed fields depending on ``changed_fields`` as-is, so that
    they are recomputed once the values of ``changed_fields`` are set.
    """
    to_compute = {
        dep: comp
        for f in changed_fields
        for dep in env.registry.get_dependent_fields(f)
        if (comp := env.records_to_compute(dep))
    }
    yield
    for dep, comp in to_compute.items():
        env.add_to_compute(dep, comp)

def _filter_post_export_domain(self, records, feedback=False):
    """ Filter the records that satisfy the postcondition of automation ``self``. """
    self_sudo = self.sudo()
    if self_sudo.filter_domain and records:
        if feedback:
            # this context flag enables to detect the executions of
            # automations while evaluating their postcondition
            records = records.with_context(__action_feedback=True)
        domain = safe_eval.safe_eval(self_sudo.filter_domain, self._get_eval_context())
        return records.sudo().filtered_domain(domain).with_env(records.env), domain
    else:
        return records, None

def _add_postmortem(self, e):
    if self.env.user._is_internal():
        e.context = {}
        e.context['exception_class'] = 'base_automation'
        e.context['base_automation'] = {
            'id': self.id,
            'name': self.sudo().name,
        }

def _unregister_hook(self):
    """ Remove the patches installed by _register_hook() """
    NAMES = ['create', 'write', '_compute_field_value', 'unlink', '_onchange_methods', "message_post"]
    for Model in self.env.registry.values():
        for name in NAMES:
            try:
                delattr(Model, name)
            except AttributeError:
                pass

def job_log_level(status, duration):
    return (logging.ERROR if status != 'done'
        else logging.WARNING if duration > 1
        else logging.INFO if duration > .1
        else logging.DEBUG)

def validate_fields(cls, triggers, field_names):
    super().validate_fields(triggers, field_names)
    cls.check_condition(triggers, field_names)

def check_condition(cls, triggers, field_names=None):
    '''
    Check condition
    '''
    if field_names and 'condition' not in field_names:
        return
    for trigger in triggers:
        try:
            PYSONDecoder(noeval=True).decode(trigger.condition)
        except Exception:
            raise ConditionError(
                gettext('ir.msg_trigger_invalid_condition',
                    condition=trigger.condition,
                    trigger=trigger.rec_name))

def on_change_on_create_(self):
    if self.on_create_:
        self.on_time_ = False

def on_change_on_write_(self):
    if self.on_write_:
        self.on_time_ = False

@Override
public List<Long> findVersions(WkfModel wkfModel) {

  List<Long> wkfModelIds = new ArrayList<>();

  WkfModel previousModel = wkfModel.getPreviousVersion();

  while (previousModel != null) {
    wkfModelIds.add(previousModel.getId());
    previousModel = previousModel.getPreviousVersion();
  }

  return wkfModelIds;
}

@Override
@Transactional(rollbackOn = Exception.class)
public WkfModel backToDraft(WkfModel wkfModel) {

  wkfModel.setStatusSelect(WkfModelRepository.STATUS_NEW);

  return wkfModelRepository.save(wkfModel);
}

@Override
@Transactional(rollbackOn = Exception.class)
public WkfModel terminate(WkfModel wkfModel) {

  wkfModel.setStatusSelect(WkfModelRepository.STATUS_TERMINATED);

  return wkfModelRepository.save(wkfModel);
}

private void updatePreviousVersion(WkfModel wkfModel, WkfModel previousVersion) {
  if (previousVersion != null) {
    previousVersion.setIsActive(false);
    wkfModel.setPreviousVersion(terminate(previousVersion));
  }
}

@Override
@Transactional(rollbackOn = Exception.class)
public WkfModel start(WkfModel sourceModel, WkfModel targetModel) {

  if (!ObjectUtils.isEmpty(sourceModel)) {
    updatePreviousVersion(targetModel, sourceModel);
  } else {
    updatePreviousVersion(targetModel, targetModel.getPreviousVersion());
  }

  return wkfModelRepository.save(targetModel);
}

@Override
@Transactional(rollbackOn = Exception.class)
public WkfModel createNewVersion(WkfModel wkfModel) {
  WkfModel newVersion =
      wkfModelRepository
          .all()
          .filter("self.previousVersion.id = ?1", wkfModel.getId())
          .fetchOne();

  if (newVersion == null) {
    newVersion = wkfModelRepository.copy(wkfModel, true);
    newVersion.setPreviousVersion(wkfModel);
    String newVersionTag =
        Strings.isNullOrEmpty(wkfModel.getVersionTag())
            ? "1"
            : String.valueOf(Long.parseLong(wkfModel.getVersionTag()) + 1);
    newVersion.setCode(wkfModel.getCode());
    newVersion.setVersionTag(newVersionTag);
  }

  return wkfModelRepository.save(newVersion);
}

def get_transitions(
	doc: Document | str | dict, workflow: Workflow | None = None, raise_exception: bool = False
) -> list[dict]:
	"""Return list of possible transitions for the given doc"""
	from frappe.model.document import Document

	if not isinstance(doc, Document):
		doc = frappe.get_doc(frappe.parse_json(doc))
		doc.load_from_db()

	if doc.is_new():
		return []

	doc.check_permission("read")

	workflow = workflow or get_workflow(doc.doctype)
	current_state = doc.get(workflow.workflow_state_field)

	if not current_state:
		if raise_exception:
			raise WorkflowStateError
		else:
			frappe.throw(_("Workflow State not set"), WorkflowStateError)

	transitions = []
	roles = frappe.get_roles()

	for transition in workflow.transitions:
		if transition.state == current_state and transition.allowed in roles:
			if not is_transition_condition_satisfied(transition, doc):
				continue
			transitions.append(transition.as_dict())

	return transitions

def is_transition_condition_satisfied(transition, doc) -> bool:
	if not transition.condition:
		return True
	else:
		return frappe.safe_eval(transition.condition, get_workflow_safe_globals(), dict(doc=doc.as_dict()))

def get_workflow_safe_globals():
	# access to frappe.db.get_value, frappe.db.get_list, and date time utils.
	return dict(
		frappe=frappe._dict(
			db=frappe._dict(get_value=frappe.db.get_value, get_list=frappe.db.get_list),
			session=frappe.session,
			utils=frappe._dict(
				now_datetime=frappe.utils.now_datetime,
				add_to_date=frappe.utils.add_to_date,
				get_datetime=frappe.utils.get_datetime,
				now=frappe.utils.now,
			),
		)
	)

def evaluate_workflow_value(value, evaluate_as_expression, doc):
	if not value:
		return None
	if evaluate_as_expression:
		try:
			return frappe.safe_eval(value, get_workflow_safe_globals(), dict(doc=doc.as_dict()))
		except Exception as e:
			frappe.throw(
				_("Invalid expression in Workflow Update Value: {0}").format(str(e)),
				title=_("Workflow Evaluation Error"),
			)
	else:
		return value

def get_workflow_name(doctype):
	workflow_name = frappe.cache.hget("workflow", doctype)
	if workflow_name is None:
		workflow_name = frappe.db.get_value("Workflow", {"document_type": doctype, "is_active": 1}, "name")
		frappe.cache.hset("workflow", doctype, workflow_name or "")

	return workflow_name

def process_workflow_actions(doc, state):
	workflow = get_workflow_name(doc.get("doctype"))
	if not workflow:
		return

	if state == "on_trash":
		clear_workflow_actions(doc.get("doctype"), doc.get("name"))
		return

	if is_workflow_action_already_created(doc):
		return

	update_completed_workflow_actions(doc, workflow=workflow, workflow_state=get_doc_workflow_state(doc))
	clear_doctype_notifications("Workflow Action")

	next_possible_transitions = get_next_possible_transitions(workflow, get_doc_workflow_state(doc), doc)

	if not next_possible_transitions:
		return

	roles = {t.allowed for t in next_possible_transitions}
	create_workflow_actions_for_roles(roles, doc)

	if send_email_alert(workflow) and frappe.db.get_value(
		"Workflow Document State",
		filters={"parent": workflow, "state": get_doc_workflow_state(doc)},
		fieldname="send_email",
	):
		enqueue(
			send_workflow_action_email,
			queue="short",
			doc=doc,
			transitions=next_possible_transitions,
			enqueue_after_commit=True,
			now=frappe.in_test,
		)

def create_workflow_actions_for_roles(roles, doc):
	if not roles:
		return
	workflow_action = frappe.get_doc(
		{
			"doctype": "Workflow Action",
			"reference_doctype": doc.get("doctype"),
			"reference_name": doc.get("name"),
			"workflow_state": get_doc_workflow_state(doc),
			"status": "Open",
		}
	)

	for role in roles:
		workflow_action.append("permitted_roles", {"role": role})

	workflow_action.insert(ignore_permissions=True)

def update_completed_workflow_actions(doc, user=None, workflow=None, workflow_state=None):
	allowed_roles = get_allowed_roles(user, workflow, workflow_state)
	# There is no transaction leading upto this state
	# so no older actions to complete
	if not allowed_roles:
		return
	if workflow_action := get_workflow_action_by_role(doc, allowed_roles):
		update_completed_workflow_actions_using_role(user, workflow_action)

def get_next_possible_transitions(workflow_name, state, doc=None):
	transitions = frappe.get_all(
		"Workflow Transition",
		fields=["allowed", "action", "state", "allow_self_approval", "next_state", "condition"],
		filters=[["parent", "=", workflow_name], ["state", "=", state]],
	)

	transitions_to_return = []

	for transition in transitions:
		is_next_state_optional = get_state_optional_field_value(workflow_name, transition.next_state)
		# skip transition if next state of the transition is optional
		if is_next_state_optional:
			continue
		if not is_transition_condition_satisfied(transition, doc):
			continue
		transitions_to_return.append(transition)

	return transitions_to_return

def is_workflow_action_already_created(doc):
	# Only an open action means the current state is already being acted upon. Completed ones must not
	# block, or a document re-entering a state it has left gets no new action and no notification.
	return frappe.db.exists(
		{
			"doctype": "Workflow Action",
			"reference_name": doc.get("name"),
			"reference_doctype": doc.get("doctype"),
			"workflow_state": get_doc_workflow_state(doc),
			"status": "Open",
		}
	)

def clear_workflow_actions(doctype, name):
	if not (doctype and name):
		return
	frappe.db.delete(
		"Workflow Action",
		filters={
			"reference_name": name,
			"reference_doctype": doctype,
		},
	)

def get_doc_workflow_state(doc):
	workflow_name = get_workflow_name(doc.get("doctype"))
	workflow_state_field = get_workflow_state_field(workflow_name)
	return doc.get(workflow_state_field)

def get_allowed_roles(user, workflow, workflow_state):
	user = user if user else frappe.session.user

	allowed_roles = frappe.get_all(
		"Workflow Transition",
		fields="allowed",
		filters=[["parent", "=", workflow], ["next_state", "=", workflow_state]],
		pluck="allowed",
	)

	user_roles = set(frappe.get_roles(user))
	return set(allowed_roles).intersection(user_roles)

def get_state_optional_field_value(workflow_name, state):
	return frappe.get_cached_value(
		"Workflow Document State", {"parent": workflow_name, "state": state}, "is_optional_state"
	)

def _filter_post_export_domain(self, records, feedback=False):
    """ Filter the records that satisfy the postcondition of automation ``self``. """
    self_sudo = self.sudo()
    if self_sudo.filter_domain and records:
        if feedback:
            # this context flag enables to detect the executions of
            # automations while evaluating their postcondition
            records = records.with_context(__action_feedback=True)
        domain = safe_eval.safe_eval(self_sudo.filter_domain, self._get_eval_context())
        return records.sudo().filtered_domain(domain).with_env(records.env), domain
    else:
        return records, None

def _check(self, automatic=False, use_new_cursor=False):
    if not automatic:
        raise RuntimeError("can run time-based automations only in automatic mode")
    self._cron_process_time_based_actions()

def job_log_level(status, duration):
    return (logging.ERROR if status != 'done'
        else logging.WARNING if duration > 1
        else logging.INFO if duration > .1
        else logging.DEBUG)

def _add_postmortem(self, e):
    if self.env.user._is_internal():
        e.context = {}
        e.context['exception_class'] = 'base_automation'
        e.context['base_automation'] = {
            'id': self.id,
            'name': self.sudo().name,
        }

def _cron_process_time_based_actions(self):
    """ Execute the time-based automations. """
    if '__action_done' not in self.env.context:
        self = self.with_context(__action_done={})

    # retrieve all the automation rules to run based on a timed condition
    final_exception = None
    automations = self.with_context(active_test=True).search([('trigger', 'in', TIME_TRIGGERS)])

    for automation in automations:
        automation = automation.with_prefetch()
        # is automation deactivated or disappeared between commits?
        try:
            if not automation.active:
                continue
        except MissingError:
            continue
        _logger.info("Starting time-based automation rule `%s`.", automation.name)
        now = self.env.cr.now()
        records = automation._search_time_based_automation_records(until=now)
        # run the automation on the records
        record = None
        try:
            for record in records:
                automation._process(record, trigger='time-based')
            record = None  # a flush error can't be attributed to a record
            self.env.flush_all()
        except Exception as e:
            self.env['ir.cron']._rollback_progress()
            if record:
                _logger.exception("Error in time-based automation rule `%s` on record %s.", automation.name, record)
            else:
                _logger.exception("Error in time-based automation rule `%s`.", automation.name)
            final_exception = e
            continue

        automation.write({'last_run': now})
        _logger.info("Time-based automation rule `%s` done.", automation.name)
        self.env['ir.cron']._commit_progress()
    if final_exception is not None:
        # raise the last found exception to mark the cron job as failing
        raise final_exception

def write(self, vals: dict):
    clear_templates = self._has_trigger_onchange()
    res = super().write(vals)
    if set(vals).intersection(CRITICAL_FIELDS):
        self._update_cron()
        self._update_registry()
        clear_templates |= self._has_trigger_onchange()
        if clear_templates and any(self._ids):
            # Invalidate templates cache to update on_change attributes if needed
            self.env.transaction.invalidate_ormcache('templates')
    elif set(vals).intersection(RANGE_FIELDS):
        self._update_cron()
    return res

def _search_time_based_automation_records(self, *, until):
    automation = self.ensure_one()

    # retrieve the domain and field
    domain = Domain.TRUE
    if automation.filter_domain:
        eval_context = automation._get_eval_context()
        domain = Domain(safe_eval.safe_eval(automation.filter_domain, eval_context))
    Model = self.env[automation.model_name]
    date_field = Model._fields.get(automation.trg_date_id.name)
    if not date_field:
        _logger.warning("Missing date trigger field in automation rule `%s`", automation.name)
        return Model

    # get the time information and find the records
    last_run = automation.last_run or datetime.datetime.fromtimestamp(0, tz=None)
    is_date_automation_last = date_field.name == "date_automation_last" and "create_date" in Model._fields
    range_sign = 1 if automation.trg_date_range_mode == 'before' else -1
    date_range = range_sign * automation.trg_date_range

    def get_record_dt(record):
        # the field can be a date or datetime, cast always to a datetime
        dt = record[date_field.name]
        if not dt and is_date_automation_last:
            dt = record.create_date
        return fields.Datetime.to_datetime(dt)

    if automation.trg_date_calendar_id and automation.trg_date_range_type == 'day':
        # use the calendar information from the record
        # _get_calendar can be overwritten and cannot be optimized
        time_domain = Domain.TRUE if is_date_automation_last else Domain(date_field.name, '!=', False)
        if date_field._description_searchable:
            records = Model.search(time_domain & domain)
        else:
            records = Model.search(domain).filtered_domain(time_domain)

        past_until = {}
        past_last_run = {}

        def calendar_filter(record):
            record_dt = get_record_dt(record)
            if not record_dt:
                return False
            calendar = self._get_calendar(automation, record)
            if calendar.id not in past_until:
                past_until[calendar.id] = calendar.plan_days(
                    date_range,
                    until,
                    compute_leaves=True,
                )
                past_last_run[calendar.id] = calendar.plan_days(
                    date_range,
                    last_run,
                    compute_leaves=True,
                )
            return (
                past_last_run[calendar.id]
                and past_until[calendar.id]
                and past_last_run[calendar.id] <= record_dt < past_until[calendar.id]
            )

        return records.filtered(calendar_filter)

    # we can search for the records to trigger
    # find the relative dates
    relative_offset = DATE_RANGE[automation.trg_date_range_type] * date_range
    relative_until = until + relative_offset
    relative_last_run = last_run + relative_offset
    if date_field.type == 'date':
        # find records that have a date in past, but were not yet executed that day
        time_domain = Domain(date_field.name, '>', relative_last_run.date()) & Domain(date_field.name, '<=', relative_until.date())
        if is_date_automation_last:
            time_domain |= Domain(date_field.name, '=', False) & Domain('create_date', '>', relative_last_run.date()) & Domain('create_date', '<=', relative_until.today())
    else:  # datetime
        time_domain = Domain(date_field.name, '>=', relative_last_run) & Domain(date_field.name, '<', relative_until)
        if is_date_automation_last:
            time_domain |= Domain(date_field.name, '=', False) & Domain('create_date', '>=', relative_last_run) & Domain('create_date', '<', relative_until)

    if date_field._description_searchable:
        return Model.search(time_domain & domain)
    else:
        return Model.search(domain).filtered_domain(time_domain)

def _has_trigger_onchange(self):
    return any(
        automation.active and automation.trigger == 'on_change' and automation.on_change_field_ids
        for automation in self
    )

def _update_cron(self):
    """ Activate the cron job depending on whether there exists automation rules
    based on time conditions.  Also update its frequency according to
    the smallest automation delay, or restore the default 4 hours if there
    is no time based automation.
    """
    cron = self.env.ref('base_automation.ir_cron_data_base_automation_check', raise_if_not_found=False)
    if cron:
        try:
            cron.lock_for_update(allow_referencing=True)
        except LockError:
            return
        automations = self.with_context(active_test=True).search([('trigger', 'in', TIME_TRIGGERS)])
        interval_number, interval_type = self._get_cron_interval(automations)
        vals = {'active': bool(automations)}

        actual_cron_timedelta = TIMEDELTA_TYPES[cron.interval_type](cron.interval_number)
        new_cron_timedelta = TIMEDELTA_TYPES[interval_type](interval_number)
        if new_cron_timedelta < actual_cron_timedelta:
            # we only update the cron interval if the new delay is shorter than the current one
            vals.update({
                'interval_type': interval_type,
                'interval_number': interval_number,
            })
        cron.write(vals)

def _register_hook(self):
    """ Patch models that should trigger action rules based on creation,
        modification, deletion of records and form onchanges.
    """
    #
    # Note: the patched methods must be defined inside another function,
    # otherwise their closure may be wrong. For instance, the function
    # create refers to the outer variable 'create', which you expect to be
    # bound to create itself. But that expectation is wrong if create is
    # defined inside a loop; in that case, the variable 'create' is bound to
    # the last function defined by the loop.
    #

    def make_create():
        """ Instanciate a create method that processes automation rules. """
        @api.model_create_multi
        def create(self, vals_list, **kw):
            # retrieve the automation rules to possibly execute
            automations = self.env['base.automation']._get_actions(self, CREATE_TRIGGERS)
            if not automations:
                return create.origin(self, vals_list, **kw)
            # call original method
            records = create.origin(self.with_env(automations.env), vals_list, **kw)
            # check postconditions, and execute actions on the records that satisfy them
            for automation in automations.with_context(old_values=None):
                with _keep_to_compute(self.env, self.env._protected):
                    automation._process(automation._filter_post(records, feedback=True), trigger='create')
            return records.with_env(self.env)

        return create

    def make_write():
        """ Instanciate a write method that processes automation rules. """
        def write(self, vals, **kw):
            # retrieve the automation rules to possibly execute
            automations = self.env['base.automation']._get_actions(self, WRITE_TRIGGERS)
            if not (automations and self):
                return write.origin(self, vals, **kw)
            records = self.with_env(automations.env).filtered('id')
            written_fields = [records._fields[n] for n in vals if n in records._fields]
            # check preconditions on records
            with _keep_to_compute(self.env, written_fields):
                pre = {a: a._filter_pre(records) for a in automations}
            # read old values before the update
            old_values = {
                record.id: {field_name: record[field_name] for field_name in vals if field_name in record._fields and record._fields[field_name].store}
                for record in records
            }
            # call original method
            write.origin(self.with_env(automations.env), vals, **kw)
            # check postconditions, and execute actions on the records that satisfy them
            for automation in automations.with_context(old_values=old_values):
                with _keep_to_compute(self.env, written_fields):
                    records, domain_post = automation._filter_post_export_domain(pre[automation], feedback=True)
                    automation._process(records, domain_post=domain_post, trigger='write')
            return True

        return write

    def make_compute_field_value():
        """ Instanciate a compute_field_value method that processes automation rules. """
        #
        # Note: This is to catch updates made by field recomputations.
        #
        def _compute_field_value(self, field):
            # determine fields that may trigger an automation
            stored_fnames = [f.name for f in self.pool.field_computed[field] if f.store]
            if not stored_fnames:
                return _compute_field_value.origin(self, field)
            # retrieve the action rules to possibly execute
            automations = self.env['base.automation']._get_actions(self, WRITE_TRIGGERS)
            records = self.filtered('id').with_env(automations.env)
            if not (automations and records):
                _compute_field_value.origin(self, field)
                return True
            # check preconditions on records
            # changed fields are all fields computed by the function
            changed_fields = [f for f in records._fields.values() if f.compute == field.compute]
            with _keep_to_compute(self.env, changed_fields):
                pre = {a: a._filter_pre(records) for a in automations}
                # read old values before the update
                old_values = {
                    record.id: {fname: record[fname] for fname in stored_fnames}
                    for record in records
                }
            # call original method
            _compute_field_value.origin(self, field)
            # check postconditions, and execute automations on the records that satisfy them
            for automation in automations.with_context(old_values=old_values):
                with _keep_to_compute(self.env, changed_fields):
                    records, domain_post = automation._filter_post_export_domain(pre[automation], feedback=True)
                    automation._process(records, domain_post=domain_post, trigger='_compute_field_value')
            return True

        return _compute_field_value

    def make_unlink():
        """ Instanciate an unlink method that processes automation rules. """
        def unlink(self, **kwargs):
            # retrieve the action rules to possibly execute
            automations = self.env['base.automation']._get_actions(self, ['on_unlink'])
            records = self.with_env(automations.env)
            # check conditions, and execute actions on the records that satisfy them
            for automation in automations:
                with _keep_to_compute(self.env, self.env._protected):
                    automation._process(automation._filter_post(records, feedback=True), trigger='unlink')
            # call original method
            return unlink.origin(self, **kwargs)

        return unlink

    def make_onchange(automation_rule_id):
        """ Instanciate an onchange method for the given automation rule. """
        def base_automation_onchange(self):
            automation_rule = self.env['base.automation'].browse(automation_rule_id)

            if not automation_rule._filter_post(self):
                # Do nothing if onchange record does not satisfy the filter_domain
                return

            result = {}
            actions = automation_rule.sudo().action_server_ids.with_context(
                active_model=self._name,
                active_id=self._origin.id,
                active_ids=self._origin.ids,
                onchange_self=self,
            )
            for action in actions:
                try:
                    res = action.run()
                except Exception as e:
                    automation_rule._add_postmortem(e)
                    raise

                if res:
                    if 'value' in res:
                        res['value'].pop('id', None)
                        self.update({key: val for key, val in res['value'].items() if key in self._fields})
                    if 'domain' in res:
                        result.setdefault('domain', {}).update(res['domain'])
                    if 'warning' in res:
                        result['warning'] = res["warning"]
            return result

        return base_automation_onchange

    def make_message_post():
        def _message_post(self, *args, **kwargs):
            message = _message_post.origin(self, *args, **kwargs)
            # Don't execute automations for a message emitted during
            # the run of automations for a real message
            # Don't execute if we know already that a message is only internal
            message_sudo = message.sudo().with_context(active_test=False)
            if "__action_done"  in self.env.context or message_sudo.is_internal or message_sudo.subtype_id.internal:
                return message
            if message_sudo.message_type in ('notification', 'auto_comment', 'user_notification'):
                return message

            # always execute actions when the author is a customer
            # if author is not set, it means the message is coming from outside
            mail_trigger = "on_message_received" if not message_sudo.author_id or message_sudo.author_id.partner_share else "on_message_sent"
            automations = self.env['base.automation']._get_actions(self, [mail_trigger])
            for automation in automations.with_context(old_values=None):
                with _keep_to_compute(self.env, self.env._protected):
                    records = automation._filter_pre(self, feedback=True)
                    automation._process(records, trigger='_message_post')

            return message
        return _message_post

    patched_models = defaultdict(set)

    def patch(model, name, method):
        """ Patch method `name` on `model`, unless it has been patched already. """
        if model not in patched_models[name]:
            patched_models[name].add(model)
            ModelClass = model.env.registry[model._name]
            method.origin = getattr(ModelClass, name)
            setattr(ModelClass, name, method)

    # retrieve all actions, and patch their corresponding model
    for automation_rule in self.with_context({}).search([]):
        Model = self.env.get(automation_rule.model_name)

        # Do not crash if the model of the base_action_rule was uninstalled
        if Model is None:
            _logger.warning(
                "Automation rule with name '%s' (ID %d) depends on model %s (ID: %d)",
                automation_rule.name,
                automation_rule.id,
                automation_rule.model_name,
                automation_rule.model_id.id)
            continue

        if automation_rule.trigger in CREATE_WRITE_SET:
            if automation_rule.trigger in CREATE_TRIGGERS:
                patch(Model, 'create', make_create())
            if automation_rule.trigger in WRITE_TRIGGERS:
                patch(Model, 'write', make_write())
                patch(Model, '_compute_field_value', make_compute_field_value())

        elif automation_rule.trigger == 'on_unlink':
            patch(Model, 'unlink', make_unlink())

        elif automation_rule.trigger == 'on_change':
            # register an onchange method for the automation_rule
            method = make_onchange(automation_rule.id)
            for field in automation_rule.on_change_field_ids:
                Model._onchange_methods[field.name].append(method)

        if automation_rule.model_id.is_mail_thread and automation_rule.trigger in MAIL_TRIGGERS:
            patch(Model, "message_post", make_message_post())

def _unregister_hook(self):
    """ Remove the patches installed by _register_hook() """
    NAMES = ['create', 'write', '_compute_field_value', 'unlink', '_onchange_methods', "message_post"]
    for Model in self.env.registry.values():
        for name in NAMES:
            try:
                delattr(Model, name)
            except AttributeError:
                pass

def _keep_to_compute(env, changed_fields):
    """ Keep the computed fields depending on ``changed_fields`` as-is, so that
    they are recomputed once the values of ``changed_fields`` are set.
    """
    to_compute = {
        dep: comp
        for f in changed_fields
        for dep in env.registry.get_dependent_fields(f)
        if (comp := env.records_to_compute(dep))
    }
    yield
    for dep, comp in to_compute.items():
        env.add_to_compute(dep, comp)

def _process_jobs(db_name: str) -> None:
    """ Execute every job ready to be run on this database. """
    try:
        db = sql_db.db_connect(db_name)
        threading.current_thread().dbname = db_name
        with db.cursor() as cron_cr:
            cls = IrCron
            cls._check_version(cron_cr)
            jobs = cls._get_all_ready_jobs(cron_cr)
            if not jobs:
                return
            cls._check_modules_state(cron_cr, jobs)
            cls._process_jobs_loop(cron_cr, job_ids=[job['id'] for job in jobs])
    except BadVersion:
        _logger.warning('Skipping database %s as its base version is not %s.', db_name, BASE_VERSION)
    except BadModuleState:
        _logger.warning('Skipping database %s because of modules to install/upgrade/remove.', db_name)
    except psycopg2.errors.UndefinedTable:
        # The table ir_cron does not exist; this is probably not an OpenERP database.
        _logger.warning('Tried to poll an undefined table on database %s.', db_name)
    except psycopg2.ProgrammingError:
        raise
    except Exception:
        _logger.warning('Exception in cron:', exc_info=True)
    finally:
        if hasattr(threading.current_thread(), 'dbname'):
            del threading.current_thread().dbname

def create(self, vals_list):
    for vals in vals_list:
        vals['usage'] = 'ir_cron'
    if os.getenv('ODOO_NOTIFY_CRON_CHANGES'):
        self.env.cr.postcommit.add(self._notifydb)
    return super().create(vals_list)

def transition(state):
    def check_transition(func):
        @wraps(func)
        def wrapper(cls, records, *args, **kwargs):
            filtered = []
            to_update = OrderedDict()

            assert len(records) == len(set(records)), "Duplicate records"

            for record in records:
                current_state = getattr(record, cls._transition_state)
                transition = (current_state, state)
                if transition in cls._transitions:
                    filtered.append(record)
                    if current_state != state:
                        to_update[record] = current_state

            result = func(cls, filtered, *args, **kwargs)
            if to_update:
                for record in list(to_update.keys()):
                    current_state = getattr(record, cls._transition_state)
                    if current_state != to_update[record]:
                        del to_update[record]
                to_update = list(to_update)
                cls.write(to_update, {
                        cls._transition_state: state,
                        })
                cls.log(
                    to_update, 'transition',
                    f'{cls._transition_state}:{state}')
            return result
        return wrapper
    return check_transition

def push(cls, name, data, scheduled_at=None, expected_at=None):
    transaction = Transaction()
    database = transaction.database
    with without_check_access():
        record, = cls.create([{
                    'name': name,
                    'data': data,
                    'scheduled_at': scheduled_at,
                    'expected_at': expected_at,
                    }])
    if database.has_channel():
        database.notify(transaction.connection, cls.__name__, '')
    if not config.getboolean('queue', 'worker', default=False):
        transaction.tasks.append(record.id)
    return record.id

def run(self):
    transaction = Transaction()
    Model = Pool().get(self.data['model'])
    self.lock()
    with transaction.set_user(self.data['user']), \
            transaction.set_context(
                self.data['context'], _skip_warnings=True):
        instances = self.data['instances']
        # Ensure record ids still exist
        if isinstance(instances, int):
            with inactive_records():
                if Model.search([('id', '=', instances)]):
                    instances = Model(instances)
                else:
                    instances = None
        else:
            with inactive_records():
                records = Model.search([('id', 'in', instances)])
            if ids := set(map(int, records)):
                instances = Model.browse(
                    [i for i in instances if i in ids])
            else:
                instances = None
        if instances is not None:
            getattr(Model, self.data['method'])(
                instances, *self.data['args'], **self.data['kwargs'])
    if not self.dequeued_at:
        self.dequeued_at = datetime.datetime.now()
    self.finished_at = datetime.datetime.now()
    self.save()

def eval(self, record):
    """
    Evaluate the condition of trigger
    """
    env = {}
    env['current_date'] = datetime.datetime.today()
    env['time'] = time
    env['context'] = Transaction().context
    env['self'] = EvalEnvironment(record, record.__class__)
    return bool(PYSONDecoder(env).decode(self.condition))

def queue_trigger_action(self, records):
    trigger_records = Transaction().trigger_records[self.id]
    ids = {r.id for r in records if self.eval(r)} - trigger_records
    if ids:
        self.__class__.__queue__.trigger_action(self, list(ids))
        trigger_records.update(ids)

@Transactional(rollbackOn = Exception.class)
public void batchUpdateProcessInstances(
    WkfProcess targetProcess, List<String> processInstanceIds, int migrationStatus) {

  if (processInstanceIds == null || processInstanceIds.isEmpty()) {
    return;
  }

  if (targetProcess != null && targetProcess.getId() != null) {
    targetProcess = wkfProcessRepository.find(targetProcess.getId());
  }

  List<WkfInstance> instances =
      wkfInstanceRepository.all().filter("self.instanceId IN (?1)", processInstanceIds).fetch();

  for (WkfInstance instance : instances) {
    if (targetProcess != null) {
      instance.addWkfInstanceMigrationHistory(
          createMigrationHistory(instance, targetProcess.getWkfModel()));
      instance.setWkfProcess(targetProcess);
      instance.setName(targetProcess.getProcessId() + " : " + instance.getInstanceId());
    }
    instance.setMigrationStatusSelect(migrationStatus);
  }
}

@Transactional
@Override
public void updateProcessInstance(
    WkfProcess process, String processInstanceId, int migrationStatus) {

  WkfInstance instance = wkfInstanceRepository.findByInstanceId(processInstanceId);
  if (instance == null) {
    return;
  }

  if (process != null && process.getId() != null) {
    process = wkfProcessRepository.find(process.getId());
  }

  if (process != null) {
    instance.addWkfInstanceMigrationHistory(
        createMigrationHistory(instance, process.getWkfModel()));
    instance.setWkfProcess(process);
    instance.setName(process.getProcessId() + " : " + instance.getInstanceId());
  }

  instance.setMigrationStatusSelect(migrationStatus);
  wkfInstanceRepository.save(instance);
}

protected Map<String, Object> createVariables(String processInstanceId) {

  Map<String, Object> varMap = new HashMap<>();

  WkfInstance wkfInstance = wkfInstanceRepository.findByInstanceId(processInstanceId);

  if (wkfInstance == null) {
    return varMap;
  }

  wkfInstance
      .getWkfProcess()
      .getWkfProcessConfigList()
      .forEach(
          wkfProcessConfig -> {
            Model model =
                FullContextHelper.getRepository(wkfProcessConfig.getModel())
                    .all()
                    .filter("self.processInstanceId = ?1", processInstanceId)
                    .fetchOne();

            if (model == null) {
              return;
            }

            Object var =
                Variables.objectValue(new FullContext(model), true)
                    .serializationDataFormat(SerializationDataFormats.JSON)
                    .create();

            Long id = model.getId();

            String varName = wkfService.getVarName(model);
            varMap.put(varName, var);
            varMap.put(varName + "Id", id);
          });

  return varMap;
}

@Override
public void onNodeDeactivation(WkfTaskConfig wkfTaskConfig, DelegateExecution execution) {

  if (wkfTaskConfig == null || execution == null) {
    return;
  }

  if (wkfTaskConfig.getNotificationEmail()
      && wkfTaskConfig.getEmailEvent() != null
      && wkfTaskConfig.getEmailEvent().equals("end")) {
    try {
      wkfEmailService.sendEmail(wkfTaskConfig, execution);
    } catch (Exception e) {
      ExceptionHelper.error(e);
    }
  }
}

@Override
public void onNodeActivation(WkfTaskConfig wkfTaskConfig, DelegateExecution execution) {

  if (wkfTaskConfig == null || execution == null) {
    return;
  }

  if (wkfTaskConfig.getNotificationEmail()
      && wkfTaskConfig.getEmailEvent() != null
      && wkfTaskConfig.getEmailEvent().equals("start")) {
    try {
      wkfEmailService.sendEmail(wkfTaskConfig, execution);
    } catch (Exception e) {
      ExceptionHelper.error(e);
    }
  }

  if (wkfTaskConfig.getCreateTask()) {
    wkfUserActionService.createUserAction(wkfTaskConfig, execution);
  }
}

