protected void startInstance(WkfProcessConfig wkfProcessConfig, Model model) {

  WkfProcessConfig previousConfig = wkfService.findOldProcessConfig(model);

  if (previousConfig != null
      && previousConfig.getProcessPath() != null
      && addRelatedInstance(model, previousConfig)) {
    return;
  }

  log.debug(
      "Start instance for the model: {}, id: {}", model.getClass().getName(), model.getId());

  WkfProcess wkfProcess = wkfProcessConfig.getWkfProcess();
  ProcessEngine engine = engineService.getEngine();
  RuntimeService runTimeService = engine.getRuntimeService();

  ProcessInstantiationBuilder builder =
      runTimeService.createProcessInstanceByKey(wkfProcess.getName());

  Map<String, Object> modelMap = new HashMap<>();
  modelMap.put(wkfService.getVarName(model), new FullContext(model));
  builder.setVariable("modelId", model.getId());
  builder.setVariable("modelName", model.getClass().getName());
  builder.setVariables(wkfService.createVariables(modelMap));
  ProcessInstance processInstance = builder.executeWithVariablesInReturn();
  WkfInstance instance = wkfInstanceRepository.findByInstanceId(model.getProcessInstanceId());
  if (instance != null) {
    instance.setModelId(model.getId());
    instance.setModelName(model.getClass().getName());
    instance.setProcessInstanceId(processInstance.getId());
  }
  model.setProcessInstanceId(processInstance.getId());
}

@Override
public void evalInstance(WkfInstance instance) throws ClassNotFoundException {
  List<WkfProcessConfig> wkfProcessConfigs = instance.getWkfProcess().getWkfProcessConfigList();
  if (wkfProcessConfigs.isEmpty()) {
    return;
  }

  String classFullName = wkfProcessConfigs.getFirst().getMetaModel().getFullName();
  Class<? extends Model> klass = Class.forName(classFullName).asSubclass(Model.class);
  Model model =
      Query.of(klass)
          .filter("self.processInstanceId = :instanceId")
          .bind("instanceId", instance.getInstanceId())
          .fetchOne();

  if (model == null) {
    throw new RuntimeException("Model not found");
  }
  evalInstance(model, null);
}

@Override
@Transactional(rollbackOn = Exception.class)
public String evalInstance(Model model, String signal) throws ClassNotFoundException {

  model = EntityHelper.getEntity(model);

  String helpText = null;

  OutputStreamAppender<ILoggingEvent> appender = null;

  String processInstanceId = null;
  WkfInstance wkfInstance = null;

  try {
    if (Strings.isNullOrEmpty(model.getProcessInstanceId())) {
      checkSubProcess(model);
    }

    if (Strings.isNullOrEmpty(model.getProcessInstanceId())) {
      addRelatedProcessInstanceId(model);
      log.debug("Model process instanceId added: {}", model.getProcessInstanceId());
    }

    if (Strings.isNullOrEmpty(model.getProcessInstanceId())) {
      return helpText;
    }

    ProcessEngine engine = engineService.getEngine();

    wkfInstance = wkfInstanceRepository.findByInstanceId(model.getProcessInstanceId());

    if (wkfInstance == null) {
      return helpText;
    }
    setWkfInstanceError(wkfInstance, false, null);
    try {
      ProcessInstance processInstance =
          findProcessInstance(wkfInstance.getInstanceId(), engine.getRuntimeService());

      if (processInstance != null && !processInstance.isEnded()) {
        processInstanceId = processInstance.getId();
        boolean isLog = appSettingsStudioService.isAddBpmLog();
        if (isLog) {
          appender = wkfLogService.createOrAttachAppender(processInstanceId);
        }
        helpText = wkfTaskService.runTasks(engine, wkfInstance, processInstance, signal, model);
      }
    } catch (Exception e) {
      setWkfInstanceError(wkfInstance, true, e.getMessage());
      throw e;
    }

  } catch (Exception e) {
    if (!(e instanceof AxelorScriptEngineException)) {
      WkfProcessConfig wkfProcessConfig = wkfService.findCurrentProcessConfig(model);
      final String finalProcessInstanceId = model.getProcessInstanceId();
      bpmAsyncExecutorService.submit(
          ContextAware.of()
              .withTransaction(false)
              .build(
                  () ->
                      bpmErrorMessageService.sendBpmErrorMessage(
                          null,
                          e.getMessage(),
                          EntityHelper.getEntity(wkfProcessConfig.getWkfProcess().getWkfModel()),
                          finalProcessInstanceId)));
    }
    WkfProcess wkfProcess = wkfService.findCurrentProcessConfig(model).getWkfProcess();
    removeRelatedFailedInstance(model, wkfProcess);
    ExceptionHelper.error(e);

  } finally {
    wkfTaskService.reset();
    if (appender != null) {
      wkfLogService.writeLog(processInstanceId);
    }
  }

  return helpText;
}

@Override
public String evalInstance(Model model, String signal, Integer source)
    throws ClassNotFoundException {
  WkfInstance wkfInstance = null;
  if (model.getProcessInstanceId() != null) {
    wkfInstance = wkfInstanceRepository.findByInstanceId(model.getProcessInstanceId());
  }
  WkfProcessConfig wkfProcessConfig = wkfService.findCurrentProcessConfig(model);
  boolean executeProcess = false;
  if (wkfProcessConfig != null || wkfInstance != null) {
    WkfProcess wkfProcess =
        wkfProcessConfig != null ? wkfProcessConfig.getWkfProcess() : wkfInstance.getWkfProcess();
    executeProcess =
        (!wkfProcess.getOnlyOnClientChange() && EXECUTION_SOURCE_LISTENER == source)
            || (source == EXECUTION_SOURCE_OBSERVER && wkfProcess.getOnlyOnClientChange());
  }
  if (executeProcess) {
    return evalInstance(model, signal);
  }
  return null;
}

protected boolean addRelatedInstance(Model model, WkfProcessConfig wkfProcessConfig) {

  log.debug(
      "Find related instance for the model: {}, id: {}, path: {}",
      model.getClass().getName(),
      model.getId(),
      wkfProcessConfig.getProcessPath());

  Object object = wkfService.findRelatedRecord(model, wkfProcessConfig.getProcessPath());

  if (object instanceof FullContext relatedModel) {
    log.debug(
        "Related instance found with processInstanceId: {}",
        relatedModel.get("processInstanceId"));
    model.setProcessInstanceId((String) relatedModel.get("processInstanceId"));
    return true;
  } else {
    WkfProcessConfig oldProcessConfig = wkfService.findOldProcessConfig(model);
    if (oldProcessConfig == null
        || oldProcessConfig.getProcessPath() == null
        || oldProcessConfig.equals(wkfProcessConfig)) {
      return false;
    }
    return addRelatedInstance(model, oldProcessConfig);
  }
}

protected void setWkfInstanceError(WkfInstance wkfInstance, boolean value, String error) {
  boolean enableNodeErrorMarking = appSettingsStudioService.isEnabledBpmErrorTracking();
  if (enableNodeErrorMarking) {
    error = (error == null || error.length() <= 250) ? error : error.substring(0, 250);
    JPA.em().refresh(wkfInstance);
    wkfInstance.setInstanceError(value);
    wkfInstance.setCurrentError(error);
  }
}

@Transactional(rollbackOn = Exception.class)
protected void removeRelatedFailedInstance(Model model, WkfProcess wkfProcess) {
  List<WkfInstance> instances =
      wkfInstanceRepository
          .all()
          .filter(
              "self.modelId = ? and self.wkfProcess.processId = ?",
              model.getId(),
              wkfProcess.getProcessId())
          .fetch();
  for (WkfInstance instance : instances) {
    if (engineService
            .getEngine()
            .getHistoryService()
            .createHistoricProcessInstanceQuery()
            .processInstanceId(instance.getInstanceId())
            .singleResult()
        == null) {
      wkfInstanceRepository.remove(instance);
    }
  }
}

protected void checkSubProcess(Model model) {

  String chldModel =
      model instanceof MetaJsonRecord metaJsonRecord
          ? metaJsonRecord.getJsonModel()
          : model.getClass().getSimpleName();

  List<WkfTaskConfig> taskConfigs =
      wkfTaskConfigRepository
          .all()
          .filter("self.callModel = ?1 AND self.callLink IS NOT NULL", chldModel)
          .fetch();

  if (taskConfigs.isEmpty()) {
    return;
  }

  FullContext modelCtx = WkfContextHelper.create(model);
  Map<String, Object> ctxMap = ImmutableMap.of(wkfService.getVarName(model), modelCtx);

  for (WkfTaskConfig taskConfig : taskConfigs) {

    if (!evalCondition(ctxMap, taskConfig.getCallLinkCondition())) {
      continue;
    }

    Object parentModel = modelCtx.get(taskConfig.getCallLink());
    if (parentModel instanceof FullContext context) {
      Model parent = (Model) context.getTarget();
      if (!Strings.isNullOrEmpty(parent.getProcessInstanceId())) {
        addChildProcessInstanceId(parent.getProcessInstanceId(), modelCtx, ctxMap);
        break;
      }
    }
  }
}

protected void addRelatedProcessInstanceId(Model model) {

  WkfProcessConfig wkfProcessConfig = wkfService.findCurrentProcessConfig(model);

  //    if (wkfProcessConfig == null) {
  //      wkfProcessConfig = wkfService.findOldProcessConfig(model);
  //    }

  if (wkfProcessConfig != null) {
    if (wkfProcessConfig.getIsStartModel()) {
      startInstance(wkfProcessConfig, model);
    } else {
      addRelatedInstance(model, wkfProcessConfig);
    }
  } else {
    log.debug(
        "No active process config found for model: {}, id: {}",
        model.getClass().getName(),
        model.getId());
  }
}

protected boolean evalCondition(Map<String, Object> ctxMap, String condition) {

  if (condition != null) {
    Object evalCondition = wkfService.evalExpression(ctxMap, condition);
    return evalCondition != null && evalCondition.equals(Boolean.TRUE);
  }

  return true;
}

@SuppressWarnings("rawtypes")
protected void addChildProcessInstanceId(
    String processInstanceId, FullContext modelCtx, Map<String, Object> ctxMap) {

  RuntimeService runtimeService = engineService.getEngine().getRuntimeService();
  List<ProcessInstance> processInstances =
      runtimeService
          .createProcessInstanceQuery()
          .superProcessInstanceId(processInstanceId)
          .list();

  for (ProcessInstance processInstance : processInstances) {
    WkfInstance wkfInstance =
        wkfInstanceRepository.findByInstanceId(processInstance.getProcessInstanceId());
    if (wkfInstance == null) {
      continue;
    }

    List<WkfProcessConfig> processConfigs = wkfInstance.getWkfProcess().getWkfProcessConfigList();

    for (WkfProcessConfig processConfig : processConfigs) {
      String configModel = null;
      if (processConfig.getMetaModel() != null) {
        configModel = processConfig.getMetaModel().getFullName();
      } else if (processConfig.getMetaJsonModel() != null) {
        configModel = processConfig.getMetaJsonModel().getName();
      }

      if (configModel == null) {
        continue;
      }

      Class klass = modelCtx.getContextClass();
      String ctxClass = klass.getName();
      if (klass.equals(MetaJsonRecord.class)) {
        ctxClass = (String) modelCtx.get("jsonModel");
      }
      if (ctxClass.equals(configModel)
          && evalCondition(ctxMap, processConfig.getPathCondition())) {
        modelCtx.put("processInstanceId", wkfInstance.getInstanceId());
        return;
      }
    }
  }
}

protected List<Task> getActiveTasks(ProcessEngine engine, String processInstanceId) {
  return engine
      .getTaskService()
      .createTaskQuery()
      .active()
      .processInstanceId(processInstanceId)
      .list();
}

@Override
public String runTasks(
    ProcessEngine engine,
    WkfInstance instance,
    ProcessInstance processInstance,
    String signal,
    Model model)
    throws ClassNotFoundException {

  WkfProcess wkfProcess = instance.getWkfProcess();

  List<Task> tasks = getActiveTasks(engine, processInstance.getId());

  boolean taskExecuted = false;
  String helpText = null;

  Map<String, Object> context = wkfService.getContext(instance, model);
  // TODO: Check if its required both variables from context and from processInstance, if
  Map<String, Object> processVariables =
      engine.getRuntimeService().getVariables(processInstance.getId());
  processVariables.entrySet().removeIf(it -> Strings.isNullOrEmpty(it.getKey()));

  Map<String, Object> expressionVariables = null;
  Map<String, Object> ctxVariables = wkfService.createVariables(context);
  if (signal != null) {
    ctxVariables.put(signal, Variables.objectValue(true, true));
  }

  for (Task task : tasks) {

    WkfTaskConfig config =
        wkfTaskConfigRepository
            .all()
            .filter(
                "self.name = ? and self.wkfModel.id = ?",
                task.getTaskDefinitionKey(),
                wkfProcess.getWkfModel().getId())
            .fetchOne();

    if (config == null) {
      continue;
    }

    List<String> validButtons = getValidButtons(signal, config.getButton());

    if (validButtons == null) {
      continue;
    }

    if (expressionVariables == null) {
      expressionVariables = new HashMap<>();
      expressionVariables.putAll(processVariables);
      expressionVariables.putAll(context);
    }

    if (validButtons.isEmpty() && config.getExpression() == null) {
      continue;
    }

    Map<String, Object> btnVariables = new HashMap<>();
    validButtons.forEach(button -> btnVariables.put(button, button.equals(signal)));

    Map<String, Object> variables = wkfService.createVariables(btnVariables);
    variables.putAll(ctxVariables);

    if (config.getExpression() != null) {
      expressionVariables.putAll(engine.getTaskService().getVariables(task.getId()));
      expressionVariables.entrySet().removeIf(it -> Strings.isNullOrEmpty(it.getKey()));
      Boolean validExpr =
          (Boolean) wkfService.evalExpression(expressionVariables, config.getExpression());
      if (validExpr == null || !validExpr) {
        log.debug("Not a valid expr: {}", config.getExpression());
        if (!validButtons.isEmpty()) {
          helpText = config.getHelpText();
        }
        continue;
      }

      log.debug("Valid expr: {}", config.getExpression());
    }

    String userId =
        Optional.ofNullable(AuthUtils.getUser()).map(Model::getId).orElse(0L).toString();
    engine.getTaskService().setAssignee(task.getId(), userId);

    engine.getTaskService().complete(task.getId(), variables); // here to update the task aop
    wkfUserActionService.updateUserAction(config, processInstance, engine, task.getId());
    taskExecuted = true;
  }
  Execution execution =
      engine
          .getRuntimeService()
          .createExecutionQuery()
          .active()
          .executionId(processInstance.getId())
          .singleResult();
  if (execution != null) {
    engine.getRuntimeService().setVariables(execution.getId(), ctxVariables);
  }
  AppBpm appBpm = appBpmService.getAppBpm();
  int taskExecutionRecursivityTimeLimit =
      Optional.ofNullable(appBpm.getTaskExecutionRecursivityDurationLimit())
          .orElse(DEFAULT_RECURSIVE_TASK_EXECUTION_DURATION_LIMIT);
  boolean hasExceededMaxTime =
      Integer.signum(taskExecutionRecursivityTimeLimit) >= 0
          && ChronoUnit.SECONDS.between(recursiveTaskExecutionTime, LocalTime.now())
              >= taskExecutionRecursivityTimeLimit;

  int taskExecutionRecursivityDepthLimit =
      Optional.ofNullable(appBpm.getTaskExecutionRecursivityDepthLimit())
          .orElse(DEFAULT_RECURSIVE_TASK_EXECUTION_DEPTH_LIMIT);
  boolean hasExceededMaxDepth =
      Integer.signum(taskExecutionRecursivityDepthLimit) >= 0
          && ++recursiveTaskExecutionCount >= taskExecutionRecursivityDepthLimit;

  if (hasExceededMaxDepth && hasExceededMaxTime) {
    throw new IllegalStateException(I18n.get(BpmExceptionMessage.INFINITE_EXECUTION));
  }

  if (taskExecuted
      && wkfInstanceService.isActiveProcessInstance(
          processInstance.getId(), engine.getRuntimeService())) {
    log.debug("Check tasks again");
    runTasks(engine, instance, processInstance, signal, model);
  }

  return helpText;
}

@Override
public void reset() {
  recursiveTaskExecutionTime = LocalTime.now();
  recursiveTaskExecutionCount = 0;
}

protected List<String> getValidButtons(String signal, String button) {

  if (button == null) {
    return new ArrayList<>();
  }

  List<String> buttons = Arrays.asList(button.split(","));
  if (buttons.contains(signal)) {
    return buttons;
  }
  return null;
}

def validate(self):
	self._assignment = None
	if self.is_new():
		if self.assigned_by == self.allocated_to:
			assignment_message = frappe._("{0} self assigned this task: {1}").format(
				get_fullname(self.assigned_by), self.description
			)
		else:
			assignment_message = frappe._("{0} assigned {1}: {2}").format(
				get_fullname(self.assigned_by), get_fullname(self.allocated_to), self.description
			)

		self._assignment = {"text": assignment_message, "comment_type": "Assigned"}

	else:
		# NOTE the previous value is only available in validate method
		if self.get_db_value("status") != self.status:
			if self.allocated_to == frappe.session.user:
				removal_message = frappe._("{0} removed their assignment.").format(
					get_fullname(frappe.session.user)
				)
			else:
				removal_message = frappe._("Assignment of {0} removed by {1}").format(
					get_fullname(self.allocated_to), get_fullname(frappe.session.user)
				)

			self._assignment = {"text": removal_message, "comment_type": "Assignment Completed"}

def on_update(self):
	if self._assignment:
		self.add_assign_comment(**self._assignment)

	self.update_in_reference()

def on_trash(self):
	self.delete_communication_links()
	self.update_in_reference()

def add_assign_comment(self, text, comment_type):
	if not (self.reference_type and self.reference_name):
		return

	frappe.get_doc(self.reference_type, self.reference_name).add_comment(comment_type, text)

def update_in_reference(self):
	if not (self.reference_type and self.reference_name):
		return

	try:
		assignments = frappe.db.get_values(
			"ToDo",
			{
				"reference_type": self.reference_type,
				"reference_name": str(self.reference_name),
				"status": ("not in", ("Cancelled", "Closed")),
				"allocated_to": ("is", "set"),
			},
			"allocated_to",
			pluck=True,
			for_update=True,
		)
		assignments.reverse()

		if frappe.get_meta(self.reference_type).issingle:
			frappe.db.set_single_value(
				self.reference_type,
				"_assign",
				json.dumps(assignments) if assignments else "",
				update_modified=False,
			)
		else:
			frappe.db.set_value(
				self.reference_type,
				self.reference_name,
				"_assign",
				json.dumps(assignments) if assignments else "",
				update_modified=False,
			)

	except Exception as e:
		if frappe.db.is_table_missing(e) and frappe.flags.in_install:
			# no table
			return

		elif frappe.db.is_missing_column(e):
			from frappe.database.schema import add_column

			add_column(self.reference_type, "_assign", "Text")
			self.update_in_reference()

		else:
			raise

def delete_communication_links(self):
	# unlink todo from linked comments
	return frappe.db.delete("Communication Link", {"link_doctype": self.doctype, "link_name": self.name})

def validate(self):
	self.validate_document_types()
	self.validate_assignment_days()

def validate_document_types(self):
	if self.document_type == "ToDo":
		frappe.throw(
			_("Assignment Rule is not allowed on document type {0}").format(frappe.bold(_("ToDo")))
		)

def validate_assignment_days(self):
	assignment_days = self.get_assignment_days()
	if len(set(assignment_days)) != len(assignment_days):
		frappe.throw(
			_("The following Assignment Days have been repeated: {0}").format(
				comma_and([_(day) for day in get_repeated(assignment_days)], add_quotes=False)
			)
		)

def apply_unassign(self, doc, assignments):
	if self.unassign_condition and self.name in [d.assignment_rule for d in assignments]:
		return self.clear_assignment(doc)

	return False

def apply_assign(self, doc):
	if self.safe_eval("assign_condition", doc):
		return self.do_assignment(doc)

def clear_assignment(self, doc):
	"""Clear assignments"""
	if self.safe_eval("unassign_condition", doc):
		return assign_to.clear(doc.get("doctype"), doc.get("name"), ignore_permissions=True)

def close_assignments(self, doc):
	"""Close assignments"""
	if self.safe_eval("close_condition", doc):
		return assign_to.close_all_assignments(
			doc.get("doctype"), doc.get("name"), ignore_permissions=True
		)

def get_user(self, doc):
	"""
	Get the next user for assignment
	"""
	if self.rule == "Round Robin":
		return self.get_user_round_robin()
	elif self.rule == "Load Balancing":
		return self.get_user_load_balancing()
	elif self.rule == "Based on Field":
		return self.get_user_based_on_field(doc)
	elif self.rule == "Weighted Distribution":
		return self.get_weighted_user()

def get_user_load_balancing(self):
	"""Assign to the user with least number of open assignments"""
	counts = [
		dict(
			user=d.user,
			count=frappe.db.count(
				"ToDo",
				dict(
					reference_type=self.document_type,
					allocated_to=d.user,
					status="Open",
				),
			),
		)
		for d in self.users
	]
	# sort by dict value
	sorted_counts = sorted(counts, key=lambda k: k["count"])

	# pick the first user
	return sorted_counts[0].get("user")

def get_user_based_on_field(self, doc):
	val = doc.get(self.field)
	if frappe.db.exists("User", val):
		return val

def get_weighted_user(self):
	"""
	Assign to the user based on weights assigned to users
	Each rule maintains its own counter.
	"""
	users = [(d.user, d.weight or 1) for d in self.weighted_users if d.user]
	if not users:
		return None

	total_weight = sum(weight for _, weight in users)
	if total_weight <= 0:
		return None

	current_index = (
		frappe.db.get_value("Assignment Rule", self.name, "current_index", for_update=True) or 0
	)
	slot = current_index % total_weight

	cumulative_weight = 0
	for user, weight in users:
		cumulative_weight += weight
		if slot < cumulative_weight:
			frappe.db.set_value(
				"Assignment Rule", self.name, "current_index", current_index + 1, update_modified=False
			)
			return user

def safe_eval(self, fieldname, doc):
	try:
		if self.get(fieldname):
			return frappe.safe_eval(self.get(fieldname), None, doc)
	except Exception as e:
		# when assignment fails, don't block the document as it may be
		# a part of the email pulling
		frappe.msgprint(frappe._("Auto assignment failed: {0}").format(str(e)), indicator="orange")

	return False

def get_assignments(doc) -> list[dict]:
	return frappe.get_all(
		"ToDo",
		fields=["name", "assignment_rule"],
		filters=dict(
			reference_type=doc.get("doctype"), reference_name=str(doc.get("name")), status=("!=", "Cancelled")
		),
		limit=5,
	)

def bulk_apply(doctype: str, docnames: str | list[str]):
	docnames = frappe.parse_json(docnames)
	background = len(docnames) > 5

	for name in docnames:
		if background:
			frappe.enqueue(
				"frappe.automation.doctype.assignment_rule.assignment_rule.apply",
				doc=None,
				doctype=doctype,
				name=name,
			)
		else:
			apply(doctype=doctype, name=name)

def reopen_closed_assignment(doc):
	todo_list = frappe.get_all(
		"ToDo",
		filters={
			"reference_type": doc.doctype,
			"reference_name": str(doc.name),
			"status": "Closed",
		},
		pluck="name",
	)

	for todo in todo_list:
		todo_doc = frappe.get_doc("ToDo", todo)
		todo_doc.status = "Open"
		todo_doc.save(ignore_permissions=True)

	return bool(todo_list)

def apply(doc=None, method=None, doctype=None, name=None):
	doctype = doctype or doc.doctype

	skip_assignment_rules = (
		frappe.flags.in_patch
		or frappe.flags.in_install
		or frappe.flags.in_setup_wizard
		or doctype in log_types
	)

	if skip_assignment_rules:
		return

	if not doc and doctype and name:
		doc = frappe.get_doc(doctype, name)
		doc.check_permission()

	assignment_rules = get_doctype_map(
		"Assignment Rule",
		doc.doctype,
		filters={"document_type": doc.doctype, "disabled": 0},
		order_by="priority desc",
	)

	# multiple auto assigns
	assignment_rule_docs: list[AssignmentRule] = [
		frappe.get_cached_doc("Assignment Rule", d.get("name")) for d in assignment_rules
	]

	if not assignment_rule_docs:
		return

	doc = doc.as_dict()
	assignments = get_assignments(doc)

	clear = True  # are all assignments cleared
	new_apply = False  # are new assignments applied

	if assignments:
		# first unassign
		# use case, there are separate groups to be assigned for say L1 and L2,
		# so when the value switches from L1 to L2, L1 team must be unassigned, then L2 can be assigned.
		clear = False
		for assignment_rule in assignment_rule_docs:
			if assignment_rule.is_rule_not_applicable_today():
				continue

			clear = assignment_rule.apply_unassign(doc, assignments)
			if clear:
				break

	# apply rule only if there are no existing assignments
	if clear:
		for assignment_rule in assignment_rule_docs:
			if assignment_rule.is_rule_not_applicable_today():
				continue

			new_apply = assignment_rule.apply_assign(doc)
			if new_apply:
				break

	# apply close rule only if assignments exists
	assignments = get_assignments(doc)

	if assignments:
		closed_assignments_checked = False
		for assignment_rule in assignment_rule_docs:
			if assignment_rule.is_rule_not_applicable_today():
				continue

			if not new_apply:
				# only reopen if close condition is not satisfied
				to_close_todos = assignment_rule.safe_eval("close_condition", doc)

				if to_close_todos:
					# close todo status
					todos_to_close = frappe.get_all(
						"ToDo",
						filters={
							"reference_type": doc.doctype,
							"reference_name": str(doc.name),
						},
						pluck="name",
					)

					for todo in todos_to_close:
						_todo = frappe.get_doc("ToDo", todo)
						_todo.status = "Closed"
						_todo.save(ignore_permissions=True)
					break

				elif not closed_assignments_checked:
					closed_assignments_checked = True
					reopened = reopen_closed_assignment(doc)
					if reopened:
						break

			assignment_rule.close_assignments(doc)

def get_repeated(values: Iterable) -> list:
	unique = set()
	repeated = set()

	for value in values:
		if value in unique:
			repeated.add(value)
		else:
			unique.add(value)

	return [str(x) for x in repeated]

def _compute_can_write(self):
    valid_records = self._filtered_access('write')
    for record in self:
        record.can_write = record in valid_records

def create(self, vals_list):
    activities = super(MailActivity, self).create(vals_list)

    # find partners related to responsible users, separate readable from unreadable
    if any(user != self.env.user for user in activities.user_id):
        user_partners = activities.user_id.partner_id
        readable_user_partners = user_partners._filtered_access('read')
    else:
        readable_user_partners = self.env.user.partner_id

    # when creating activities for other: send a notification to assigned user;
    if self.env.context.get('mail_activity_quick_update'):
        activities_to_notify = self.env['mail.activity']
    else:
        activities_to_notify = activities.filtered(lambda act: act.user_id != self.env.user)
    if activities_to_notify:
        to_sudo = activities_to_notify.filtered(lambda act: act.user_id.partner_id not in readable_user_partners)
        other = activities_to_notify - to_sudo
        to_sudo.sudo().action_notify()
        other.action_notify()

    # subscribe (batch by model and user to speedup)
    for model, activity_data in activities.filtered('res_model')._classify_by_model().items():
        per_user = defaultdict(set)
        for activity in activity_data['activities'].filtered(lambda act: act.user_id):
            per_user[activity.user_id].add(activity.res_id)
        for user, res_ids in per_user.items():
            pids = user.partner_id.ids if user.partner_id in readable_user_partners else user.sudo().partner_id.ids
            self.env[model].browse(res_ids).message_subscribe(partner_ids=pids)

    # send notifications about activity creation
    today = fields.Date.context_today(activities)
    todo_activities = activities.filtered(lambda act: act.active and act.date_deadline <= today and act.user_id)
    if todo_activities:
        for user, user_activities in todo_activities.grouped('user_id').items():
            user._bus_send("mail.activity/updated", {"activity_created": True, "count_diff": len(user_activities)})
    return activities

def write(self, vals):
    today = fields.Date.context_today(self)

    def get_user_todo_activity_count(activities):
        return {
            user: len(user_activities.filtered(lambda a: a.active and a.date_deadline <= today))
            for user, user_activities in activities.grouped('user_id').items()
            if user
        }

    original_user_todo_activity_count = None
    if 'date_deadline' in vals or 'active' in vals or 'user_id' in vals:
        original_user_todo_activity_count = get_user_todo_activity_count(self)

    new_user_activities = self.env['mail.activity']
    if vals.get('user_id'):
        new_user_activities = self.filtered(lambda activity: activity.user_id.id != vals.get('user_id'))

    res = super().write(vals)

    # notify new responsibles
    if vals.get('user_id'):
        if vals['user_id'] != self.env.uid:
            if not self.env.context.get('mail_activity_quick_update', False):
                new_user_activities.action_notify()
        new_user = self.env['res.users'].browse(vals['user_id'])
        for res_model, model_activities in new_user_activities.filtered(
            lambda activity: activity.res_model and activity.res_id
        ).grouped('res_model').items():
            res_ids = OrderedSet(id_ for id_ in model_activities.mapped('res_id') if id_)
            self.env[res_model].browse(res_ids).message_subscribe(partner_ids=new_user.partner_id.ids)

    # update activity counter
    if original_user_todo_activity_count is not None:
        new_user_todo_activity_count = get_user_todo_activity_count(self)
        users = new_user_todo_activity_count.keys() | original_user_todo_activity_count.keys()
        # sorting users by id to ensure deterministic order because keys views are set-like
        for user in sorted(users, key=lambda user: user.id):
            count_diff = new_user_todo_activity_count.get(user, 0) - original_user_todo_activity_count.get(user, 0)
            if count_diff > 0:
                user._bus_send("mail.activity/updated", {"activity_created": True, "count_diff": count_diff})
            elif count_diff < 0:
                user._bus_send("mail.activity/updated", {"activity_deleted": True, "count_diff": count_diff})

    return res

def unlink(self):
    todo_activities = self.filtered(lambda act: act.active and act.date_deadline <= fields.Date.today() and act.user_id)
    if todo_activities:
        for user, user_activities in todo_activities.grouped('user_id').items():
            user._bus_send("mail.activity/updated", {"activity_deleted": True, "count_diff": -len(user_activities)})
    return super().unlink()

def action_done(self):
    """ Wrapper without feedback because web button add context as
    parameter, therefore setting context to feedback """
    return self.filtered(lambda r: r.active).action_feedback()

def action_feedback(self, feedback=False, attachment_ids=None):
    messages = self.with_context(
        clean_context(self.env.context)
    )._action_done(feedback=feedback, attachment_ids=attachment_ids)
    return messages[0].id if messages else False

def action_done_schedule_next(self):
    """ Wrapper without feedback because web button add context as
    parameter, therefore setting context to feedback """
    return self.action_feedback_schedule_next()

def _classify_by_model(self):
    """ To ease batch computation of various activities related methods they
    are classified by model. Activities not linked to a valid record through
    res_model / res_id are ignored.

    :returns: for each model having at least one activity in self, have
      a sub-dict containing

        * activities: activities related to that model;
        * record IDs: record linked to the activities of that model, in same
          order;
    :rtype: dict
    """
    data_by_model = {}
    for activity in self.filtered(lambda act: act.res_model and act.res_id):
        if activity.res_model not in data_by_model:
            data_by_model[activity.res_model] = {
                'activities': self.env['mail.activity'],
                'record_ids': [],
            }
        data_by_model[activity.res_model]['activities'] += activity
        data_by_model[activity.res_model]['record_ids'].append(activity.res_id)
    return data_by_model

def _get_activity_done_message_extra_values(self, activity):
    """To ease passing new values to the mail.message_activity_done chatter template."""
    return {}

def validate(cls, works):
    super().validate(works)
    for work in works:
        work.check_work_progress()

def copy(cls, project_works, default=None):
    pool = Pool()
    WorkStatus = pool.get('project.work.status')
    if default is None:
        default = {}
    else:
        default = default.copy()
    default.setdefault('number')
    default.setdefault('progress', None)
    default.setdefault(
        'status', lambda data: WorkStatus.get_default_status(data['type']))
    new_works = super().copy(project_works, default=default)
    with cls.bulk_save() as save:
        for work, new_work in zip(project_works, new_works):
            if work.timesheet_available:
                new_work.timesheet_available = work.timesheet_available
                new_work.timesheet_start_date = work.timesheet_start_date
                new_work.timesheet_end_date = work.timesheet_end_date
                save.push(new_work)
    return new_works

@Override
@Transactional(rollbackOn = Exception.class)
public void updateTasksBatchStatus(List<Pair<String, String>> taskBatch, String status) {

  if (taskBatch == null || taskBatch.isEmpty()) {
    return;
  }

  StringBuilder sql = new StringBuilder();
  sql.append("UPDATE team_task t ");
  sql.append("SET status = :status ");
  sql.append("FROM (VALUES ");

  for (int i = 0; i < taskBatch.size(); i++) {
    sql.append("(:proc").append(i).append(", :task").append(i).append(")");
    if (i < taskBatch.size() - 1) {
      sql.append(", ");
    }
  }

  sql.append(") AS pairs(process_id, task_name) ");
  sql.append("WHERE t.status != :status ");
  sql.append("AND t.related_process_instance IN (");
  sql.append("SELECT id FROM studio_wkf_instance rpi WHERE rpi.instance_id = pairs.process_id");
  sql.append(") ");
  sql.append("AND t.wkf_task_config IN (");
  sql.append("SELECT id FROM studio_wkf_task_config wtc WHERE wtc.name = pairs.task_name");
  sql.append(")");

  jakarta.persistence.Query query = JPA.em().createNativeQuery(sql.toString());
  query.setParameter("status", status);

  for (int i = 0; i < taskBatch.size(); i++) {
    query.setParameter("proc" + i, taskBatch.get(i).getLeft());
    query.setParameter("task" + i, taskBatch.get(i).getRight());
  }

  query.executeUpdate();

  JPA.em().clear();
}

private FullContext createFullContext(String processInstanceId) throws ClassNotFoundException {

  WkfInstance instance =
      wkfInstanceRepository.all().filter("self.instanceId = ?", processInstanceId).fetchOne();

  if (instance == null) {
    throw new IllegalArgumentException(
        String.format(I18n.get(BpmExceptionMessage.NO_WFK_INSTANCE_FOUND), processInstanceId));
  }

  List<WkfProcessConfig> wkfProcessConfigs = instance.getWkfProcess().getWkfProcessConfigList();
  if (wkfProcessConfigs == null || wkfProcessConfigs.isEmpty()) {
    throw new IllegalStateException(
        String.format(
            I18n.get(BpmExceptionMessage.NO_PROCESS_CONFIGURATION_FOUND), processInstanceId));
  }

  WkfProcessConfig firstConfig = wkfProcessConfigs.getFirst();

  String classFullName;
  if (firstConfig.getMetaModel() != null) {
    classFullName = firstConfig.getMetaModel().getFullName();
  } else if (firstConfig.getMetaJsonModel() != null) {
    classFullName = MetaJsonRecord.class.getName();
  } else {
    throw new IllegalStateException(
        String.format(
            I18n.get(BpmExceptionMessage.NO_PROCESS_CONFIGURATION_FOUND), processInstanceId));
  }

  Class<? extends Model> klass = Class.forName(classFullName).asSubclass(Model.class);

  Model model =
      Query.of(klass)
          .filter("self.processInstanceId = :instanceId")
          .bind("instanceId", instance.getInstanceId())
          .fetchOne();

  if (model == null) {
    throw new RuntimeException(
        String.format(
            I18n.get(BpmExceptionMessage.MODEL_NOT_FOUND), processInstanceId, classFullName));
  }

  return WkfContextHelper.create(model);
}

